// v3.4: merge user-added discovery wallets (from previous sessions)
(function loadDiscoveryAdded() {
  try {
    const raw = localStorage.getItem(DISCOVERY_ADDED_STORE);
    if (!raw) return;
    const added = JSON.parse(raw);
    if (!Array.isArray(added)) return;
    for (const w of added) {
      if (!w || !w.address || !BASE58_RE.test(w.address)) continue;
      if (WATCHLIST.some(x => x.address === w.address)) continue;
      WATCHLIST.push({ label: w.label || ('DISCOVERED_' + w.address.slice(1, 6)), address: w.address, cat: w.cat || 'whale' });
    }
  } catch (e) { /* silent */ }
})();

// v16.8: merge the SHARED HVT ROSTER. The live wall watched 76 targets and this
// console watched 149, overlapping on only 45 — so a wallet could drain to
// nothing on the HVT board without the morning brief ever looking at it, and a
// brief headline could be absent from the board entirely. src/shared/
// hvt-roster.js is the union; this adds whatever it carries that the hard-coded
// WATCHLIST above does not already have. Additive only — nothing is removed, and
// a roster wallet with a sourced identity keeps the identity registry as the one
// thing allowed to NAME it.
(function mergeSharedRoster() {
  try {
    const R = (typeof window !== 'undefined') && window.SW_HVT_ROSTER;
    if (!R || !Array.isArray(R.targets)) return;
    const CAT = { EXCH: 'exchange', RIPPLE: 'escrow', HVT: 'whale' };
    let added = 0;
    for (const t of R.targets) {
      if (!t || !t.address || !BASE58_RE.test(t.address)) continue;
      if (WATCHLIST.some(x => x.address === t.address)) continue;
      WATCHLIST.push({
        // v16.8.1: was `t.handle || 'ROSTER_' + addr.slice(1,7)`. handle is null
        // for every target that came from the live wall, so 30 wallets — Gate.io,
        // Bitfinex, Gemini among them — got a made-up ROSTER_xxxxxx handle even
        // though the roster carried their real name the whole time, and any code
        // path printing KNOWN[addr].label raw leaked it into the report. The
        // roster's own label is the right fallback: a registry NAME when it has
        // one, the wall's own label otherwise.
        label: t.handle || t.label || ('ROSTER_' + t.address.slice(1, 7)),
        address: t.address,
        cat: CAT[t.type] || 'whale'
      });
      added++;
    }
    if (added) try { console.log('[HVT-ROSTER] merged ' + added + ' shared target(s) into the watch list'); } catch (_) {}
  } catch (_) { /* the console must still boot without the roster */ }
})();

const KNOWN = Object.fromEntries(WATCHLIST.map(w => [w.address, w]));

// ── v3.8: WALLET GROUP CLASSIFIER ──
// Groups are functional buckets for the consolidated XRP main report.
// More granular than `cat` (which only has 3 values: exchange/whale/escrow).
function getWalletGroup(labelOrAddress) {
  const label = (KNOWN[labelOrAddress]?.label || labelOrAddress || '').toString();
  if (/^ARTHUR_BRITTO/i.test(label)) return 'founder';
  if (/^CHRIS_LARSEN/i.test(label))  return 'founder';
  if (/^RIPPLE_/i.test(label))       return 'ripple_corp';
  // v3.10: linked multi-sig cluster (INST_MSIG_*) — separate from regular institutional custody
  if (/^INST_MSIG/i.test(label))     return 'msig_cluster';
  if (/^INST_CUSTODY/i.test(label))  return 'institutional';
  if (/^DORMANT/i.test(label))       return 'dormant';
  if (/^GENESIS_WHALE/i.test(label)) return 'genesis_whale';
  if (/^MM_/i.test(label))           return 'market_maker';        // v3.10: market makers
  if (/^OTC_WHALE/i.test(label))     return 'whale';               // OTC reserves classified as whales
  if (/^(BINANCE|COINBASE|UPBIT|UPHOLD|HUOBI|BITSTAMP|BITHUMB|BITBANK|BITFLYER|COINCHECK|COINONE|BYBIT|OKX|CRYPTO_COM|ETORO|BITRUE|INDODAX)/i.test(label)) return 'exchange';
  return 'whale';
}
const GROUP_LABELS = {
  founder:        'FOUNDER WALLETS',
  ripple_corp:    'RIPPLE CORPORATE / ESCROW',
  exchange:       'EXCHANGE CUSTODY',
  institutional:  'INSTITUTIONAL CUSTODY',
  msig_cluster:   'LINKED MULTI-SIG CLUSTER',    // v3.10
  market_maker:   'MARKET MAKERS / BOTS',        // v3.10
  dormant:        'DORMANT WHALES',
  genesis_whale:  'GENESIS-ERA WHALES',
  whale:          'PRIVATE WHALES'
};

