// ── DOM + FORMAT HELPERS ───────────────────────────────────────
const $ = id => document.getElementById(id);
function setText(id, val) { const el = $(id); if (el) el.textContent = String(val ?? ''); }
function setBar(id, p, cls) {
  const el = $(id); if (!el) return;
  el.style.width = Math.max(0, Math.min(100, p)) + '%';
  el.className = 'hud-bar' + (cls ? ' ' + cls : '');
}
const n = v => Number(v) || 0;
const drops = v => n(v) / 1e6;
const rip = secs => new Date((n(secs) + RIPPLE_EPOCH) * 1000).toISOString();
const today = () => new Date().toISOString().slice(0, 10);
const nowUTC = () => new Date().toUTCString().slice(17, 25) + ' UTC';
const ca = a => a ? a.slice(0, 6) + '…' + a.slice(-4) : '—';
function fmt(v, d = 2) {
  v = n(v);
  if (Math.abs(v) >= 1e9) return (v / 1e9).toFixed(2) + 'B';
  if (Math.abs(v) >= 1e6) return (v / 1e6).toFixed(2) + 'M';
  if (Math.abs(v) >= 1e3) return (v / 1e3).toFixed(2) + 'K';
  return v.toFixed(d);
}
function usd(v) { v = n(v); return v ? '$' + fmt(v, 0) : '—'; }
function pct(v) { const d = n(v); return (d >= 0 ? '+' : '') + d.toFixed(2) + '%'; }
const delay = ms => new Promise(r => setTimeout(r, ms));

// ── READER-FACING WALLET NAMES (evidence lines) ─────────────────
// The evidence sections (LARGE MOVES, holder dominance, pattern memory, the
// ledger paragraph) were printing the WATCHLIST's internal handles straight
// through: "LARGE_RECV_rDAE53 → WHALE_RECV_rfQ9Ec". Those handles are keys we
// made up to track a wallet; they are not names, they mean nothing to a reader,
// and worse, that address IS in the identity registry as Binance — so the app
// knew the answer and printed a bookkeeping string instead.
//
// _swWho() is the single resolver every reader-facing line goes through:
//   1. src/shared/wallet-identities.js has a sourced identity  → NAME it
//   2. on the watch list, no identity                          → describe the
//      role + short address ("whale receiver rfQ9Ec…"), never the handle
//   3. neither                                                 → short address
// Rule 1 is the ONLY path that may produce a real-world name, which is what
// keeps assertLabelProvenance satisfiable: every name in the report body traces
// to a committed registry entry. Everything else stays behavioural.
const _SW_ROLE_BY_CAT = {
  exchange:                   'exchange wallet',
  escrow:                     'escrow wallet',
  whale:                      'whale wallet',
  next_hop_splitter:          'routing wallet',
  discovered_whale:           'whale wallet',
  discovered_receiver:        'receiving wallet',
  discovered_unknown_highval: 'high-value wallet',
  discovered:                 'watched wallet'
};
// Longest prefix first — WHALE_RECV_ must win over WHALE_.
const _SW_ROLE_BY_HANDLE = [
  ['EXOUT_RECV_',  'exchange-outflow receiver'],
  ['WHALE_RECV_',  'whale receiver'],
  ['LARGE_RECV_',  'large-transfer receiver'],
  ['NEXTHOP_',     'next-hop wallet'],
  ['SPLITTER_',    'routing wallet'],
  ['HIGHVAL_',     'high-value wallet'],
  ['DISCOVERED_',  'watched wallet'],
  ['WHALE_',       'whale wallet'],
  ['RIPPLE_',      'escrow wallet']
];
// An internal handle: all-caps/underscore bookkeeping, e.g. BINANCE_HOT,
// WHALE_RECV_rfQ9Ec, RIPPLE_1.3B. Never printed to a reader.
const _SW_HANDLE_RE = /^[A-Z][A-Z0-9_.]*(_[A-Za-z0-9]+)?$/;
// A raw address, or one already shortened for display ("rDAE53…JPxr"). Either
// way it is an address, not a name, and belongs in the address branch.
const _SW_ADDRISH_RE = /^r[1-9A-HJ-NP-Za-km-z]{4,}(…|\.\.\.|$)/;
function _swIsHandle(s) {
  return typeof s === 'string' && _SW_HANDLE_RE.test(s) && /[_]/.test(s);
}
function _swRoleFromHandle(h) {
  for (let i = 0; i < _SW_ROLE_BY_HANDLE.length; i++) {
    if (h.indexOf(_SW_ROLE_BY_HANDLE[i][0]) === 0) return _SW_ROLE_BY_HANDLE[i][1];
  }
  return null;
}
function _swIdentity(addr) {
  try {
    const R = (typeof window !== 'undefined') && window.SW_WALLET_IDENTITIES;
    return (R && addr && R[addr]) || null;
  } catch (_) { return null; }
}
function _swWatched(addr) {
  try {
    if (addr && typeof KNOWN !== 'undefined' && KNOWN && KNOWN[addr]) return KNOWN[addr];
  } catch (_) {}
  return null;
}
// addr        — the XRPL address, when the caller has it (always prefer this)
// fallbackLbl — whatever label the caller was going to print (may be a handle,
//               a pre-shortened address, or 'UNKNOWN')
// opts.bare   — return just the short address for tier 3, with no "unidentified
//               wallet" prefix (for lines that already say what the slot is)
function _swWho(addr, fallbackLbl, opts) {
  opts = opts || {};
  const short = a => (typeof a === 'string' && a.length > 12) ? ca(a) : (a || '');
  const ident = _swIdentity(addr);
  if (ident && ident.name) return ident.name;

  const w = _swWatched(addr);
  const handle = (w && w.label) || (_swIsHandle(fallbackLbl) ? fallbackLbl : null);
  let role = (w && w.cat) ? _SW_ROLE_BY_CAT[w.cat] : null;
  if (!role && handle) role = _swRoleFromHandle(handle);
  if (role) {
    const tail = addr ? short(addr) : _swHandleTail(handle);
    return tail ? role + ' ' + tail : role;
  }
  // A label that is already plain human text (not one of our handles, not a raw
  // or pre-shortened address, not the placeholder) is worth keeping as-is.
  if (fallbackLbl && !_swIsHandle(fallbackLbl) && fallbackLbl !== 'UNKNOWN' &&
      !_SW_ADDRISH_RE.test(fallbackLbl)) {
    return fallbackLbl;
  }
  if (addr) return opts.bare ? short(addr) : 'unidentified wallet ' + short(addr);
  if (typeof fallbackLbl === 'string' && fallbackLbl.indexOf('…') > 0) {
    return opts.bare ? fallbackLbl : 'unidentified wallet ' + fallbackLbl;
  }
  return 'an unidentified wallet';
}
// "WHALE_RECV_rfQ9Ec" → "rfQ9Ec…" — the handle's trailing address fragment is
// the only part of it that carries information, and it's what distinguishes two
// wallets with the same role when we don't have the full address.
function _swHandleTail(h) {
  if (!h) return '';
  const m = /(r[1-9A-HJ-NP-Za-km-z]{4,})$/.exec(h);
  return m ? m[1] + '…' : '';
}
// A list of addresses as reader-facing names, with repeats collapsed. A cluster
// can hold several addresses belonging to the SAME identity — once they resolve
// through the registry, "Binance + Binance + Binance" is what you'd get without
// this, which reads like three parties instead of one entity's three wallets.
function _swWhoList(addrs, opts) {
  opts = opts || {};
  const order = [], count = {};
  (addrs || []).forEach(a => {
    const nm = _swWho(a, null, { bare: true });
    if (count[nm] == null) { count[nm] = 0; order.push(nm); }
    count[nm]++;
  });
  const out = order.map(nm => count[nm] > 1 ? nm + ' ×' + count[nm] : nm);
  const cap = opts.max || 0;
  if (cap && out.length > cap) return out.slice(0, cap).concat('+' + (out.length - cap) + ' more');
  return out;
}
// Machine classification codes, said in English. The code stays available in the
// JSON payload; the prose shouldn't make a reader decode SCREAMING_SNAKE_CASE.
const _SW_CLS_PHRASE = {
  UNKNOWN_FLOW:                   'unclassified flow',
  WATCHLIST_INTERNAL:             'watchlist-internal transfer',
  EXCHANGE_OUTFLOW:               'exchange outflow',
  EXCHANGE_INFLOW:                'exchange inflow',
  WHALE_TO_UNKNOWN:               'whale to unidentified wallet',
  ESCROW_FLOW:                    'escrow flow',
  FRESH_ACCOUNT_RECEIVER:         'brand-new account taking size',
  NEXT_HOP_HOLDING:               'holding',
  NEXT_HOP_FORWARDING_DETECTED:   'forwarding onward',
  NEXT_HOP_SPLITTER:              'splitting onward',
  RECEIVER_HOLDING_UNKNOWN:       'holding, purpose unknown',
  LARGE_TRANSFER_RECEIVER:        'large-transfer receiver',
  SHARED_COUNTERPARTY:            'shared counterparty',
  LOW_VALUE_NOISE:                'low-value noise'
};
function _swCls(code) {
  if (!code) return 'unclassified flow';
  return _SW_CLS_PHRASE[code] || String(code).toLowerCase().replace(/_/g, ' ');
}
// Confidence reads as a plain word in prose; the bracket already marks it out.
function _swConf(c) { return String(c || 'MEDIUM').toLowerCase(); }
if (typeof window !== 'undefined') {
  window._swWho = _swWho; window._swCls = _swCls; window._swConf = _swConf;
}

// ── LOGGING ────────────────────────────────────────────────────
function log(msg) {
  const el = $('statusFeed'); if (!el) return;
  el.textContent += '\n' + msg;
  el.scrollTop = el.scrollHeight;
}
function elog(label, err) {
  const el = $('errorLog'); if (!el) return;
  const m = '[' + new Date().toISOString().slice(11, 19) + '] ' + label + (err ? ': ' + (err.message || err) : '');
  if (el.textContent === 'No errors yet.') el.textContent = '';
  el.textContent += m + '\n';
}
function resetLog() { const el = $('statusFeed'); if (el) el.textContent = ''; }
// v3.12: SMOOTH PERCENT COUNTER
// ── v3.22 HUD ARC PROGRESS ──────────────────────────────────────
// shadowSay drives the SVG arc fill + phase bar in addition to the
// existing text labels. Arc uses CSS transition for smooth movement;
// pct text is still rAF-animated for the counting effect.
// Phase mapping converts engine phase labels → 6 HUD segments.

const _pctState = { current: 0, target: 0, animating: false, lastUpdate: 0, active: false };

function _ensureAnim() {
  if (!_pctState.animating) {
    _pctState.animating = true;
    _pctState.lastUpdate = performance.now();
    requestAnimationFrame(_animatePct);
  }
}

// Arc circumference = 2π × 46 ≈ 289.03
const HUD_ARC_CIRC = 289.03;

// Map engine phase identifiers → one of the 6 HUD phase labels
const HUD_PHASE_MAP = {
  BOOT:       'INIT',
  INIT:       'INIT',
  MARKET:     'INIT',
  BALANCES:   'LEDGER',
  WALLETS:    'LEDGER',
  LEDGER:     'LEDGER',
  TX_SCAN:    'FLOW',
  FLOW:       'FLOW',
  TX:         'FLOW',
  OFFERS:     'DEX',
  AMM:        'DEX',
  DEX:        'DEX',
  MEMORY:     'MEMORY',
  ANALYSIS:   'MEMORY',
  PATTERN:    'MEMORY',
  DISCOVERY:  'MEMORY',
  SEAL:       'SEAL',
  BUILDING:   'SEAL',
  DONE:       'SEAL',
  SEALED:     'SEAL',
  WAITING:    'INIT',
  SCANNING:   'LEDGER',
  ERROR:      'SEAL'
};

// Phase order for the "done" coloring
const HUD_PHASE_ORDER = ['INIT','LEDGER','FLOW','DEX','MEMORY','SEAL'];

// Update the SVG arc fill based on current pct
function _updateArc(pct) {
  // Drives the scan-monitor progress bar (was the circular SVG arc).
  const fill = document.getElementById('scanBarFill');
  if (!fill) return;
  fill.style.width = Math.max(0, Math.min(100, pct)).toFixed(2) + '%';
}

// Update the phase bar: mark active + done phases
function _updatePhaseBar(hudPhase) {
  const bar = document.getElementById('hudPhaseBar');
  if (!bar || !hudPhase) return;
  const activeIdx = HUD_PHASE_ORDER.indexOf(hudPhase);
  bar.querySelectorAll('.hud-ps').forEach((el, i) => {
    el.classList.remove('active','done');
    if (i < activeIdx)  el.classList.add('done');
    if (i === activeIdx) el.classList.add('active');
  });
}

function _animatePct() {
  const now = performance.now();
  const dt = Math.min(120, now - (_pctState.lastUpdate || now));
  _pctState.lastUpdate = now;

  // During stalls between phases, creep gently past the last reported target so
  // the dial never looks frozen — but never past 99 until the scan finishes.
  let ceil = _pctState.target;
  const stalled = _pctState.current >= _pctState.target - 0.5;
  if (stalled && _pctState.active && _pctState.target < 99) {
    ceil = Math.min(99, _pctState.target + 7);
  }

  const gap = ceil - _pctState.current;
  if (gap > 0.05) {
    // Exponential ease-out: quick catch-up on real jumps, slow drift on creep.
    const k = stalled ? 0.0018 : 0.011; // per ms — time constant ≈ 550ms / 90ms
    _pctState.current = Math.min(ceil, _pctState.current + gap * (1 - Math.exp(-k * dt)));
    const shown = Math.floor(_pctState.current);
    const el = document.getElementById('orbPct');
    if (el && el.textContent !== shown + '%') el.textContent = shown + '%';
    _updateArc(_pctState.current);
  }

  // Keep the loop alive while a scan is active or we're still easing to target.
  if (_pctState.active || _pctState.current < _pctState.target - 0.05) {
    requestAnimationFrame(_animatePct);
  } else {
    _pctState.animating = false;
  }
}

// Legacy shadowSay phase → XAI mobile-HUD phase (ceilings ascend). Bridges the
// two progress systems so the mobile gauge actually advances during a scan.
const XAI_PHASE_BRIDGE = {
  BOOT: 'INIT', INIT: 'INIT', MARKET: 'INIT', WAITING: 'INIT', SCANNING: 'INIT',
  BALANCES: 'LEDGER', LEDGER: 'LEDGER',
  WALLETS: 'WALLET_PROGRESS',
  TX_SCAN: 'BALANCE',
  ESCROW: 'FLOW', FLOW: 'FLOW', TX: 'FLOW',
  OFFERS: 'DISCOVERY', AMM: 'DISCOVERY', DEX: 'DISCOVERY',
  MEMORY: 'DISCOVERY', ANALYSIS: 'DISCOVERY', PATTERN: 'DISCOVERY', DISCOVERY: 'DISCOVERY',
  SEAL: 'REPORTING', BUILDING: 'REPORTING',
  SEALED: 'SEALED', DONE: 'DONE', READY: 'DONE', ERROR: 'FAILED'
};

function shadowSay(status, phase, pctVal) {
  setText('orbStatus', status);
  const rawPhase = (phase || 'SCANNING').toUpperCase();
  setText('orbPhase', rawPhase);

  // Map engine phase → HUD segment and update phase bar
  const hudPhase = HUD_PHASE_MAP[rawPhase] || 'INIT';
  _updatePhaseBar(hudPhase);

  const target = Math.round(pctVal);
  if (target > _pctState.target) {
    _pctState.target = target;
    _pctState.active = target < 100;
    _ensureAnim();
  } else if (target <= _pctState.current - 25) {
    // A big drop = a genuinely new scan: snap back to the low value and go.
    _pctState.current = target; _pctState.target = target; _pctState.active = true;
    const el = document.getElementById('orbPct');
    if (el) el.textContent = target + '%';
    _updateArc(target);
    _ensureAnim();
  }
  // Minor backward targets are ignored (monotonic — no 69↔70 bounce).

  // ── Bridge legacy orb HUD → XAI mobile HUD (fixes "stuck at 13%") ──
  // run() only calls shadowSay(), so advance the mobile phase state machine here.
  try {
    var xp = XAI_PHASE_BRIDGE[rawPhase];
    if (xp && typeof window.safeXaiProgress === 'function') {
      var st = null;
      if (xp === 'WALLET_PROGRESS' && window.XAI_SCAN_PROGRESS &&
          !window.XAI_SCAN_PROGRESS.walletsTotal &&
          typeof KNOWN !== 'undefined' && KNOWN) {
        st = { walletsTotal: Object.keys(KNOWN).length };
      }
      window.safeXaiProgress(xp, st);
      if (window.XAI_PROGRESS_SMOOTHER &&
          typeof window.XAI_PROGRESS_SMOOTHER.setTarget === 'function' &&
          typeof pctVal === 'number' && !isNaN(pctVal)) {
        window.XAI_PROGRESS_SMOOTHER.setTarget(Math.round(pctVal));
      }
    }
  } catch (_) { /* HUD bridge must never break a scan */ }
}

// Sub-progress: bumps within a phase band
function shadowProgress(phaseStart, phaseEnd, fraction) {
  const f = Math.max(0, Math.min(1, fraction));
  const target = Math.round(phaseStart + (phaseEnd - phaseStart) * f);
  if (target > _pctState.target) {
    _pctState.target = target;
    _pctState.active = target < 100;
    _ensureAnim();
  }
}

function shadowReset() {
  _pctState.current = 0; _pctState.target = 0; _pctState.animating = false; _pctState.active = false;
  const el = document.getElementById('orbPct');
  if (el) el.textContent = '0%';
  _updateArc(0);
  _updatePhaseBar('INIT');
  setText('orbPhase', 'WAITING');
  setText('orbStatus', 'Shadow Watch forensic core standing by.');
  // v3.26-hotfix5: flip source pill to WAITING at scan start so it doesn't
  // show NEWS DEGRADED from a previous scan while this scan is still running.
  try { if (typeof updateSourcePill === 'function') updateSourcePill({ _waiting: true }); } catch (_) {}
}

// ── TX WINDOW ──────────────────────────────────────────────────
const pad2 = x => String(x).padStart(2, '0');
function toLocalInput(d) {
  return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()) +
    'T' + pad2(d.getHours()) + ':' + pad2(d.getMinutes());
}
function parseLocalInput(v) { if (!v) return null; const d = new Date(v); return isFinite(d.getTime()) ? d.getTime() : null; }
// ── HOW FAR BACK A DEFAULT SCAN REACHES ────────────────────────
// A flat 24 hours opens Monday blind. The ledger does not take weekends off,
// but this report was only ever looking at the last day — so everything that
// moved between Friday's scan and Monday's fell in a hole nobody could see,
// and "a quiet weekend" and "we did not look" produced the same report.
//
// The floor is now set by the day it actually is, in UTC, the same clock the
// ledger timestamps use:
//   Monday    72h — back through Friday, the whole weekend in one sweep
//   Sunday    60h — Friday evening onward
//   Saturday  48h — Friday's session
//   otherwise 24h — the usual overnight
const _DAY_LOOKBACK_H = { 1: 72, 0: 60, 6: 48 };
function defaultLookbackHours(nowMs) {
  try { return _DAY_LOOKBACK_H[new Date(nowMs).getUTCDay()] || 24; }
  catch (_) { return 24; }
}
// When did we last complete a scan? The balance snapshot carries a timestamp
// per wallet, so the newest of those is the last time this app actually looked
// — no new storage needed. Used to widen the window when a day was missed, so
// a skipped run leaves no gap rather than a silent one.
function lastScanMs() {
  try {
    const prev = JSON.parse(localStorage.getItem(STORE) || '{}');
    let newest = 0;
    for (const k in prev) {
      const t = prev[k] && prev[k].ts ? Date.parse(prev[k].ts) : 0;
      if (isFinite(t) && t > newest) newest = t;
    }
    return newest || 0;
  } catch (_) { return 0; }
}
const MAX_LOOKBACK_H = 24 * 7;      // never reach further than the page depth supports

function getTxWindow() {
  const now = Date.now();
  const sR = parseLocalInput($('txStart') && $('txStart').value);
  const eR = parseLocalInput($('txEnd') && $('txEnd').value);
  const dayH = defaultLookbackHours(now);
  // Cover whichever is longer: the day-of-week floor, or the gap since the last
  // completed scan (plus an hour of overlap so nothing straddles the boundary).
  const last = lastScanMs();
  const gapH = last ? Math.min(MAX_LOOKBACK_H, (now - last) / 3600000 + 1) : 0;
  const autoH = Math.max(dayH, gapH);
  let startMs = sR ?? (now - autoH * 3600000), endMs = eR ?? now;
  if (endMs < startMs) { const t = startMs; startMs = endMs; endMs = t; }
  // An auto-set window is still "ours" even though the inputs are filled.
  const custom = !!(sR || eR) && !state._txWindowAuto;
  const hours = Math.max(1, (endMs - startMs) / 3600000);
  const DAY = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][new Date(now).getUTCDay()];
  let label;
  if (custom) {
    label = new Date(startMs).toLocaleString() + ' → ' + new Date(endMs).toLocaleString();
  } else {
    label = 'LAST ' + Math.round(hours) + 'H';
    // Say WHY it is wider than usual — a reader seeing "LAST 72H" deserves to
    // know it is deliberate and not a misconfiguration.
    if (gapH > dayH + 0.5) label += ' · GAP SINCE LAST SCAN';
    else if (dayH > 24)    label += ' · ' + DAY.toUpperCase() + ' WEEKEND SWEEP';
  }
  return { startMs, endMs, custom, hours, label, autoHours: autoH, dayName: DAY };
}

// FIX: 5 pages for 24h (was 1 in v2.x — biggest data gap)
function txWindowMaxPages() {
  const { hours } = getTxWindow();
  if (hours <= 30)     return 5;
  if (hours <= 24 * 7) return 10;
  return 15;
}

// auto = the app chose this window (day-aware default), not the operator. It
// only affects how the window is LABELLED — an operator-chosen range prints as a
// range, ours explains itself ("MONDAY WEEKEND SWEEP").
function setTxWindowHours(h, auto) {
  const end = new Date(), start = new Date(end.getTime() - h * 3600000);
  if ($('txStart')) $('txStart').value = toLocalInput(start);
  if ($('txEnd')) $('txEnd').value = toLocalInput(end);
  state._txWindowAuto = !!auto;
  updateScopeHud();
}
// Called on boot. Applies the day-aware lookback rather than a flat 24 hours.
function applyAutoTxWindow() {
  const now = Date.now();
  const last = lastScanMs();
  const gapH = last ? Math.min(MAX_LOOKBACK_H, (now - last) / 3600000 + 1) : 0;
  setTxWindowHours(Math.max(defaultLookbackHours(now), gapH), true);
}
function clearTxWindow() {
  if ($('txStart')) $('txStart').value = '';
  if ($('txEnd')) $('txEnd').value = '';
  state._txWindowAuto = false;
  updateScopeHud();
}

// ── SCAN TARGET ────────────────────────────────────────────────
function getScanTarget() { return ($('scanTarget') && $('scanTarget').value) || 'ALL'; }
function getActiveWatchlist() {
  const v = getScanTarget();
  if (v === 'ALL')       return WATCHLIST;
  if (v === 'EXCHANGES') return WATCHLIST.filter(w => w.cat === 'exchange');
  if (v === 'WHALES')    return WATCHLIST.filter(w => w.cat === 'whale');
  if (v === 'ESCROW')    return WATCHLIST.filter(w => w.cat === 'escrow');
  if (v.startsWith('ADDR:')) return WATCHLIST.filter(w => w.address === v.slice(5));
  return WATCHLIST;
}
function targetLabel() {
  const v = getScanTarget();
  if (v === 'ALL')       return 'ALL ' + WATCHLIST.length + ' WATCHED';
  if (v === 'EXCHANGES') return 'EXCHANGES (' + WATCHLIST.filter(w => w.cat === 'exchange').length + ')';
  if (v === 'WHALES')    return 'WHALES (' + WATCHLIST.filter(w => w.cat === 'whale').length + ')';
  if (v === 'ESCROW')    return 'ESCROW (' + WATCHLIST.filter(w => w.cat === 'escrow').length + ')';
  if (v.startsWith('ADDR:')) {
    const w = WATCHLIST.find(x => x.address === v.slice(5));
    return w ? w.label : ca(v.slice(5));
  }
  return 'ALL WATCHED';
}
function updateScopeHud() {
  const a = getActiveWatchlist(), tw = getTxWindow();
  setText('scopeTargetChip', 'TARGET: ' + targetLabel());
  setText('scopeWindowChip', 'WINDOW: ' + tw.label);
  setText('hudScopeBadge', a.length + ' WALLET' + (a.length === 1 ? '' : 'S'));
  setText('hudTotal', a.length);
  setText('statWallets', a.length);
}
function populateScanTarget() {
  const sel = $('scanTarget'); if (!sel) return;
  const cur = sel.value || 'ALL';
  const ex = WATCHLIST.filter(w => w.cat === 'exchange');
  const wh = WATCHLIST.filter(w => w.cat !== 'exchange');
  sel.innerHTML = `<option value="ALL">All watched wallets (${WATCHLIST.length})</option>
    <option value="EXCHANGES">All exchanges (${ex.length})</option>
    <option value="WHALES">All whales (${WATCHLIST.filter(w=>w.cat==='whale').length})</option>
    <option value="ESCROW">Ripple / escrow (${WATCHLIST.filter(w=>w.cat==='escrow').length})</option>
    <optgroup label="Exchange wallets">${ex.map(w=>`<option value="ADDR:${w.address}">${w.label}</option>`).join('')}</optgroup>
    <optgroup label="Whale / escrow">${wh.map(w=>`<option value="ADDR:${w.address}">${w.label}</option>`).join('')}</optgroup>`;
  sel.value = [...sel.options].some(o => o.value === cur) ? cur : 'ALL';
  sel.onchange = updateScopeHud;
  updateScopeHud();
}

// ── XRPL CONNECT (with FALLBACK) ───────────────────────────────
async function connectXRPL() {
  const preferred = $('xrplServer') ? $('xrplServer').value : XRPL_SERVERS[0];
  const servers = [preferred, ...XRPL_SERVERS.filter(s => s !== preferred)];
  for (const server of servers) {
    try {
      const ws = await new Promise((res, rej) => {
        const w = new WebSocket(server);
        const t = setTimeout(() => { try { w.close(); } catch {} rej(new Error('connect timeout ' + server)); }, 8000);
        w.onopen = () => { clearTimeout(t); res(w); };
        w.onerror = () => { clearTimeout(t); rej(new Error('ws error ' + server)); };
      });
      log('XRPL connected: ' + server);
      return ws;
    } catch (e) {
      elog('XRPL server failed, trying next: ' + server, e);
    }
  }
  throw new Error('All XRPL servers failed');
}

// ── LIVE SOCKET ────────────────────────────────────────────────
// Leave the app mid-scan and the OS closes the WebSocket. Nothing here used to
// notice: ws was captured once at boot and every later request was sent into a
// dead socket. The WebSocket spec says a send() on a CLOSING or CLOSED socket is
// DISCARDED SILENTLY — no throw, no error — so each request then sat out its
// full 15-second timeout before failing, and the per-wallet catch marked the row
// FAILED and moved on to the next one. At 8-parallel over 187 wallets that is
// ~6 minutes of dead air in the balance pass, and the tx pass does it again.
// That is the "it never finishes" everyone was watching: not a hang, a scan
// grinding through a dozen minutes of guaranteed timeouts.
//
// The socket now lives on state so a reconnect can be swapped in underneath every
// in-flight call without touching a single call site.
function _sockOpen(w) { try { return !!w && w.readyState === 1; } catch (_) { return false; } }

// Have we given up on the connection? Used by the batch passes so they stop
// instead of walking their whole list producing one identical error per wallet.
function _linkDown() {
  if (_sockOpen(state._sock)) return false;
  return n(state._reconnectFails) >= 1 && !state._reconnecting;
}

async function _ensureSock(ws) {
  if (_sockOpen(ws)) return ws;
  if (_sockOpen(state._sock)) return state._sock;
  // One shared reconnect for the whole scan: 8 parallel wallets hitting a dead
  // socket must not open 8 connections.
  if (state._reconnecting) return await state._reconnecting;
  if (n(state._reconnectFails) >= 3) return null;   // stop trying, fail fast
  state._reconnecting = (async () => {
    try {
      log('XRPL link dropped — reconnecting…');
      const nw = await connectXRPL();
      state._sock = nw;
      state._reconnectFails = 0;
      log('XRPL link re-established. Scan continues.');
      return nw;
    } catch (e) {
      state._reconnectFails = n(state._reconnectFails) + 1;
      // v16.23: record that the link went down DURING the scan. Until now this
      // only reached the error log. The balance pass had usually finished, so
      // coverage still read 228/228 honestly — but the later phases (offers,
      // next-hop) never ran, their sections simply did not print, and the report
      // gave no sign anything was missing.
      //
      // SW-20260813-Q20LA lost sections 7 and 10 this way. The run before it
      // lost the same two, and with them the top actionable finding — "rwV8eL is
      // sitting on 77.15M XRP with no forward". A reader would conclude the
      // finding had gone away. It had not; we stopped looking.
      state.linkLostDuringScan = true;
      state.linkLostAt = new Date().toISOString();
      elog('mid-scan reconnect', e);
      return null;
    } finally {
      const done = state._reconnecting;
      setTimeout(() => { if (state._reconnecting === done) state._reconnecting = null; }, 0);
    }
  })();
  return await state._reconnecting;
}

async function xrpl(ws, cmd) {
  const sock = await _ensureSock(ws);
  if (!sock) throw new Error('XRPL link down');
  return new Promise((res, rej) => {
    const id = Math.random().toString(36).slice(2);
    let settled = false;
    function done(fn, arg) {
      if (settled) return; settled = true;
      clearTimeout(timer);
      try { sock.removeEventListener('message', onMsg); } catch (_) {}
      try { sock.removeEventListener('close', onClose); } catch (_) {}
      fn(arg);
    }
    const timer = setTimeout(() => done(rej, new Error('timeout ' + cmd.command)), 15000);
    function onMsg(ev) {
      let j; try { j = JSON.parse(ev.data); } catch { return; }
      if (j.id !== id) return;
      j.status === 'success' ? done(res, j.result)
                             : done(rej, new Error(j.error_message || j.error || 'xrpl error'));
    }
    // Fail the instant the socket goes, instead of waiting out 15s for a reply
    // that can no longer arrive. This is what turns a 12-minute zombie scan into
    // a reconnect that takes a second.
    function onClose() { done(rej, new Error('XRPL link closed mid-request')); }
    sock.addEventListener('message', onMsg);
    sock.addEventListener('close', onClose);
    try { sock.send(JSON.stringify({ ...cmd, id })); }
    catch (e) { done(rej, e instanceof Error ? e : new Error(String(e))); }
  });
}

async function accountTxWindow(ws, account, startMs, endMs, limit) {
  return accountTxWindowDepth(ws, account, startMs, endMs, limit, txWindowMaxPages());
}

// v3.11: depth-aware version — caller supplies maxPages so tier-based scans
// can use 1 page for dormant wallets, 3 for exchanges, etc.
async function accountTxWindowDepth(ws, account, startMs, endMs, limit, maxPages) {
  const rows = []; let marker = null, pages = 0;
  do {
    const req = { command: 'account_tx', account, ledger_index_min: -1, ledger_index_max: -1, limit, forward: false };
    if (marker) req.marker = marker;
    const res = await xrpl(ws, req);
    const txs = res.transactions || []; let oldest = Infinity;
    for (const item of txs) {
      const t = item.tx_json || item.tx || {}, iso = t.date ? rip(t.date) : '';
      if (!iso) continue;
      const ms = new Date(iso).getTime();
      if (!isFinite(ms)) continue;
      oldest = Math.min(oldest, ms);
      if (ms >= startMs && ms <= endMs) rows.push(item);
    }
    marker = res.marker; pages++;
    if (oldest < startMs) break;
  } while (marker && pages < maxPages);
  return rows;
}

// v3.12: SMART TWO-PHASE SCAN
// PHASE 1: Fast parallel balance check (8 concurrent account_info calls).
//          Records baseline + delta for every wallet. ~1-2 seconds for 74.
// PHASE 2: Tier-based account_tx ONLY for wallets where balance actually changed
//          OR first-scan baseline (no prev). Most quiet wallets skip Phase 2 entirely.
// Result: quiet day ~3-5 sec, active day ~8-12 sec (vs old 75 sec).
const SCAN_PARALLEL = 8;          // v3.12: doubled from 4
const SCAN_CHUNK_DELAY_MS = 0;    // v3.12: no inter-chunk delay needed

// Per-group page depth for Phase 2.
function pageDepthFor(label) {
  const grp = getWalletGroup(label);
  let base;
  switch (grp) {
    case 'dormant': case 'founder': case 'genesis_whale': base = 1; break;
    case 'whale': case 'institutional': case 'msig_cluster': case 'market_maker': base = 2; break;
    case 'exchange': case 'ripple_corp': base = 3; break;
    default: base = 2;
  }
  // These page counts were tuned for a 24-hour window. Widening the window to
  // cover a weekend without widening the depth would have been worse than not
  // widening it at all: a busy exchange fills three pages inside a single day,
  // so the extra 48 hours would come back empty and the report would call a
  // weekend quiet on the strength of data it never fetched. Scale with the
  // window. accountTxWindowDepth still stops the moment it reads past the
  // window start, so a quiet wallet pays nothing for the higher ceiling.
  try {
    const h = getTxWindow().hours;
    const factor = Math.max(1, Math.min(4, Math.ceil(h / 24)));
    return Math.min(15, base * factor);
  } catch (_) { return base; }
}

async function scanWallets(ws) {
  state.wallets = []; state.txs = []; state.flags = []; state.large = []; state.frags = [];
  const prev = JSON.parse(localStorage.getItem(STORE) || '{}');
  const tw = getTxWindow();
  const limit = Math.max(20, Math.min(400, n($('inTxLimit').value) || 200));
  const active = getActiveWatchlist();
  log('SCAN: ' + active.length + ' wallets, parallel=' + SCAN_PARALLEL + ', smart-skip tx-pass');

  // ── PHASE 1: Fast parallel balance check ──
  // Build a row per wallet. Fetch account_info only (1 RPC each).
  shadowSay('Phase 1: balance check ' + active.length + ' wallets...', 'BALANCES', 32);
  const rows = active.map(w => ({
    ...w, balance_xrp: 0, prev_balance_xrp: prev[w.address]?.balance_xrp ?? null,
    delta_xrp: null, status: 'CHECKED', error: '', _needsTx: false
  }));

  async function balanceOne(row) {
    if (!BASE58_RE.test(row.address)) {
      row.status = 'INVALID_ADDR'; row.error = 'malformed XRPL address';
      return;
    }
    try {
      const info = await xrpl(ws, { command: 'account_info', account: row.address, ledger_index: 'validated' });
      row.balance_xrp = drops(info.account_data.Balance);
      if (row.prev_balance_xrp !== null) {
        row.delta_xrp = row.balance_xrp - row.prev_balance_xrp;
      }
      // Decide if Phase 2 (tx scan) is needed:
      // - First scan ever for this wallet (no prev)
      // - Balance actually changed (|delta| > 0)
      // - Any active exchange (always pull recent tx for flow visibility)
      const grp = getWalletGroup(row.label);
      const balanceChanged = row.prev_balance_xrp !== null && Math.abs(row.delta_xrp || 0) > 0;
      const firstScan = row.prev_balance_xrp === null;
      const isActive = grp === 'exchange' || grp === 'ripple_corp';
      row._needsTx = firstScan || balanceChanged || isActive;
      row.status = 'CHECKED';
    } catch (e) {
      row.status = 'FAILED'; row.error = e.message;
    }
  }

  let phase1Done = 0;
  for (let i = 0; i < rows.length; i += SCAN_PARALLEL) {
    const chunk = rows.slice(i, i + SCAN_PARALLEL);
    await Promise.all(chunk.map(balanceOne));
    phase1Done = i + chunk.length;
    // Smooth progress: 32→55% over Phase 1
    shadowProgress(32, 55, phase1Done / rows.length);
    state.wallets = rows.slice();      // mid-scan render
    renderWallets();
    setBar('hudWalletBar', phase1Done / rows.length * 50);   // 0-50% on bar = Phase 1
    // Publish live wallet progress. XAI_SCAN_PROGRESS was only ever updated by
    // _pollWallets(), which reads state.pack — and state.pack is not assigned
    // until the very END of the scan, so the wallet-coverage gauge and the
    // mission UI sat empty for the whole scan. Publish it from the loop itself.
    try {
      if (window.XAI_SCAN_PROGRESS) {
        window.XAI_SCAN_PROGRESS.walletsTotal   = rows.length;
        window.XAI_SCAN_PROGRESS.walletsChecked = phase1Done;
        window.XAI_SCAN_PROGRESS.phase          = 'WALLET_PROGRESS';
      }
      if (window.__swDashApplied && typeof window.renderDashboardV1Live === 'function') window.renderDashboardV1Live();
    } catch (_) {}
    setText('hudChecked', rows.filter(r => r.status === 'CHECKED').length);
    setText('hudFailed', rows.filter(r => r.status === 'FAILED').length);
    setText('hudInvalid', rows.filter(r => r.status === 'INVALID_ADDR').length);
  }

  // ── PHASE 2: account_tx only for wallets that need it ──
  const needTx = rows.filter(r => r._needsTx && r.status === 'CHECKED');
  log('Phase 1 complete. Phase 2 tx-scan needed for ' + needTx.length + ' / ' + rows.length + ' wallets.');
  shadowSay('Phase 2: tx scan ' + needTx.length + ' active wallets...', 'TX_SCAN', 56);

  async function txOne(row) {
    const depth = pageDepthFor(row.label);
    try {
      const txRows = await accountTxWindowDepth(ws, row.address, tw.startMs, tw.endMs, limit, depth);
      for (const item of txRows) {
        const t = item.tx_json || item.tx || {}, iso = t.date ? rip(t.date) : '';
        if (!iso) continue;
        let amt = 0, cur = 'XRP', escrowDest = '';
        // v16.9 units fix: a partial payment carries a huge SENTINEL in `Amount`
        // (the max, often ~1e17 drops ≈ 100B+ XRP) while the REAL moved amount is
        // in meta.delivered_amount. Reading Amount produced impossible "103B XRP"
        // transfers. Prefer the actually-delivered amount whenever it's present.
        const _dmeta = item.meta || item.metaData || {};
        let amtSrc = t.Amount;
        if (_dmeta && _dmeta.delivered_amount != null && _dmeta.delivered_amount !== 'unavailable')
          amtSrc = _dmeta.delivered_amount;
        if (typeof amtSrc === 'string') amt = drops(amtSrc);
        else if (amtSrc && typeof amtSrc === 'object') { cur = amtSrc.currency || 'TOKEN'; amt = n(amtSrc.value || 0); }
        else if (t.TransactionType === 'EscrowFinish' || t.TransactionType === 'EscrowCreate') {
          // Released/locked XRP lives in metadata (the created/deleted Escrow node), not t.Amount.
          const meta = item.meta || item.metaData || {};
          for (const nd of (meta.AffectedNodes || [])) {
            const en = nd.DeletedNode || nd.CreatedNode;
            if (en && en.LedgerEntryType === 'Escrow') {
              const ff = en.FinalFields || en.NewFields || {};
              if (typeof ff.Amount === 'string') amt = drops(ff.Amount);
              if (ff.Destination) escrowDest = ff.Destination;
              break;
            }
          }
          if (!amt && typeof t.Amount === 'string') amt = drops(t.Amount);
        }
        const _sig = _sigMode(t);
        state.txs.push({
          account: row.address, label: row.label, cat: row.cat,
          type: t.TransactionType, hash: t.hash || item.hash || '',
          date: iso, from: t.Account || '', to: escrowDest || t.Destination || '',
          amount: amt, currency: cur, destination_tag: t.DestinationTag ?? '',
          // Who authorised this — see _sigMode.
          sig_mode: _sig.mode, signer_count: _sig.count
        });
      }
    } catch (e) {
      // Don't fail the wallet — Phase 1 balance is still valid. Just log.
      log('tx-scan miss: ' + row.label + ' (' + e.message + ')');
    }
  }

  let phase2Done = 0;
  for (let i = 0; i < needTx.length; i += SCAN_PARALLEL) {
    const chunk = needTx.slice(i, i + SCAN_PARALLEL);
    await Promise.all(chunk.map(txOne));
    phase2Done = i + chunk.length;
    shadowProgress(56, 78, phase2Done / Math.max(needTx.length, 1));
    setBar('hudWalletBar', 50 + phase2Done / Math.max(needTx.length, 1) * 50);
    try {
      if (window.XAI_SCAN_PROGRESS) {
        window.XAI_SCAN_PROGRESS.walletsTotal   = rows.length;
        window.XAI_SCAN_PROGRESS.walletsChecked = rows.length;   // balances all read
        window.XAI_SCAN_PROGRESS.phase          = 'LEDGER';
      }
      if (window.__swDashApplied && typeof window.renderDashboardV1Live === 'function') window.renderDashboardV1Live();
    } catch (_) {}
  }

  // ── DEDUPE: one ledger transaction = one row ──────────────────
  // Transactions are fetched per watched wallet, so a transfer BETWEEN two
  // watched wallets comes back in both wallets' account_tx results and was
  // pushed twice. Every downstream total counted it twice: the 24h tx count,
  // watched activity volume, and — because analyzeFlags() walks state.txs —
  // shadow volume and the large-transfer list. Measured on the 2026-07-31 scan:
  // 36 large-transfer rows for 24 real transactions, overstating shadow volume
  // by 37%. Keep the first row for each ledger hash (rows without a hash, e.g.
  // synthetic entries, are always kept).
  (function dedupeTxsByHash() {
    var seen = Object.create(null), out = [], dropped = 0;
    for (var i = 0; i < state.txs.length; i++) {
      var h = state.txs[i] && state.txs[i].hash;
      if (h) { if (seen[h]) { dropped++; continue; } seen[h] = 1; }
      out.push(state.txs[i]);
    }
    if (dropped) log('deduped ' + dropped + ' duplicate tx row(s) seen from both sides of a watched-to-watched transfer');
    state.txs = out;
  })();

  // Final state
  state.wallets = rows;
  renderWallets();

  // Save snapshot for delta baseline
  localStorage.setItem(STORE, JSON.stringify(Object.fromEntries(
    rows.filter(w => w.status === 'CHECKED')
      .map(w => [w.address, { label: w.label, balance_xrp: w.balance_xrp, ts: new Date().toISOString() }])
  )));

  // v16.8: feed the SHARED balance history. This console and the live wall are
  // separate documents but the same origin, so they already share a localStorage
  // — writing here means the wall's HVT board can flag a drained target from a
  // balance THIS scan read, without waiting for its own sweep to come round. The
  // reverse holds too: the wall's readings are here when the report runs.
  try {
    if (window.SW_HVT_HISTORY) {
      let n0 = 0;
      rows.forEach(w => {
        if (w.status === 'CHECKED' && w.address && isFinite(n(w.balance_xrp))) {
          SW_HVT_HISTORY.record(w.address, n(w.balance_xrp), 'report');
          n0++;
        }
      });
      if (n0) log('shared balance history updated for ' + n0 + ' wallet(s)');
    }
  } catch (_) { /* never let the shared store break a scan */ }
  const checked = rows.filter(w => w.status === 'CHECKED').length;
  const total = active.length;
  setText('hudWalletBadge', checked + '/' + total);
  const b = $('hudWalletBadge');
  if (b) b.className = 'panel-badge ' + (checked === total ? 'ok' : checked > 0 ? 'warn' : 'bad');
}

// ── WHO SIGNED IT ─────────────────────────────────────────────
// The Coreum bridge drain turned entirely on this question. A widely-shared
// warning said XRP was "leaking out through the issuer" via an account flag; the
// ledger said every one of those 94 payments carried the bridge's own account in
// the Account field with an empty SigningPubKey and 17 signatures in Signers —
// the bridge PAID the money out, its own relayer quorum authorising each one.
// Same money, same direction, completely different event, and the only way to
// tell them apart is to read the signature.
//
// XRPL encodes it plainly: a single-key transaction carries a hex SigningPubKey
// and no Signers; a multi-signed one carries an empty SigningPubKey and a Signers
// array holding one entry per co-signer. Some API shapes omit SigningPubKey
// entirely, so presence of Signers is the primary test and the key is the
// fallback — anything else is honestly 'unknown' rather than guessed.
function _sigMode(t) {
  try {
    if (Array.isArray(t.Signers) && t.Signers.length > 0)
      return { mode: 'multisig', count: t.Signers.length };
    if (typeof t.SigningPubKey === 'string' && t.SigningPubKey.length > 0)
      return { mode: 'single', count: 1 };
    if (t.SigningPubKey === '')            // empty key, no Signers we can see
      return { mode: 'multisig', count: 0 };
  } catch (_) {}
  return { mode: 'unknown', count: 0 };
}
// How to say it in a report line. Never printed for a single-key transfer —
// that is the ordinary case and saying so on every line would be noise.
function _sigPhrase(t) {
  if (!t || t.sig_mode !== 'multisig') return '';
  const c = n(t.signer_count);
  return c > 0 ? ' · signed by ' + c + '-key quorum' : ' · multisig-signed';
}

// An account younger than this, receiving a large transfer, is reported as such.
// 48h rather than the ~2h the Coreum front wallets actually had: the point is to
// catch the pattern, and a wallet opened yesterday to take millions today is the
// same story told a day slower.
const FRESH_ACCOUNT_HOURS = 48;
function _ageText(h) {
  if (h == null || !isFinite(h)) return '';
  if (h < 1)  return Math.max(1, Math.round(h * 60)) + ' minutes old';
  if (h < 48) return Math.round(h) + ' hours old';
  return Math.round(h / 24) + ' days old';
}

// ── ANALYZE FLAGS ─────────────────────────────────────────────
function classify(t) {
  const f = KNOWN[t.from], to = KNOWN[t.to];
  let type = 'UNKNOWN_FLOW', conf = 'MEDIUM', reason = 'receiver not in watchlist';
  if (f && to)                                  { type = 'WATCHLIST_INTERNAL'; conf = 'HIGH'; reason = f.label + ' → ' + to.label; }
  else if (f && f.cat === 'exchange' && !to)    { type = 'EXCHANGE_OUTFLOW';  conf = 'HIGH'; reason = 'known exchange to unknown'; }
  else if (!f && to && to.cat === 'exchange')   { type = 'EXCHANGE_INFLOW';   conf = 'HIGH'; reason = 'unknown to exchange'; }
  else if (f && f.cat === 'whale' && !to)       { type = 'WHALE_TO_UNKNOWN';  conf = 'HIGH'; reason = 'known whale to unknown'; }
  else if (f && f.cat === 'escrow')             { type = 'ESCROW_FLOW';       conf = 'HIGH'; reason = 'Ripple/escrow wallet'; }
  return { ...t, classification: type, confidence: conf, reason,
    // The sender label must describe the ACTUAL sender. Falling back to
    // t.label used the label of the wallet whose history the row came from —
    // which for an inbound transfer is the RECEIVER — so the report claimed
    // things like "UPBIT_1.2B → UPBIT_1.2B" for a payment from an unknown
    // third party. Fall back to the sender's own (shortened) address instead.
    sender_label: f?.label || (t.from ? ca(t.from) : 'UNKNOWN'),
    receiver_label: to?.label || (t.to ? ca(t.to) : 'UNKNOWN') };
}

function analyzeFlags() {
  const flags = [], large = [], frags = [];
  const threshold = n($('inLargeThreshold').value) || 1000000;
  // XRP total supply is ~100B. Any single "XRP" amount at/above this ceiling is a
  // data artifact (e.g. an unresolved partial-payment sentinel), never a real
  // transfer — exclude it so the report can't print an impossible 100B+ move.
  const MAX_PLAUSIBLE_XRP = 100_000_000_000;
  for (const t of state.txs) {
    if (t.currency === 'XRP' && t.amount >= MAX_PLAUSIBLE_XRP) {
      log('dropped implausible XRP amount (data artifact): ' + fmt(t.amount, 0) + ' ' + (t.hash || ''));
      continue;
    }
    if (t.currency === 'XRP' && t.amount >= threshold) {
      const c = classify(t); large.push(c);
      flags.push(`${c.confidence} ${c.classification}: ${c.sender_label} → ${ca(c.to)} ${fmt(c.amount, 0)} XRP ${c.hash}`);
    }
    if (t.type === 'EscrowFinish' || t.type === 'EscrowCreate')
      flags.push(`HIGH ESCROW_${t.type}: ${t.label} ${fmt(t.amount)} XRP ${t.hash}`);
  }
  // Dust groups
  const groups = {};
  for (const t of state.txs) {
    if (t.currency === 'XRP' && t.amount > 0 && t.amount <= 50 && t.to) {
      const k = t.to + '|' + (t.destination_tag || 'none');
      if (!groups[k]) groups[k] = { to: t.to, tag: t.destination_tag || '', count: 0, total: 0, froms: new Set() };
      groups[k].count++; groups[k].total += t.amount; groups[k].froms.add(t.from);
    }
  }
  for (const g of Object.values(groups)) {
    if (g.count >= 5) {
      const sev = (g.total >= 1 || g.froms.size >= 3 || g.count >= 25) ? 'FRAG_SUSPECT' : 'DUST_NOISE';
      frags.push({ to: g.to, tag: g.tag, count: g.count, total: g.total, unique_from: g.froms.size, severity: sev });
      flags.push(`${sev}: to=${ca(g.to)} tag=${g.tag||'none'} count=${g.count} unique_from=${g.froms.size}`);
    }
  }
  for (const w of state.wallets) {
    if (w.delta_xrp !== null && Math.abs(w.delta_xrp) >= 1000000)
      flags.push(`HIGH BALANCE_DELTA >1M: ${w.label} ${w.delta_xrp > 0 ? '+' : ''}${fmt(w.delta_xrp, 2)} XRP`);
  }
  // ── SIGNING-HABIT WATCH ──────────────────────────────────────
  // Teach the shared store how each watched wallet authorises payments, and
  // surface the moment that changes. Only senders we actually watch are tracked:
  // a stranger's signing habit is not something we have any history for.
  state.sigChanges = [];
  try {
    if (window.SW_HVT_HISTORY && SW_HVT_HISTORY.recordSig) {
      const seenSig = Object.create(null);
      for (const t of state.txs) {
        if (!t.from || !KNOWN[t.from]) continue;
        if (t.sig_mode !== 'multisig' && t.sig_mode !== 'single') continue;
        const k = t.from + '|' + t.sig_mode;
        if (seenSig[k]) continue;              // one vote per wallet per mode per scan
        seenSig[k] = 1;
        const ch = SW_HVT_HISTORY.recordSig(t.from, t.sig_mode, t.signer_count);
        if (ch) state.sigChanges.push(ch);
      }
      state.sigChanges.forEach(c => {
        const who = _swWho(c.address, (KNOWN[c.address] || {}).label, { bare: true });
        flags.push((c.to === 'single' ? 'HIGH' : 'MEDIUM') + ' SIGNING_MODE_CHANGE: ' + who +
          ' now signs ' + (c.to === 'single' ? 'with a single key' : 'by quorum') +
          ' (was ' + (c.from === 'single' ? 'single-key' : 'quorum') + ')');
      });
    }
  } catch (_) { /* the signing watch must never break a scan */ }

  if (!flags.length) flags.push('No 24h tx/delta anomaly detected. Scan-based, not filler.');
  state.flags = flags; state.large = large; state.frags = frags;
  if ($('flagsBox')) $('flagsBox').textContent = flags.join('\n');
}

async function scanReceivers(ws) {
  state.receivers = [];
  const seen = new Map();
  for (const t of state.large) {
    if (t.to && !KNOWN[t.to] && !seen.has(t.to) && BASE58_RE.test(t.to)) seen.set(t.to, t);
  }
  const limit = Math.max(5, Math.min(80, n($('inHopLimit').value) || 60));
  for (const [addr, src] of seen.entries()) {
    const rec = { address: addr, source_label: src.sender_label, source_amount_xrp: src.amount,
      balance_xrp: null, tx_count: 0, forwarded_large_count: 0, forwarded_large_total_xrp: 0,
      classification: 'RECEIVER_HOLDING_UNKNOWN', confidence: 'MEDIUM', error: '' };
    try {
      const info = await xrpl(ws, { command: 'account_info', account: addr, ledger_index: 'validated' });
      rec.balance_xrp = drops(info.account_data.Balance);
      // ── HOW OLD IS THIS ACCOUNT? ──────────────────────────────
      // Both wallets that took the Coreum bridge outflow were created under two
      // hours before the first payment landed. "Millions of XRP into an account
      // opened this afternoon" is the loudest signal on the ledger and we were
      // not reading it. One extra call, forward from the beginning: the first
      // transaction an account ever appears in is the payment that funded it.
      try {
        const first = await xrpl(ws, { command: 'account_tx', account: addr,
          ledger_index_min: -1, ledger_index_max: -1, limit: 1, forward: true });
        const f0 = (first.transactions || [])[0];
        const ft = f0 && (f0.tx_json || f0.tx || {});
        const fiso = ft && ft.date ? rip(ft.date) : '';
        if (fiso) {
          rec.created_at = fiso;
          rec.age_hours = Math.max(0, (Date.now() - new Date(fiso).getTime()) / 3600000);
        }
      } catch (_) { /* age is a bonus signal — never fail the receiver for it */ }
      const tx = await xrpl(ws, { command: 'account_tx', account: addr, ledger_index_min: -1, ledger_index_max: -1, limit, forward: false });
      const cutoff = Date.now() - 86400000;
      for (const item of (tx.transactions || [])) {
        const t = item.tx_json || item.tx || {}, iso = t.date ? rip(t.date) : '';
        if (!iso || new Date(iso).getTime() < cutoff) continue;
        rec.tx_count++;
        // Prefer meta.delivered_amount (partial-payment sentinel fix) so a huge
        // Amount sentinel can't inflate the forwarded total.
        const _meta = item.meta || item.metaData || {};
        let _amtSrc = t.Amount;
        if (_meta.delivered_amount != null && _meta.delivered_amount !== 'unavailable') _amtSrc = _meta.delivered_amount;
        const amt = typeof _amtSrc === 'string' ? drops(_amtSrc) : 0;
        if (amt >= 100000000000) continue; // implausible (≥ total supply) → data artifact
        if (t.Account === addr && amt >= 1000000) { rec.forwarded_large_count++; rec.forwarded_large_total_xrp += amt; }
      }
      // An account that did not exist yesterday, taking millions today, is a
      // stronger read than whether it forwarded or held — so it wins the
      // classification. FRESH_ACCOUNT_RECEIVER is exactly the shape both Coreum
      // front wallets had: created hours earlier, funded once, emptied onward.
      rec.fresh_account = rec.age_hours != null && rec.age_hours <= FRESH_ACCOUNT_HOURS;
      rec.classification = rec.fresh_account ? 'FRESH_ACCOUNT_RECEIVER'
        : rec.forwarded_large_count > 0 ? 'NEXT_HOP_FORWARDING_DETECTED'
        : rec.balance_xrp >= src.amount * 0.5 ? 'RECEIVER_STILL_HOLDING_SIZE'
        : 'RECEIVER_BALANCE_LOW_OR_SPLIT';
      rec.confidence = (rec.fresh_account || rec.forwarded_large_count > 0) ? 'HIGH' : 'MEDIUM';
    } catch (e) {
      rec.error = e.message; rec.classification = 'NEXT_HOP_SCAN_FAILED'; rec.confidence = 'LOW';
    }
    state.receivers.push(rec);
    log(`NEXT_HOP: ${ca(addr)} ${rec.classification}` + (rec.balance_xrp != null ? ' ' + fmt(rec.balance_xrp, 2) + ' XRP' : ''));
    await delay(200);
  }
  setText('hudReceiverCount', state.receivers.length);
  setText('hudReceiverMode', state.receivers.length ? state.receivers.length + ' receiver(s) scanned' : 'no unknown large-transfer receivers');
}

// ── AMM SCAN ──────────────────────────────────────────────────
const WATCHED_AMM_PAIRS = [
  { name: 'XRP/RLUSD', asset: 'XRP', asset2: { currency: '524C555344000000000000000000000000000000', issuer: 'rMxCKbEDwqr76QuheSUMdEGf4B9xJ8m5De' } }
];
async function scanAmmIntel(ws) {
  const out = { pairs_checked: 0, pairs_failed: 0, pools: [] };
  for (const pair of WATCHED_AMM_PAIRS) {
    if (!pair.asset2.issuer) {
      out.pools.push({ name: pair.name, status: 'CONFIG_NEEDED', error: 'issuer required' });
      continue;
    }
    out.pairs_checked++;
    try {
      const r = await xrpl(ws, { command: 'amm_info', asset: { currency: 'XRP' }, asset2: pair.asset2 });
      const amm = r.amm || {};
      out.pools.push({ name: pair.name, status: 'OK', trading_fee: String(amm.trading_fee ?? ''), lp_token: amm.lp_token });
    } catch (e) {
      out.pairs_failed++;
      out.pools.push({ name: pair.name, status: 'FAILED', error: e.message || String(e) });
    }
  }
  out.summary = `AMM: ${out.pairs_checked} checked, ${out.pairs_failed} failed.`;
  state.ammIntel = out;
  if ($('ammBox')) $('ammBox').textContent = JSON.stringify(out, null, 2);
  setText('hudAmmBadge', out.pairs_checked > out.pairs_failed ? 'OK' : 'PARTIAL');
  return out;
}

// ── MARKET FEEDS (4-source fallback) ──────────────────────────
// v3.26-hotfix2: every market() fetch capped at 5s individually.
// Previous bug: CoinGecko (or any single endpoint) hanging on its default
// browser timeout (~60s+) blocked the entire boot phase at 18%. With the
// timeout, each endpoint either responds or fails in ≤5s; the whole market
// scan completes in <8s even in worst case (5 of 7 endpoints timing out).
const MARKET_FETCH_TIMEOUT_MS = 5000;

// v3.32b: DeFiLlama DEX volume was fetched direct-only, so a CORS block or a
// renamed adapter slug left the DEX tiles blank. Try direct, then the relay
// cascade, and only return a positive number (never overwrite good data with 0).
async function fetchDefiDex(url) {
  let j = null;
  try { const r = await fetchWithTimeout(url, MARKET_FETCH_TIMEOUT_MS); if (r.ok) j = await r.json(); } catch (e) {}
  if (!j || j.total24h == null) {
    try { const { response } = await proxyFetch(url, MARKET_FETCH_TIMEOUT_MS); if (response && response.ok) j = await response.json(); } catch (e) {}
  }
  const v = j && Number(j.total24h);
  return (v && v > 0) ? Math.round(v) : null;
}

// ── RLUSD supply: two INDEPENDENT sources, each a fallback for the other ──
// A) on-chain gateway_balances (authoritative — the issuer's own obligations)
// B) CoinGecko aggregate. Run in parallel; if one fails we still have the other.
const RLUSD_ISSUER = 'rMxCKbEDwqr76QuheSUMdEGf4B9xJ8m5De';
const RLUSD_HEX    = '524C555344000000000000000000000000000000'; // "RLUSD" (5-char → 40-hex)
async function fetchRlusdGateway() {
  try {
    const controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
    const tid = controller ? setTimeout(function(){ controller.abort(); }, MARKET_FETCH_TIMEOUT_MS) : null;
    const opts = { method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ method: 'gateway_balances', params: [{ account: RLUSD_ISSUER, ledger_index: 'validated' }] }) };
    if (controller) opts.signal = controller.signal;
    const resp = await fetch('https://xrplcluster.com', opts);
    if (tid) clearTimeout(tid);
    if (!resp.ok) return null;
    const data = await resp.json();
    const obl = data && data.result && data.result.obligations;
    if (!obl) return null;
    let val = n(obl[RLUSD_HEX]);
    if (!val) { for (const k in obl) { const vv = n(obl[k]); if (vv > val) val = vv; } } // largest obligation
    return val > 0 ? Math.round(val) : null;
  } catch (_) { return null; }
}
async function fetchRlusdCoinGecko() {
  const url = 'https://api.coingecko.com/api/v3/coins/ripple-usd?localization=false&tickers=false&market_data=true&community_data=false&developer_data=false&sparkline=false';
  let j = null;
  try { const r = await fetchWithTimeout(url, MARKET_FETCH_TIMEOUT_MS); if (r.ok) j = await r.json(); } catch (e) {}
  if (!j || !j.market_data) { try { const { response } = await proxyFetch(url, MARKET_FETCH_TIMEOUT_MS); if (response && response.ok) j = await response.json(); } catch (e) {} }
  const m = (j && j.market_data) || {};
  const sup = n(m.circulating_supply) || n(m.total_supply);
  return sup > 0 ? Math.round(sup) : null;
}

// ── NEW FUNDED XRPL ACCOUNTS PER DAY (adoption) ────────────────────
// XRPScan daily ledger metrics (no API key). Returns an array of daily
// entries; each metric.accounts_created is the network-wide count of NEW
// funded accounts that day (unfunded/vanity keypairs never hit the Ledger,
// so this is the real adoption number). We take the most recent day.
async function fetchXrplDailyMetrics(){
  var url='https://api.xrpscan.com/api/v1/metrics/metric';
  var j=null;
  try { const r=await fetchWithTimeout(url, MARKET_FETCH_TIMEOUT_MS); if (r.ok) j=await r.json(); } catch(e){}
  if (!Array.isArray(j)){ try { const { response }=await proxyFetch(url, MARKET_FETCH_TIMEOUT_MS); if (response && response.ok) j=await response.json(); } catch(e){} }
  if (!Array.isArray(j) || !j.length) return null;
  // Use the most recent COMPLETE day (date < today UTC) — the current day is
  // only partially elapsed and would under-report (e.g. "+73" an hour in).
  var todayYmd=''; try { todayYmd=new Date().toISOString().slice(0,10); } catch(_){}
  var best=null, bestYmd='';
  for (var i=j.length-1;i>=0 && i>j.length-60;i--){
    var e=j[i]; if (!e || !e.date) continue;
    var d=String(e.date).slice(0,10);
    if (todayYmd && d>=todayYmd) continue;        // skip the in-progress current day
    if (d>bestYmd){ best=e; bestYmd=d; }
  }
  if (!best) best=j[j.length-1];                   // fallback: only today's partial exists
  var m=(best && best.metric) || {};
  var created=n(m.accounts_created);
  if (!(created>0)) return null;
  return { date:String(best.date||'').slice(0,10), accounts_created:created,
           transaction_count:n(m.transaction_count), payments_count:n(m.payments_count) };
}

async function market() {
  const notes = [];
  // 1. CoinGecko (primary)
  try {
    const r = await fetchWithTimeout('https://api.coingecko.com/api/v3/coins/xrp?localization=false&tickers=false&market_data=true&community_data=false&developer_data=false&sparkline=false', MARKET_FETCH_TIMEOUT_MS);
    if (r.ok) {
      const j = await r.json(), m = j.market_data || {};
      if (m.current_price?.usd)          $('inPrice').value = Number(m.current_price.usd).toFixed(4);
      if (m.price_change_percentage_24h != null) $('inDelta').value = Number(m.price_change_percentage_24h).toFixed(2);
      if (m.total_volume?.usd)           $('inVolume').value = Math.round(m.total_volume.usd);
      notes.push('✓ CoinGecko');
    } else notes.push('CoinGecko ' + r.status);
  } catch (e) { notes.push('CoinGecko ' + (/timeout/i.test(e.message) ? 'timeout' : 'blocked')); }
  // 2. Coinbase (price only fallback)
  try {
    if (!n($('inPrice').value)) {
      const r = await fetchWithTimeout('https://api.coinbase.com/v2/prices/XRP-USD/spot', MARKET_FETCH_TIMEOUT_MS);
      if (r.ok) { const j = await r.json(); $('inPrice').value = Number(j.data.amount).toFixed(4); notes.push('✓ Coinbase'); }
    }
  } catch (e) { notes.push('Coinbase ' + (/timeout/i.test(e.message) ? 'timeout' : 'blocked')); }
  // 3. CoinCap
  try {
    if (!n($('inPrice').value) || !n($('inVolume').value)) {
      const r = await fetchWithTimeout('https://api.coincap.io/v2/assets/xrp', MARKET_FETCH_TIMEOUT_MS);
      if (r.ok) {
        const j = await r.json(), d = j.data || {};
        if (!n($('inPrice').value)  && d.priceUsd)        $('inPrice').value = Number(d.priceUsd).toFixed(4);
        if (!n($('inDelta').value)  && d.changePercent24Hr) $('inDelta').value = Number(d.changePercent24Hr).toFixed(2);
        if (!n($('inVolume').value) && d.volumeUsd24Hr)   $('inVolume').value = Math.round(Number(d.volumeUsd24Hr));
        notes.push('✓ CoinCap');
      }
    }
  } catch (e) { notes.push('CoinCap ' + (/timeout/i.test(e.message) ? 'timeout' : 'blocked')); }
  // 4. CoinPaprika
  try {
    if (!n($('inVolume').value)) {
      const r = await fetchWithTimeout('https://api.coinpaprika.com/v1/tickers/xrp-xrp', MARKET_FETCH_TIMEOUT_MS);
      if (r.ok) {
        const j = await r.json(), q = (j.quotes && j.quotes.USD) || {};
        if (!n($('inPrice').value)  && q.price)            $('inPrice').value = Number(q.price).toFixed(4);
        if (!n($('inDelta').value)  && q.percent_change_24h != null) $('inDelta').value = Number(q.percent_change_24h).toFixed(2);
        if (!n($('inVolume').value) && q.volume_24h)       $('inVolume').value = Math.round(Number(q.volume_24h));
        notes.push('✓ CoinPaprika');
      }
    }
  } catch (e) { notes.push('CoinPaprika ' + (/timeout/i.test(e.message) ? 'timeout' : 'blocked')); }
  // 5. DefiLlama TVL
  try {
    const r = await fetchWithTimeout('https://api.llama.fi/chains', MARKET_FETCH_TIMEOUT_MS);
    if (r.ok) {
      const a = await r.json(), row = a.find(x => (x.name || '').toLowerCase() === 'xrpl evm');
      if (row) { $('inTvl').value = Math.round(row.tvl || 0); notes.push('✓ DefiLlama TVL'); }
    }
  } catch (e) { notes.push('DefiLlama TVL ' + (/timeout/i.test(e.message) ? 'timeout' : 'blocked')); }
  // 6. DefiLlama EVM DEX (direct → relay fallback; keep prior value on failure)
  try {
    const v = await fetchDefiDex('https://api.llama.fi/overview/dexs/xrpl-evm?excludeTotalDataChart=true&excludeTotalDataChartBreakdown=true&dataType=dailyVolume');
    if (v != null) { $('inDexvol').value = v; notes.push('✓ EVM DEX'); } else notes.push('EVM DEX empty');
  } catch (e) { notes.push('EVM DEX blocked'); }
  // 7. DefiLlama XRPL Native DEX (direct → relay fallback; keep prior value on failure)
  try {
    const v = await fetchDefiDex('https://api.llama.fi/overview/dexs/xrpl?excludeTotalDataChart=true&excludeTotalDataChartBreakdown=true&dataType=dailyVolume');
    if (v != null) { $('inXrpldex').value = v; notes.push('✓ Native DEX'); } else notes.push('Native DEX empty');
  } catch (e) { notes.push('Native DEX blocked'); }
  // 8. RLUSD supply — TWO independent sources in parallel (on-chain gateway +
  //    CoinGecko). Either one covers if the other fails; keep both to compare.
  try {
    const rl = await Promise.allSettled([ fetchRlusdGateway(), fetchRlusdCoinGecko() ]);
    const gwv = rl[0].status === 'fulfilled' ? rl[0].value : null;
    const cgv = rl[1].status === 'fulfilled' ? rl[1].value : null;
    state.rlusdSupplySources = { gateway: gwv, coingecko: cgv };
    // Prefer the authoritative on-chain figure; fall back to CoinGecko.
    const chosen = gwv || cgv;
    if (chosen) {
      state.rlusdSupply = chosen;
      let tag;
      if (gwv && cgv) tag = 'gateway+gecko ' + (Math.abs(gwv - cgv) / Math.max(gwv, cgv) < 0.02 ? 'agree' : 'diverge');
      else            tag = gwv ? 'gateway only' : 'gecko only';
      notes.push('✓ RLUSD supply (' + tag + ')');
    } else notes.push('RLUSD supply empty (both sources failed)');
  } catch (e) { notes.push('RLUSD supply error'); }
  // 9. New funded XRPL accounts per day (XRPScan daily metrics, no key).
  try {
    const dm = await fetchXrplDailyMetrics();
    if (dm) { state.xrplDaily = dm; notes.push('✓ XRPL accounts created +' + dm.accounts_created + ' on ' + dm.date); }
    else notes.push('XRPL daily metrics empty');
  } catch (e) { notes.push('XRPL daily metrics error'); }

  // Update HUD
  const price = n($('inPrice').value), delta = n($('inDelta').value), vol = n($('inVolume').value);
  setText('hudPrice', price ? '$' + price.toFixed(4) : '—');
  setText('hudPriceDelta', delta ? pct(delta) : '—');
  setText('hudVol', vol ? usd(vol) : '—');
  setText('hudDexNative', n($('inXrpldex').value) > 0 ? usd(n($('inXrpldex').value)) : '—');
  setText('hudDexEvm',    n($('inDexvol').value)  > 0 ? usd(n($('inDexvol').value))  : '—');
  setText('hudEvmTvl',    n($('inTvl').value)     > 0 ? usd(n($('inTvl').value))     : '—');
  return notes;
}

