    if (title.length < 12) broken = true;
    if (TRUNCATION_FRAGMENT_RE.test(title)) broken = true;
    if (/\.\.+$/.test(title)) broken = true;     // 2+ trailing dots (regex stripped one)
    if (/[-–—|]\s*$/.test(title)) broken = true;  // ends with separator
    if (/^\s*(unknown|none|n\/a|null)\s*$/i.test(title)) broken = true;
