  // ─── Part A: XAI_VOICE_PROFILE ─────────────────────────────
  var FEMALE_NAME_RE = /\b(samantha|victoria|karen|susan|zira|jenny|aria|hazel|tessa|moira|fiona|allison|ava|joanna|kimberly|salli|amy|emma|olivia|rachel|lily|amelie|celine|laura|sara|sofia|elsa|nora|ema|female|woman|girl)\b/i;
  var MALE_NAME_HINTS = /\b(male|man|david|mark|alex|daniel|fred|paul|tom|matthew|brian|justin|stephen|george|james|guy|james|mike)\b/i;
  var STORAGE_KEY_VOICE = 'shadowwatch_xai_voice_name_v1';

