        sections.market    = grab(/MARKET SNAPSHOT\s*\n([\s\S]*?)(?=\n\n[A-Z]|\nLEDGER STORY|$)/);
        sections.ledger    = grab(/LEDGER STORY\s*\n([\s\S]*?)(?=\n\n[A-Z]|\nREAL NEWS|\nPATTERN MEMORY|$)/);
        sections.realNews  = grab(/REAL NEWS\s*\n([\s\S]*?)(?=\n\n[A-Z]|\nPATTERN MEMORY|\nDISCOVERY|$)/);
