          if (m = l.match(/Ceiling \/ Resistance:\s*~?\$?([\d.]+|UNKNOWN)/i)) resistance = m[1];
          if (m = l.match(/Directional Bias:\s*([A-Z\-]+|UNKNOWN)/i))         bias = m[1];
