        if (action && action !== 'UNKNOWN')    s += '24 hour action ' + action + '. ';
        if (vol && vol !== 'UNKNOWN')          s += 'Volume ' + vol + '. ';
        if (support && support !== 'UNKNOWN')  s += 'Support near ' + support + '. ';
        if (resistance && resistance !== 'UNKNOWN') s += 'Resistance near ' + resistance + '. ';
