      var totalOut = outbound.reduce(function(s,t){ return s+t.amount_xrp; }, 0);
      var still_holding_estimate = Math.max(0, totalIn - totalOut);
      var rs = 0;
      if (outbound.length && large_outbound.length) rs += 30;
      if (repeat_counterparties.length >= 2)        rs += 20;
      if (tag_fragmentation.length)                 rs += 20;
      if (exchange_links.length)                    rs += 15;
      if (totalIn > 0 && still_holding_estimate < totalIn * 0.2) rs += 15;
