        address: address, tx_checked: txs.length,
        inbound_count: inbound.length, outbound_count: outbound.length,
        watched_links: watched_links, exchange_links: exchange_links,
        large_inbound: large_inbound.slice(0,5), large_outbound: large_outbound.slice(0,5),
        repeat_counterparties: repeat_counterparties, tag_fragmentation: tag_fragmentation,
