      if (result.exchange_links && result.exchange_links.length)
        notes.push('Exchange-adjacent flow: ' + result.exchange_links.length + ' exchange counterpart(s) in tx history.');
      if (result.watched_links && result.watched_links.length)
        notes.push('Connection to ' + result.watched_links.length + ' watched wallet(s) found in tx history.');
      if (result.repeat_counterparties && result.repeat_counterparties.length)
        notes.push('Repeat counterparty pattern: ' + result.repeat_counterparties.length + ' address(es) appear 3+ times.');
      if (result.tag_fragmentation && result.tag_fragmentation.length)
        notes.push('Destination tag fragmentation detected — possible routing indicator.');
      if (result.still_holding_estimate != null)
        notes.push('Estimated net holding after inflow/outflow: ~' + Math.round(result.still_holding_estimate).toLocaleString() + ' XRP (behavioral estimate only).');
