            lines.push('  reverseSearchHelpers   '+(g2.reverseSearch?'ENABLED':'DISABLED'));
            lines.push('  evidenceCollectors     '+(g2.evidenceCollectors?'ENABLED':'DISABLED'));
            lines.push('  coaches                DISABLED');
            lines.push('  helper_pool.enabled:   '+(g2.helper_pool_enabled?'true':'false'));
            lines.push('  helper_pool.jobs_created:   '+(g2.jobs_created||0));
            lines.push('  helper_pool.jobs_completed: '+(g2.jobs_completed||0));
            lines.push('  helper_pool.jobs_failed:    '+(g2.jobs_failed||0));
            lines.push('  reverse_search.wallets_checked: '+(g2.wallets_checked||0));
            lines.push('  evidence_collector.cards:   '+(g2.evidence_cards||0));
            lines.push('  bloom_queue.size:            '+(g2.queue_size||0));
            if (g2.skipped_reason) lines.push('  helper_pool.skipped_reason: '+g2.skipped_reason);
