// ── v3.29: RICHLIST INGEST UI render + wiring ─────────────────
function renderRichlistMetrics(meta) {
  const el = document.getElementById('rlMetrics');
  if (!el) return;
  if (!meta) { el.style.display = 'none'; return; }
  el.style.display = 'block';
  el.innerHTML =
    '<b>RAW ROWS:</b> ' + (meta.raw_rows||0).toLocaleString() + ' &nbsp;|&nbsp; ' +
    '<b>UNIQUE:</b> ' + (meta.unique_addresses||0).toLocaleString() + ' &nbsp;|&nbsp; ' +
    '<b>DUPES REMOVED:</b> ' + (meta.duplicate_rows_removed||0).toLocaleString() + '<br>' +
    '<b>INVALID:</b> ' + (meta.invalid_addresses_removed||0) + ' &nbsp;|&nbsp; ' +
    '<b>IDENTITIES RESOLVED:</b> ' + (meta.identities_resolved||0).toLocaleString() + ' &nbsp;|&nbsp; ' +
    '<b>UNKNOWN:</b> ' + (meta.identities_unknown||0).toLocaleString() + '<br>' +
    '<b>TOP BALANCE:</b> ' + Math.round(meta.top_balance_xrp||0).toLocaleString() + ' XRP &nbsp;|&nbsp; ' +
    '<b>IMPORTED:</b> ' + (meta.imported_at ? meta.imported_at.slice(0,19).replace('T',' ') : '—');
}
function renderRichlistSuggestions() {
  const universe = (typeof state !== 'undefined') ? (state.richlistUniverse||{}) : {};
  const watched  = (typeof KNOWN !== 'undefined') ? KNOWN : {};
  const el    = document.getElementById('rlSuggestionList');
  const badge = document.getElementById('rlBadge');
  if (!el) return;
  const entries = Object.entries(universe)
    .filter(([a, r]) => !watched[a] && (r.balance_xrp_normalized||0) >= 1_000_000)
    .sort((a, b) => (b[1].balance_xrp_normalized||0) - (a[1].balance_xrp_normalized||0))
    .slice(0, 50);
  if (badge) badge.textContent = Object.keys(universe).length.toLocaleString() + ' ADDRS';
  if (!entries.length) {
    el.innerHTML = '<div style="color:rgba(0,255,0,0.35);text-align:center;padding:16px 0">No candidates ≥1M XRP outside watchlist.</div>';
    return;
  }
  el.innerHTML = entries.map(([addr, rec]) => {
    const balM = ((rec.balance_xrp_normalized||0)/1_000_000).toFixed(1);
    const id   = rec.identity_clean || '—';
    const sh   = addr.slice(0,8) + '…' + addr.slice(-6);
    return '<div class="awf-row" style="margin-bottom:3px"><div class="awf-addr">' + sh +
           '</div><div class="awf-meta">Rank #' + rec.source_rank_min + ' · <b>' + balM +
           'M XRP</b></div><div class="awf-meta" style="opacity:0.7">' + id + '</div></div>';
  }).join('');
}
