// Top-N large transfers as compact human-readable lines
function renderTopLargeTransfers(largeTransfers, max) {
  if (!Array.isArray(largeTransfers) || !largeTransfers.length) return [];
  const sorted = [...largeTransfers].sort((a, b) => n(b.amount) - n(a.amount));
  // v3.34: collapse identical sender→receiver→amount transfers (e.g. a repeated
  // watchlist-internal move) into one line with an ×N count, so LARGE MOVES
  // doesn't print the same transfer four times.
  const seen = {};
  const deduped = [];
  sorted.forEach(t => {
    // v3.36: both ends go through _swWho, so a wallet the registry can identify
    // is NAMED here instead of printing the internal handle we track it by.
    let sender = _swWho(t.from, t.sender_label || t.label);
    let recvLabel = _swWho(t.to, (t.receiver_label && t.receiver_label !== 'UNKNOWN') ? t.receiver_label : null);
    // Two different wallets of the same entity resolve to the same name, and
    // "Binance → Binance" hides the fact that these are two distinct addresses.
    // Keep the name — it is the true answer — and add the address that tells
    // them apart.
    if (sender === recvLabel && t.from && t.to && t.from !== t.to) {
      sender    += ' ' + ca(t.from);
      recvLabel += ' ' + ca(t.to);
    }
    const amt = fmt(n(t.amount), 0);
    const cls = _swCls(t.classification);
    const conf = _swConf(t.confidence);
    const key = sender + '>' + recvLabel + '>' + amt + '>' + cls;
    if (seen[key] != null) { deduped[seen[key]].count++; return; }
    seen[key] = deduped.length;
    deduped.push({ sender: sender, recvLabel: recvLabel, amt: amt, cls: cls, conf: conf,
                   sig: _sigPhrase(t), count: 1 });
  });
  return deduped.slice(0, max || 5).map(d =>
    '• ' + d.sender + ' → ' + d.recvLabel + ' · ' + d.amt + ' XRP · ' + d.cls + ' [' + d.conf + ']' +
    d.sig + (d.count > 1 ? ' ×' + d.count : '')
  );
}

// Receiver followthrough — surface meaningful next-hop behavior
function renderReceiverFollowthrough(receivers, max) {
  if (!Array.isArray(receivers) || !receivers.length) return [];
  const filtered = receivers.filter(r => r && r.address);
  const sorted = filtered.sort((a, b) => n(b.forwarded_large_count) - n(a.forwarded_large_count));
  const top = sorted.slice(0, max || 5);
  return top.map(r => {
    const who = _swWho(r.address, r.label, { bare: true });
    const bal = r.balance_xrp != null ? fmt(n(r.balance_xrp), 0) + ' XRP' : 'balance unknown';
    const fwd = n(r.forwarded_large_count);
    const fwdNote = fwd > 0
      ? 'forwarded ' + fwd + ' large tx (' + fmt(n(r.forwarded_large_total_xrp), 0) + ' XRP)'
      : 'held — no large forward';
    const cls = _swCls(r.classification || 'NEXT_HOP_HOLDING');
    const age = r.age_hours != null ? ', account ' + _ageText(r.age_hours) : '';
    return '• ' + who + ': ' + bal + age + ', ' + fwdNote + ' · ' + cls + ' [' + _swConf(r.confidence) + ']';
  });
}

// Coordination memory — only when enough snapshots AND named pairs with real score
// v3.19: Filter out placeholder pairs (missing labels) and zero-score pairs.
// If snapshots are sufficient but no valid named pair survives, show a
// truthful "enough snapshots but no strong named pair" line instead of
// fabricating "wallet A + wallet B, same-hour score 0".
function renderCoordinationMemory(coord) {
  if (!coord) return { lines: [], gating: 'Need 5+ snapshots. Current: 0.' };
  const snaps = n(coord.snapshots_analyzed);
  if (snaps < 5) {
    return { lines: [], gating: 'Need 5+ snapshots. Current: ' + snaps + '.' };
  }
  const pairs = Array.isArray(coord.pairs) ? coord.pairs : [];

  // v3.19: defensive filter — drop pairs with placeholder labels or score <= 0
  const PLACEHOLDER = /^(wallet\s*[ab]?|unknown|null|undefined|\s*|none)$/i;
  const hasRealLabel = (lbl) => typeof lbl === 'string' && lbl.trim() && !PLACEHOLDER.test(lbl);
  const named = pairs.filter(p => {
    const a = p.label_a || p.a || '';
    const b = p.label_b || p.b || '';
    return hasRealLabel(a) && hasRealLabel(b) && n(p.score) > 0;
  });

  if (!pairs.length) {
    return { lines: ['• ' + snaps + ' snapshots analyzed. No coordinated pairs surfaced.'], gating: null };
  }
  if (!named.length) {
    // Snapshots present, pairs returned, but none survive the truth filter
    return {
      lines: ['• Coordination memory has enough snapshots (' + snaps +
              '), but no strong named pair is ready for public display.'],
      gating: null
    };
  }

  const sorted = [...named].sort((a, b) => n(b.score) - n(a.score));
  const top = sorted.slice(0, 3);
  const lines = ['• ' + sorted.length + ' coordinated pair(s) detected across ' + snaps + ' scans.'];
  top.forEach((pair, i) => {
    const labelA = pair.label_a || pair.a;
    const labelB = pair.label_b || pair.b;
    const tag = i === 0 ? 'Strongest' : (i === 1 ? 'Secondary' : 'Tertiary');
    lines.push('• ' + tag + ': ' + labelA + ' + ' + labelB + ', same-hour score ' + n(pair.score) + '.');
  });
  return { lines, gating: null };
}

// Normalize risk label — never silently downgrade the internal label.
// Returns { internal, public, combined }
function normalizeRiskLabel(pack) {
  const r = (pack && pack.risk_score) || state.riskScore || {};
  const score = n(r.score);
  const internal = r.label || (
    score >= 75 ? 'BLACK / EXTREME' :
    score >= 50 ? 'ORANGE / ACTIVE' :
    score >= 25 ? 'YELLOW / WATCH' : 'GREEN / QUIET'
  );
  let publicLabel;
  if (score >= 75)      publicLabel = 'HIGH / FORENSICS WATCH';
  else if (score >= 50) publicLabel = 'ELEVATED / MONITOR';
  else if (score >= 25) publicLabel = 'MODERATE / WATCH';
  else                  publicLabel = 'LOW / QUIET';
  // Combined form for public display — keeps internal label visible.
  const combined = score + '/100 — ' + internal +
    (internal !== publicLabel ? ' (' + publicLabel + ')' : '');
  return { score, internal, public: publicLabel, combined };
}

// Build the dynamic Daily Report.
// modes:
//   'text'  — plaintext, raw URLs in Sources block (for downloads)
//   'html'  — HTML, clickable Sources block (for on-screen viewer)
//   'agent' — plaintext with explicit structured Sources section for GPT
function buildDynamicDailyReport(pack, mode) {
  mode = mode || 'text';
  pack = pack || state.pack || {};
  // Base text body — reuses existing buildXRPMainReport which now
  // includes the new sections (large moves, receivers, coordination,
  // source note). The plain-text sources block is appended below.
  const baseText = (typeof buildXRPMainReport === 'function')
    ? buildXRPMainReport(pack)
    : '';
  const sourcesRanked = rankNewsItems(getNewsSources(pack)).slice(0, 8);

  if (mode === 'html') {
    // HTML mode: strip the baked plain-text SOURCES block (added by
    // buildXRPMainReport in v3.19), then escape the body and append a
    // clickable Sources block.
    const cleaned = baseText.replace(/\n{1,3}SOURCES[\s\S]*$/m, '').trimEnd();
    const bodyHTML = '<pre class="cmd-report-pre">' + escapeHTML(cleaned) + '</pre>';
    const sourcesHTML = renderClickableSources(sourcesRanked);
    return bodyHTML + sourcesHTML;
  }

  // v3.19: text / agent modes no longer double-append SOURCES — buildXRPMainReport
  // now includes a SOURCES block by default. We still produce the structured
  // status meta for 'agent' mode and strip the duplicate sources block from
  // baseText if a caller happens to invoke buildXRPMainReport again externally.
  if (mode === 'agent') {
    const health = getSourceHealth(pack);
    const meta = [
      '',
      'STRUCTURED SOURCE STATUS',
      'degraded: ' + (health.degraded ? 'true' : 'false'),
      'partial_coverage: ' + (health.partial_coverage ? 'true' : 'false'),
      'failed_providers: ' + (health.failed.length ? health.failed.join(', ') : 'none'),
      'ok_providers: ' + (health.ok.length ? health.ok.join(', ') : 'none'),
      'headline_count: ' + n(health.headline_count),
      'source_group_count: ' + n(health.source_group_count)
    ].join('\n');
    return baseText + meta;
  }
  // text mode: baseText already includes SOURCES from buildXRPMainReport
  return baseText;
}

// Expose helpers on window for smoke tests / external use
if (typeof window !== 'undefined') {
  window.getNewsSources = getNewsSources;
  window.rankNewsItems = rankNewsItems;
  window.filterSourcesForReport = filterSourcesForReport;
  window.renderClickableSources = renderClickableSources;
  window.renderPlainTextSources = renderPlainTextSources;
  window.getSourceHealth = getSourceHealth;
  window.buildDynamicDailyReport = buildDynamicDailyReport;
  window.normalizeRiskLabel = normalizeRiskLabel;
  window.escapeHTML = escapeHTML;
  window.validateURL = validateURL;
}

function buildExecutiveSummary(p, netDelta, news) {
  const price = n(p.xrp_price);
  const delta24 = p.xrp_delta_24h_pct;
  const tape = (delta24 == null) ? 'an unmeasured tape'
             : (delta24 > 3) ? 'a green tape'
             : (delta24 < -3) ? 'a red tape'
             : (Math.abs(delta24) < 1) ? 'a flat tape'
             : (delta24 < 0) ? 'a soft tape' : 'a firm tape';
  const dir = netDelta > 0 ? 'gained' : netDelta < 0 ? 'lost' : 'remained flat at';
  const absStr = fmt(Math.abs(netDelta), 0);
  const priceStr = price ? '$' + price.toFixed(4) : '—';
  // v3.26: News framing — only mention news if news is HEALTHY or EVIDENCE_LED.
  // PARTIAL_CONTEXT / LEDGER_ONLY → no news line in executive summary.
  // v3.26-hotfix9: prefer STRONG matched articles from the router; fall back
  // to MEDIUM; never use WEAK in the executive summary. Toned-down framing
  // — "active context" instead of "matters" — to avoid overclaiming.
  let newsLine = '';
  if (typeof isNewsUsableForNarrative === 'function' && isNewsUsableForNarrative(p)) {
    // First try router matched_articles filtered to STRONG/MEDIUM
    const matched = (p.news_intelligence_router && p.news_intelligence_router.matched_articles) || [];
    // v16.9: prefer a headline that actually mentions XRP over one that merely
    // matched a trigger keyword. On 2026-08-12 the router's first MEDIUM match
    // was "Bitcoin Chart Mimics Exact Pattern That Sparked 2023 Rally" — it hit
    // on a macro keyword — so the executive summary offered a Bitcoin chart
    // story as XRP news context while a Ripple/CLARITY Act headline sat second
    // in the same list AND was what GLOBAL SYNC printed four lines later. Two
    // sections of one report naming different top stories reads like an error,
    // because it is one. Strength still comes first; XRP-relevance breaks ties.
    const xrpRe = /(XRP|Ripple|XRPL|RLUSD|Clarity Act|ETF|SBI|Japan|Korea|Hidden Road|Standard Custody|Bullish|Uphold|Upbit|Bithumb)/i;
    const rel = (strength) => matched.find(a => a.match_strength === strength && xrpRe.test(a.title || ''));
    const any = (strength) => matched.find(a => a.match_strength === strength);
    // The router RANKS candidates; it must not FILTER them. On 2026-08-12 19:08
    // its only MEDIUM match was a Bitcoin chart story — the Ripple/CLARITY Act
    // headline never entered matched_articles at all — so both this line and
    // GLOBAL SYNC printed a Bitcoin piece as XRP news context while a directly
    // relevant headline sat unused in the pool. An XRP-relevant headline now
    // wins over an off-topic router match wherever one exists, at any strength;
    // only when nothing in the whole pool mentions XRP do we fall back to the
    // router's own top pick.
    const strongOrMedium = rel('STRONG') || rel('MEDIUM') ||
                           (news || []).find(h => xrpRe.test(h.title || '')) ||
                           any('STRONG') || any('MEDIUM');
    if (strongOrMedium && strongOrMedium.title) {
      newsLine = ` Active news context (not causation proof): ${_asSentence(_stripPublisherSuffix(strongOrMedium.title))}`;
    } else {
      // Fall back to top XRP-tagged headline if no STRONG/MEDIUM router match
      const topXrp = news.find(h => xrpRe.test(h.title || ''));
      if (topXrp) {
        newsLine = ` Active news context (not causation proof): ${_asSentence(_stripPublisherSuffix(topXrp.title))}`;
      }
    }
  }
  // v16.21: with no stored baseline, "remained flat at 0 XRP net" is a claim we
  // cannot make. Say what is actually true — there is nothing to compare to yet.
  const _db = deltaBaseline(p);
  const boardClause = _db.none
    ? `the tracked wallet board has no prior balances on this device yet, so net flow is not measurable on this run`
    : `the tracked wallet board ${dir} ${absStr} XRP net versus the local snapshot`;
  return `Today's scan shows institutional-style rotation under ${tape}: XRP sits near ${priceStr}, while ${boardClause}.${_db.partial ? ' ' + _db.line : ''}${newsLine}`;
}

// Build per-group Shadow Watch bullets with 🟢🟡🔴 indicator
function shadowWatchSection(buckets, p) {
  const lines = [];
  // Helper: classify a group's biggest move
  function indicator(maxAbsDelta) {
    if (maxAbsDelta >= 5_000_000) return '🔴';
    if (maxAbsDelta >= 100_000)   return '🟡';
    return '🟢';
  }
  // Helper: format a top mover description for a group
  function moverPhrase(walletsInGroup) {
    if (!walletsInGroup || !walletsInGroup.length) return null;
    const sorted = [...walletsInGroup].sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta));
    const top = sorted[0];
    if (Math.abs(top.delta) < 100) return null;
    const verb = top.delta > 0 ? 'gained' : 'lost';
    const sign = top.delta > 0 ? '+' : '-';
    return `${_swWho(top.address, top.label, { bare: true })} ${verb} ${sign}${fmt(Math.abs(top.delta), 0)} XRP`;
  }
  function topMoversList(walletsInGroup, max) {
    if (!walletsInGroup) return [];
    return [...walletsInGroup]
      .filter(w => Math.abs(w.delta) >= 100)
      .sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta))
      .slice(0, max || 2)
      .map(w => `${_swWho(w.address, w.label, { bare: true })} ${w.delta > 0 ? 'gained' : 'dropped'} ${w.delta > 0 ? '+' : '-'}${fmt(Math.abs(w.delta), 0)} XRP`);
  }

  // 1. Ripple Escrow / Corporate Hubs
  const ripple = buckets.ripple_corp || [];
  if (ripple.length) {
    const maxAbs = Math.max(0, ...ripple.map(w => Math.abs(w.delta)));
    const ind = indicator(maxAbs);
    const phrase = moverPhrase(ripple);
    if (maxAbs < 1000) {
      lines.push(`• ${ind} Ripple Escrow Hubs: checked; no local balance shock.`);
    } else {
      lines.push(`• ${ind} Ripple Escrow Hubs: ${phrase || 'mixed activity across ' + ripple.length + ' wallets'}.`);
    }
  }
  // 2. Binance nodes (filter exchange wallets by name)
  const exchanges = buckets.exchange || [];
  const binance = exchanges.filter(w => /BINANCE/i.test(w.label));
  if (binance.length) {
    const maxAbs = Math.max(0, ...binance.map(w => Math.abs(w.delta)));
    const ind = indicator(maxAbs);
    const movers = topMoversList(binance, 1);
    if (maxAbs < 1000) {
      lines.push(`• ${ind} Binance Nodes: major Binance cold nodes flat; no material movement.`);
    } else {
      lines.push(`• ${ind} Binance Nodes: ${movers.join('; ') || 'mixed flow across ' + binance.length + ' nodes'}.`);
    }
  }
  // 3. Upbit hubs
  const upbit = exchanges.filter(w => /UPBIT/i.test(w.label));
  if (upbit.length) {
    const maxAbs = Math.max(0, ...upbit.map(w => Math.abs(w.delta)));
    const movers = topMoversList(upbit, 1);
    lines.push(`• ${indicator(maxAbs)} Upbit Hubs: ${movers[0] || (upbit.length + ' Upbit wallets quiet')}.`);
  }
  // 4. Coinbase / Gateway
  const coinbase = exchanges.filter(w => /COINBASE|GATEWAY/i.test(w.label));
  if (coinbase.length) {
    const maxAbs = Math.max(0, ...coinbase.map(w => Math.abs(w.delta)));
    const movers = topMoversList(coinbase, 1);
    lines.push(`• ${indicator(maxAbs)} Coinbase/Gateway: ${movers[0] || 'flat'}.`);
  }
  // 5. Other named exchanges (Bithumb, Uphold, Bitstamp, Bybit, OKX, Crypto.com, etc.)
  const otherExch = exchanges.filter(w => !/BINANCE|UPBIT|COINBASE|GATEWAY/i.test(w.label));
  if (otherExch.length) {
    const maxAbs = Math.max(0, ...otherExch.map(w => Math.abs(w.delta)));
    const movers = topMoversList(otherExch, 2);
    if (movers.length) {
      lines.push(`• ${indicator(maxAbs)} Exchange Custody (other): ${movers.join('; ')}.`);
    } else {
      lines.push(`• 🟢 Exchange Custody (other): ${otherExch.length} wallets quiet across Bithumb, Uphold, Bitstamp, Bybit, OKX tier.`);
    }
  }
  // 6. Whale / Institutional Custody Nodes
  const whales = [...(buckets.whale || []), ...(buckets.institutional || []), ...(buckets.genesis_whale || [])];
  if (whales.length) {
    const maxAbs = Math.max(0, ...whales.map(w => Math.abs(w.delta)));
    const movers = topMoversList(whales, 3);
    if (movers.length) {
      lines.push(`• ${indicator(maxAbs)} Custody/Whale Nodes: ${movers.join('; ')}.`);
    } else {
      lines.push(`• 🟢 Custody/Whale Nodes: ${whales.length} whale wallets quiet.`);
    }
  }
  // v3.10: 6b. Multi-sig Cluster — linked custody (treat group total as significant)
  const msig = buckets.msig_cluster || [];
  if (msig.length) {
    const totalDelta = msig.reduce((s, w) => s + w.delta, 0);
    const totalBal = msig.reduce((s, w) => s + n(w.balance_xrp), 0);
    const maxAbs = Math.max(0, ...msig.map(w => Math.abs(w.delta)));
    if (maxAbs < 100) {
      lines.push(`• 🟢 Linked Multi-sig Cluster (${msig.length} wallets, ~${fmt(totalBal, 0)} XRP combined): all quiet, cluster cohesive.`);
    } else {
      const movers = topMoversList(msig, 3);
      const arrow = totalDelta > 0 ? '+' : '';
      lines.push(`• ${indicator(maxAbs)} Linked Multi-sig Cluster: ${movers.join('; ')}. Cluster net ${arrow}${fmt(totalDelta, 0)} XRP — investigate as ONE entity, not three.`);
    }
  }
  // v3.10: 6c. Market Makers — high-frequency, treat differently
  const mm = buckets.market_maker || [];
  if (mm.length) {
    const maxAbs = Math.max(0, ...mm.map(w => Math.abs(w.delta)));
    const movers = topMoversList(mm, 2);
    if (maxAbs < 100) {
      lines.push(`• 🟢 Market Makers: ${mm.length} bot wallets quiet this window.`);
    } else {
      lines.push(`• 🟡 Market Makers: ${movers.join('; ')}. High-frequency arbitrage — informational, not directional.`);
    }
  }
  // 7. Founder wallets (Arthur Britto + Chris Larsen) — always significant
  const founders = buckets.founder || [];
  if (founders.length) {
    const maxAbs = Math.max(0, ...founders.map(w => Math.abs(w.delta)));
    const movers = topMoversList(founders, 2);
    if (maxAbs < 100) {
      lines.push(`• 🟢 Founder Wallets: ${founders.length} founder wallets (Britto / Larsen) quiet. Historically rare to move.`);
    } else {
      lines.push(`• 🔴 Founder Wallets: ${movers.join('; ')}. HISTORICALLY RARE — investigate.`);
    }
  }
  // 8. Dormant whales
  const dormant = buckets.dormant || [];
  if (dormant.length) {
    const maxAbs = Math.max(0, ...dormant.map(w => Math.abs(w.delta)));
    if (maxAbs < 100) {
      lines.push(`• 🟢 Dormant Whales: still dormant.`);
    } else {
      const movers = topMoversList(dormant, 2);
      lines.push(`• 🔴 Dormant Whales: ${movers.join('; ')}. HIGH-SIGNIFICANCE awakening.`);
    }
  }
  // 9. Failed / invalid — yellow if any
  const failed = (p.wallets_failed || 0);
  const invalid = (p.wallets_invalid || 0);
  if (failed > 0 || invalid > 0) {
    const failedNames = ((p.wallet_results || []).filter(w => w.status === 'failed' || w.status === 'invalid') || [])
      .map(w => w.label).slice(0, 4).join(', ');
    // v16.10: 162 of 197 unreadable is not a yellow footnote. Escalate with the
    // share of the board that went dark, and say what it costs the report.
    const _c = scanCoverage(p);
    lines.push(_c.severe
      ? `• 🔴 Failed/Invalid: ${failed} failed, ${invalid} invalid${failedNames ? ' (' + failedNames + ')' : ''}. ` +
        `Only ${_c.percent}% of the board was readable — every figure in this report is a partial read, and no "quiet" finding is confirmed.`
      : `• 🟡 Failed/Invalid: ${failed} failed, ${invalid} invalid${failedNames ? ' (' + failedNames + ')' : ''}. Excluded from scoring.`);
  }
  // 10. The Ghosts — dust noise / receiver activity
  const ghosts = (p.dust_noise_count || 0) + ((p.receiver_followthrough || []).filter(r => r.forwarded_large_count > 0).length);
  if (ghosts > 0) {
    lines.push(`• 🟢 THE GHOSTS: ${ghosts} small forwards / dust noise flagged. Microscopic totals — exchange-tag noise, not proven banking fragmentation.`);
  } else {
    lines.push(`• 🟢 THE GHOSTS: no dust pattern flagged this window.`);
  }
  return lines;
}

// Anomaly detection — picks the biggest non-trivial delta and writes Event + Evidence
function anomalySection(buckets, p, netDelta) {
  const results = p.wallet_results || [];
  const sorted = [...results]
    .map(w => ({ ...w, delta: n(w.balance_xrp) - n(w.prev_balance_xrp) }))
    .filter(w => Math.abs(w.delta) >= 100_000)
    .sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta));

  if (!sorted.length) {
    return [
      '• Event: No statistically significant balance anomaly this window.',
      '• Evidence: Largest delta below the 100k XRP threshold. Board is in baseline drift.'
    ];
  }
  const top = sorted[0];
  const evmTvl = n(p.xrpl_evm_tvl_usd);
  const evmDexVol = n(p.xrpl_evm_dex_volume_24h_usd);
  const bridgeQuiet = evmDexVol < 100_000;
  const event = bridgeQuiet
    ? 'Large balance rotation without EVM bridge confirmation.'
    : 'Large balance rotation with active EVM bridge flow.';

  // Build evidence string from top 4 movers
  const movers = sorted.slice(0, 4)
    .map(w => `${_swWho(w.address, w.label, { bare: true })} ${w.delta > 0 ? 'gained +' : 'fell -'}${fmt(Math.abs(w.delta), 0)} XRP`);
  const conclusion = bridgeQuiet
    ? 'That points to custody/exchange reshuffling more than sidechain exit traffic.'
    : 'Bridge flow plus wallet rotation suggests cross-rail rebalancing.';
  const netStr = (netDelta > 0 ? '+' : '') + fmt(netDelta, 0);
  return [
    `• Event: ${event}`,
    `• Evidence: Watchlist delta came in at ${netStr} XRP. ${movers.join(', ')}. ${conclusion}`
  ];
}

// Global Sync — pull XRP/banking headlines, distill into Bank Move + Hidden Narrative
// v3.26-hotfix9: prefer STRONG/MEDIUM matched_articles from the router; tone-down
// "Hidden Narrative" language from "liquidity pipes are being built around the asset"
// to "headlines align with theme X — context, not causation proof."
function globalSyncSection(news, p) {
  if (!news || !news.length) {
    return [
      '• Bank/Institutional Headline: No verified headlines loaded this window. Operator-supplied context (if any) is in the master package.',
      '• Theme Read: News lane offline. Ledger evidence stands alone today.'
    ];
  }
  // v3.26-hotfix9: prefer STRONG/MEDIUM router-matched articles when available
  const routerMatched = (p && p.news_intelligence_router && p.news_intelligence_router.matched_articles) || [];
  const strongOrMedium = routerMatched.filter(a =>
    a.match_strength === 'STRONG' || a.match_strength === 'MEDIUM'
  );
  // Pick top banking/institutional/regulatory headline for the "Bank/Institutional Headline" slot
  const bankRe = /(bank|institution|prime|brokerage|custody|swift|payment|partnership|ETF|ruling|Clarity|stablecoin|RLUSD|Bullish|Hidden Road|Standard Custody|SBI|Bitwise)/i;
  let bankHl;
  // Same rule as the executive summary: a router match that is not actually
  // banking/institutional loses to a pool headline that is. Without this step
  // the slot printed "Bitcoin Chart Mimics Exact Pattern That Sparked 2023
  // Rally" under the label "Bank/Institutional Headline", with a Theme Read
  // about ETF approvals underneath it.
  bankHl = strongOrMedium.find(a => bankRe.test(a.title || '')) ||
           news.find(h => bankRe.test(h.title || '')) ||
           strongOrMedium[0] || news[0];
  const bankTitle = (bankHl.title || '').replace(/\s*[-—–|]\s*[^-—–|]+$/, '');
  // For Theme Read, look at the cluster of themes — count news themes
  const themes = { etf: 0, japan: 0, korea: 0, regulation: 0, custody: 0, partnership: 0, stablecoin: 0 };
  news.forEach(h => {
    const t = (h.title || '').toLowerCase();
    if (/etf|grayscale|bitwise|21shares/i.test(t)) themes.etf++;
    if (/japan|sbi/i.test(t)) themes.japan++;
    if (/korea|upbit|bithumb/i.test(t)) themes.korea++;
    if (/clarity|fit21|regulation|sec|ruling|legal/i.test(t)) themes.regulation++;
    if (/custody|hidden road|standard custody|prime/i.test(t)) themes.custody++;
    if (/partnership|integration|collaboration/i.test(t)) themes.partnership++;
    if (/rlusd|stablecoin/i.test(t)) themes.stablecoin++;
  });
  const sorted = Object.entries(themes).sort((a, b) => b[1] - a[1]).filter(t => t[1] > 0);
  const themeLabels = { etf: 'ETF approvals', japan: 'Japan/SBI integration', korea: 'Korean exchange activity',
                        regulation: 'regulatory clarity', custody: 'custody rails', partnership: 'banking partnerships', stablecoin: 'RLUSD/stablecoin' };
  // v3.26-hotfix9: toned-down "Theme Read" — was "Hidden Narrative" with strong
  // claims about "liquidity pipes being built". New language frames it as context.
  let hidden;
  if (sorted.length >= 2) {
    hidden = `Headlines align with ${themeLabels[sorted[0][0]]} and ${themeLabels[sorted[1][0]]} themes — context, not causation proof. Watch cross-flow.`;
  } else if (sorted.length === 1) {
    hidden = `Headlines lean toward ${themeLabels[sorted[0][0]]} — active context, not causation proof.`;
  } else {
    hidden = 'No dominant theme this window. Wallet movement stands on its own.';
  }
  return [
    `• Bank/Institutional Headline: ${_asSentence(bankTitle)}`,
    `• Theme Read: ${hidden}`
  ];
}

// Verdict — Support / Resistance / Directional Bias
function verdictSection(p, netDelta, delta24) {
  const sup = n(p.support);
  const res = n(p.resistance);
  // Directional bias: combine price delta + wallet delta + risk
  const risk = n(p.risk_score?.score);
  let biasScore = 0;
  if (delta24 != null) biasScore += delta24 > 0 ? 1 : delta24 < 0 ? -1 : 0;
  if (netDelta > 5_000_000) biasScore += 1;
  else if (netDelta < -5_000_000) biasScore -= 1;
  if (risk >= 60) biasScore -= 1;
  let biasLabel = 'NEUTRAL';
  if (biasScore >= 2)       biasLabel = 'BULLISH';
  else if (biasScore === 1) biasLabel = 'NEUTRAL-BULLISH';
  else if (biasScore === -1) biasLabel = 'NEUTRAL-BEARISH';
  else if (biasScore <= -2) biasLabel = 'BEARISH';

  const commentary = (biasScore <= 0)
    ? 'Price is soft, but wallet deltas are not dead. The next tell is whether inflows continue or reverse into exchange-side sell pressure.'
    : (biasScore >= 2)
      ? 'Price and wallet rotation both lean constructive. Confirmation comes from whether large transfers follow the price into next session.'
      : 'Mixed signals: price drifting while wallets reposition. Watch the next 24h for resolution.';

  return [
    `[Support: $${sup.toFixed(4)} | Resistance: $${res.toFixed(4)}]`,
    `[Directional Bias: ${biasLabel}]. ${commentary}`
  ];
}

// Mission Debrief — plain-language synthesis
function missionDebrief(buckets, p, netDelta, news) {
  const parts = [];
  parts.push('Plain talk:');
  // Price
  const delta24 = p.xrp_delta_24h_pct;
  const priceQual = delta24 == null ? 'unmeasured' : delta24 < -1 ? 'soft' : delta24 > 1 ? 'firm' : 'flat';
  parts.push(`XRP price is ${priceQual},`);
  // Wallet board
  if (Math.abs(netDelta) > 1_000_000) {
    parts.push(`but the wallet board moved.`);
  } else {
    parts.push(`and the wallet board was relatively quiet.`);
  }
  // Largest mover
  const results = (p.wallet_results || [])
    .map(w => ({ ...w, delta: n(w.balance_xrp) - n(w.prev_balance_xrp) }))
    .filter(w => Math.abs(w.delta) > 100_000)
    .sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta));
  if (results.length) {
    const top3 = results.slice(0, 3).map(w =>
      `${_swWho(w.address, w.label, { bare: true })} ${w.delta > 0 ? 'gained' : 'bled'} ${fmt(Math.abs(w.delta), 0)} XRP`
    ).join(', ');
    parts.push(top3 + '.');
  }
  // EVM bridge
  const evmVol = n(p.xrpl_evm_dex_volume_24h_usd);
  parts.push(evmVol > 100_000 ? 'The EVM bridge saw active flow.' : 'The EVM bridge stayed quiet.');
  // v3.26-hotfix1: News framing — only run when news is HEALTHY_CONTEXT
  // or EVIDENCE_LED_CONTEXT. PARTIAL/LEDGER_ONLY → no institutional narrative.
  const health = (p && p.news_health) ||
                 (typeof computeNewsHealth === 'function' ? computeNewsHealth(p) : null);
  const newsUsable = health && (health.newsMode === 'HEALTHY_CONTEXT' || health.newsMode === 'EVIDENCE_LED_CONTEXT');
  if (newsUsable && news && news.length) {
    const xrpRe = /(RLUSD|prime|broker|custody|Clarity|ETF|partnership|institutional)/i;
    if (news.some(h => xrpRe.test(h.title || ''))) {
      // v3.29-hotfix1: toned down — was "institutional rails — prime brokerage..."
      // which overstated causation. Replaced with measured context framing.
      parts.push('Institutional and regulatory headlines are active context, not causation proof.');
    }
  } else if (health && (health.newsMode === 'PARTIAL_CONTEXT' || health.newsMode === 'LEDGER_ONLY')) {
    parts.push('Broader institutional context was not strong enough this scan to use as narrative evidence; ledger evidence remains primary.');
  }
  return parts.join(' ');
}

// ── INTEL BRIEF ───────────────────────────────────────────────
// ── INTEL BRIEF VOICE ──────────────────────────────────────────
// Sections 2, 6 and 7 used to be hardcoded strings — byte-identical in every
// report ever produced, telling the operator to do the same four things whether
// the scan had found a drained bridge or nothing at all. A brief that cannot
// change is not intelligence, it is letterhead. These pools rotate by date the
// same way the scripture and prayer pools do, and the two sections that should
// respond to findings now do.
const INTEL_SIGNAL_FRAMES = [
  'Money moved and the board recorded it.',
  'The ledger\u2019s own accounting for the window:',
  'Here is the arithmetic, before anyone interprets it:',
  'Raw movement first \u2014 interpretation comes after.',
  'What the window actually contained:',
  'Counted, not estimated:',
  'The numbers as the ledger reports them:',
  'Straight totals, no adjustment:'
];
const INTEL_BEHAVIOR_CAVEATS = [
  'Archetypes are behavioural scoring, not identity proof.',
  'These are patterns of use, not claims about who is behind them.',
  'An archetype describes how a wallet acts, never who owns it.',
  'Behaviour is observable; ownership is not. Only the first is claimed here.',
  'Scored on what the wallets did, not on who they might be.',
  'Read these as habits, not as names.',
  'Classification here is descriptive. It confers nothing.',
  'How a wallet behaves is evidence. Who holds it is not established.'
];
const INTEL_NO_ACTION = [
  'Nothing this window demands follow-up. Keep the baseline warm.',
  'No open threads. The value of a quiet scan is the comparison it gives the next loud one.',
  'Nothing outstanding \u2014 which is itself worth recording.',
  'No leads to chase. Re-run tomorrow and watch for change against today.',
  'Clean window. The next anomaly will be measured against this.',
  'No action required. A baseline day is not a wasted one.'
];

// What the operator should actually do next, derived from what this scan found.
// Falls back to a rotating generic line ONLY when there is genuinely nothing.
function _intelActions(p) {
  const out = [];
  const recv = state.receivers || [];
  const fresh = recv.filter(r => r.fresh_account);
  const fwd   = recv.filter(r => n(r.forwarded_large_count) > 0);
  const held  = recv.filter(r => !r.fresh_account && !n(r.forwarded_large_count) && n(r.balance_xrp) >= 1e6);

  fresh.slice(0, 2).forEach(r => out.push(
    'Re-check ' + _swWho(r.address, r.label, { bare: true }) + ' \u2014 the account is ' +
    _ageText(r.age_hours) + ' and took size on day one. Whether it holds or forwards is the tell.'));
  fwd.slice(0, 2).forEach(r => out.push(
    'Follow the next hop out of ' + _swWho(r.address, r.label, { bare: true }) + '; it forwarded ' +
    n(r.forwarded_large_count) + ' large transfer' + (n(r.forwarded_large_count) === 1 ? '' : 's') +
    ' rather than holding.'));
  held.slice(0, 1).forEach(r => out.push(
    _swWho(r.address, r.label, { bare: true }) + ' is sitting on ' + fmt(n(r.balance_xrp), 0) +
    ' XRP with no forward. Watch whether that changes.'));

  (state.sigChanges || []).slice(0, 2).forEach(c => out.push(
    _swWho(c.address, (KNOWN[c.address] || {}).label, { bare: true }) + ' changed how it authorises payments (' +
    (c.from === 'single' ? 'single key' : 'quorum') + ' \u2192 ' + (c.to === 'single' ? 'single key' : 'quorum') +
    '). Confirm that was intended.'));

  try {
    (window.SW_HVT_HISTORY ? SW_HVT_HISTORY.alerts() : []).slice(0, 2).forEach(a => out.push(
      _swWho(a.address, (KNOWN[a.address] || {}).label, { bare: true }) + ' is holding ' +
      (a.ratio != null ? Math.round(a.ratio * 100) : 0) + '% of what it once held. Establish where the rest went.'));
  } catch (_) {}

  if ((state.frags || []).some(f => f.severity === 'FRAG_SUSPECT'))
    out.push('A destination tag is collecting small payments from several senders. Check whether it is an exchange deposit tag before reading anything into it.');

  const topCand = (state.discoveryInbox || []).filter(c => c && c.seen_this_scan)
    .sort((a, b) => n(b.score) - n(a.score))[0];
  if (topCand && n(topCand.score) >= 120)
    out.push('Promote or dismiss ' + _swWho(topCand.address, null, { bare: true }) +
             ' \u2014 it scored ' + n(topCand.score) + '/200 this scan and is still unreviewed.');

  if (n(p.wallets_failed) > 0)
    out.push(n(p.wallets_failed) + ' wallet' + (n(p.wallets_failed) === 1 ? '' : 's') +
             ' failed to read this pass and are excluded from every total above. Re-run before treating the flow figure as complete.');

  return out;
}

// Only state the limits that actually apply to THIS report. Listing a caveat
// about failed wallets on a scan where none failed trains the reader to skip
// the section entirely.
function _intelLimits(p, health) {
  const out = [];
  if (health && health.newsMode !== 'LEDGER_ONLY')
    out.push('Headlines are external context and prove nothing about the transfers above.');
  // v16.23: an incomplete pass outranks every other caveat — it says the report
  // stopped early, so put it first.
  try {
    const _si = scanIntegrity(p);
    if (_si.linkLost) out.unshift(_si.line);
  } catch (_) {}
  if (n(p.wallets_failed) > 0)
    out.push(n(p.wallets_failed) + ' wallet read failure' + (n(p.wallets_failed) === 1 ? '' : 's') + ' \u2014 totals are of what was reachable, not of the whole list.');
  if ((state.frags || []).length)
    out.push('Dust and destination-tag clusters are routing signals, not evidence of fragmentation or intent.');
  if ((state.clusters || []).length)
    out.push('Behavioural clusters link wallets by activity, never by ownership.');
  if ((p.large_transfers || []).length)
    out.push('Transfer classifications are heuristic. A large move is not a proven intention.');
  if (!out.length)
    out.push('Everything above is ledger-observed. Nothing here is an ownership claim.');
  return out;
}

function buildIntelBrief(p) {
  const risk = publicRiskLabel(p);
  const cluster = (state.clusters || [])[0];
  const rec = (p.receiver_followthrough || []).find(r => r.forwarded_large_count > 0);
  // v16.10: FAILED_SCAN is a scan OUTCOME, not a behaviour. Leaving it in the
  // tally produced "Dominant pattern: failed scan. Board mix: failed scan ×162"
  // — reporting the outage as the board's behaviour. Coverage belongs in the
  // coverage line; the mix describes wallets we actually read.
  const profiles = (state.walletProfiles || []).filter(x => x && x.archetype !== 'FAILED_SCAN');
  const dom = profiles.reduce((m, x) => { m[x.archetype] = (m[x.archetype] || 0) + 1; return m; }, {});
  const primary = Object.entries(dom).sort((a, b) => b[1] - a[1])[0]?.[0] || 'NO_PROFILE';
  const cov = scanCoverage(p);

  // v3.26: news context derived from shared newsMode — same authority
  // DailyReport / MorningStory use. Eliminates the old contradiction
  // where IntelBrief said "ledger-only" while DailyReport quoted headlines.
  const health = (p && p.news_health) || (typeof computeNewsHealth === 'function' ? computeNewsHealth(p) : null);
  let newsLine;
  if (!health || health.newsMode === 'LEDGER_ONLY') {
    newsLine = 'NEWS/MACRO CONTEXT — No live headlines. Ledger-only report mode.';
  } else if (health.newsMode === 'PARTIAL_CONTEXT') {
    newsLine = 'NEWS/MACRO CONTEXT — partial coverage (' + health.headline_count + ' headlines from ' + health.source_group_count + ' source group). Ledger evidence remains primary.';
  } else if (health.newsMode === 'EVIDENCE_LED_CONTEXT') {
    newsLine = 'NEWS/MACRO CONTEXT — ' + health.headline_count + ' headlines across ' + health.source_group_count + ' source group' + (health.source_group_count === 1 ? '' : 's') + ', ' + health.ledger_relevant_count + ' ledger-relevant.';
  } else {
    newsLine = 'NEWS/MACRO CONTEXT — ' + health.headline_count + ' headlines across ' + health.source_group_count + ' source group' + (health.source_group_count === 1 ? '' : 's') + '.';
  }

  const dateStr = p.date || today();
  // The brief's phrasing rotates per RUN, not per day — the verse and the prayer
  // stay daily on purpose, but XRPMan does not repeat himself inside one day.
  const runSeed = swRunSeed(p);
  const _db = deltaBaseline(p);
  const tw = getTxWindow();

  // 1 — the arithmetic, with the window it covers. A weekend sweep and an
  // overnight look identical in a bare total, so the window is stated.
  const lt = (p.large_transfers || []).length;
  const signal = [
    swVoicePick(INTEL_SIGNAL_FRAMES, 'intel-frame', runSeed),
    // v16.21: "Net inflow of 0 XRP" on a device with no stored baseline is not a
    // reading, it is the absence of one. Say which it is.
    (_db.none
      ? 'Net flow not measurable this run — no previous balances stored on this device. ' +
        n(p.wallets_checked) + ' wallets read, window ' + tw.label + '.'
      : 'Net ' + (n(p.total_balance_delta_xrp) < 0 ? 'outflow' : 'inflow') + ' of ' +
        (p.total_balance_delta_xrp > 0 ? '+' : '') + fmt(p.total_balance_delta_xrp, 0) + ' XRP across ' +
        n(p.wallets_checked) + ' watched wallets, window ' + tw.label + '.' +
        (_db.partial ? ' ' + _db.line : '')),
    lt + ' transfer' + (lt === 1 ? '' : 's') + ' above threshold. Shadow volume: ' +
      fmt(p.shadow_volume_xrp, 0) + ' XRP.',
    // Coverage sits with the arithmetic, not in a footnote. A total across 35 of
    // 197 wallets and a total across all 197 read identically otherwise.
    'Coverage: ' + cov.line + (cov.degraded ? ' ' + cov.caveat : '')
  ].join('\n');

  // 2 — the actual archetype MIX, not just the top one.
  const mix = Object.entries(dom).sort((a, b) => b[1] - a[1]).slice(0, 3)
    .map(([k, v]) => k.toLowerCase().replace(/_/g, ' ') + ' \u00d7' + v);
  const behavior = (mix.length
      ? 'Dominant pattern: ' + primary.toLowerCase().replace(/_/g, ' ') +
        (mix.length > 1 ? '. Board mix: ' + mix.join(', ') + '.' : '.') +
        (cov.degraded ? ' Profiled from ' + profiles.length + ' readable wallet' +
                        (profiles.length === 1 ? '' : 's') + ' — ' + cov.failed +
                        ' never answered and have no behaviour on record this pass.' : '')
      : (cov.degraded && cov.failed > 0
          ? 'No wallet profiles built — ' + cov.failed + ' of ' + cov.total +
            ' wallets failed to read, so there is no behaviour to describe.'
          : 'No wallet profiles built this pass.')) +
    ' ' + swVoicePick(INTEL_BEHAVIOR_CAVEATS, 'intel-caveat', runSeed);

  // 6 / 7 — only what applies, and what to actually do about it.
  const limits = _intelLimits(p, health).map(x => '\u2022 ' + x).join('\n');
  const acts = _intelActions(p);
  const actions = acts.length
    ? acts.map(x => '\u2022 ' + x).join('\n')
    : '\u2022 ' + swVoicePick(INTEL_NO_ACTION, 'intel-noaction', runSeed);

  const brief = `FORENSIC INTELLIGENCE BRIEF — ${dateStr}

1. LEDGER SIGNAL
${signal}

2. WALLET BEHAVIOR
${behavior}

3. CLUSTER READ
${cluster ? cluster.type + ' detected. ' + String(cluster.reason || '').replace(/\s*\.?\s*$/, '.') : 'No behavioural cluster crossed the threshold this window.'}${rec ? ' Receiver follow-through suggests routing rather than long-term holding.' : ''}

4. NEWS / MACRO CONTEXT
${newsLine}

5. RISK SCORE
${risk}.

6. EVIDENCE LIMITS
${limits}

7. ACTIONABLE WATCHLIST
${actions}`;
  state.intelBrief = brief;
  if ($('intelBriefBox')) $('intelBriefBox').textContent = brief;
  return brief;
}

// ── EVIDENCE SEAL (SHA-256) ───────────────────────────────────
async function sha256(text) {
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
}
async function buildEvidenceSeal(p, report, bundle) {
  const reportId = 'SW-' + today().replace(/-/g, '') + '-' + Math.random().toString(36).slice(2, 7).toUpperCase();
  const scanId = 'SC-' + Date.now().toString(36).toUpperCase();
  const [pubHash, fullHash] = await Promise.all([sha256(report), sha256(bundle)]);
  const master = await sha256(pubHash + fullHash + reportId);
  const seal = { report_id: reportId, scan_id: scanId, version: APP_VERSION, date: today(),
    public_hash: pubHash.slice(0, 32), full_hash: fullHash.slice(0, 32), master_hash: master.slice(0, 32),
    chars_4k: report.length, generated_at: new Date().toISOString() };
  setText('sealReportId', seal.report_id);
  setText('sealScanId', seal.scan_id);
  setText('sealCharCount', seal.chars_4k + ' / 4000');
  setText('sealPublicHash', seal.public_hash);
  setText('sealFullHash', seal.full_hash);
  setText('sealMasterHash', seal.master_hash);
  if ($('sealJson')) $('sealJson').textContent = JSON.stringify(seal, null, 2);
  setText('hudSealMini', 'SEALED');
  state.seal = seal;   // v3.15: stash for SHADOW_EXPORTS / shadowFileBase
  return seal;
}

