// ─── MODULE 1 — PATTERN MEMORY ────────────────────────────────────────

const PATTERN_MEMORY_KEY      = 'SHADOW_WATCH_PATTERN_MEMORY_V1';
const PATTERN_MEMORY_CAP      = 100;
const NEWS_DOCTOR_HISTORY_KEY = 'SHADOW_WATCH_NEWS_DOCTOR_HISTORY_V1';

// Shape of an empty pattern memory object
function _emptyPatternMemory() {
  return { version: 'v1', snapshots: [], wallets: {}, patterns: {}, updated_at: '' };
}

// Load from localStorage (or create fresh)
function getPatternMemory() {
  try {
    const raw = localStorage.getItem(PATTERN_MEMORY_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && parsed.version === 'v1') return parsed;
    }
  } catch (_) {}
  return _emptyPatternMemory();
}

// Write to localStorage
function savePatternMemory(memory) {
  if (!memory) return;
  memory.updated_at = new Date().toISOString();
  try { localStorage.setItem(PATTERN_MEMORY_KEY, JSON.stringify(memory)); } catch (_) {}
}

// Wipe
function clearPatternMemory() {
  try { localStorage.removeItem(PATTERN_MEMORY_KEY); } catch (_) {}
  log('Pattern memory cleared.');
}

// Download as JSON file
function exportPatternMemory() {
  const mem = getPatternMemory();
  const base = shadowFileBase ? shadowFileBase('PatternMemory') : 'ShadowWatch_PatternMemory';
  if (typeof downloadJsonFile === 'function') {
    downloadJsonFile(base + '.json', mem);
  } else {
    const a = document.createElement('a');
    a.href = 'data:application/json,' + encodeURIComponent(JSON.stringify(mem, null, 2));
    a.download = base + '.json';
    a.click();
  }
}

// Build a compact snapshot object from the current pack
function savePatternSnapshot(pack) {
  if (!pack) return;
  const mem = getPatternMemory();

  // Compact snapshot — only what pattern detection needs later
  const snap = {
    scan_id:                 pack.scan_id || state.scanId || '',
    report_id:               pack.report_id || state.reportId || '',
    generated_at:            new Date().toISOString(),
    version:                 APP_VERSION || 'v3.32a-helper-runtime-proof-lock',
    xrp_price:               n(pack.xrp_price),
    xrp_delta_24h_pct:       pack.xrp_delta_24h_pct != null ? pack.xrp_delta_24h_pct : null,
    xrp_volume_24h:          n(pack.xrp_volume_24h),
    shadow_volume_xrp:       n(pack.shadow_volume_xrp),
    total_balance_delta_xrp: n(pack.total_balance_delta_xrp),
    tx_24h_count:            n(pack.tx_24h_count),
    large_transfer_count:    (pack.large_transfers || []).length,
    risk_score:              pack.risk_score ? { score: n(pack.risk_score.score), label: pack.risk_score.label } : null,
    source_health_summary:   (() => {
      try {
        const h = getSourceHealth(pack);
        return { degraded: h.degraded, partial: h.partial_coverage,
                 failed_count: (h.failed || []).length, group_count: n(h.source_group_count) };
      } catch (_) { return null; }
    })(),
    // Only store minimal transfer info for pattern detection (no full tx data)
    top_large_transfers: (pack.large_transfers || []).slice(0, 5).map(t => ({
      from: t.from, to: t.to,
      sender_label: t.sender_label || '', receiver_label: t.receiver_label || '',
      amount_xrp: n(t.amount),
      classification: t.classification || ''
    })),
    receiver_followthrough: (pack.receiver_followthrough || []).slice(0, 5).map(r => ({
      address: r.address,
      forwarded: n(r.forwarded_large_count) > 0,
      classification: r.classification || ''
    })),
    behavioral_cluster_top: (() => {
      const bc = state.behavioralClusters;
      const top = bc && bc.clusters && bc.clusters[0];
      if (!top) return null;
      return { type: top.cluster_type || top.type || 'UNKNOWN',
               confidence: top.confidence || '',
               wallets: (top.wallets_label || []).slice(0, 3) };
    })(),
    discovery_summary: (() => {
      const inbox = state.discoveryInbox || [];
      return { count: inbox.length,
               recommended: inbox.filter(r =>
                 r.recommended_action === 'RECOMMEND_FOR_WATCH' ||
                 r.review_status === 'RECOMMENDED' || r.review_status === 'APPROVED').length,
               top_address: inbox.length ? inbox[0].address.slice(0, 10) + '…' : null };
    })()
  };

  mem.snapshots.push(snap);
  // Cap at 100 most recent
  if (mem.snapshots.length > PATTERN_MEMORY_CAP) {
    mem.snapshots = mem.snapshots.slice(-PATTERN_MEMORY_CAP);
  }
  savePatternMemory(mem);
}

// Update per-wallet memory from the current pack's wallet_results + large_transfers
function updateWalletMemory(pack) {
  if (!pack) return;
  const mem = getPatternMemory();
  const now = new Date().toISOString();

  // Wallet results (balance, delta)
  (pack.wallet_results || pack.wallets || []).forEach(w => {
    if (!w.address) return;
    let rec = mem.wallets[w.address];
    if (!rec) {
      rec = {
        address: w.address,
        label: w.label || '',
        first_seen: now,
        last_seen: now,
        times_seen: 0,
        total_in_xrp: 0,
        total_out_xrp: 0,
        largest_transfer_xrp: 0,
        common_counterparties: {},
        destination_tags: {},
        archetype_history: [],
        source_types: [],
        last_classification: null
      };
      mem.wallets[w.address] = rec;
    }
    rec.last_seen = now;
    rec.times_seen++;
    const delta = n(w.delta_xrp);
    if (delta > 0) rec.total_in_xrp += delta;
    if (delta < 0) rec.total_out_xrp += Math.abs(delta);
    if (w.archetype && !rec.archetype_history.includes(w.archetype)) {
      rec.archetype_history.push(w.archetype);
    }
  });

  // Large transfers — update sender/receiver wallet memory
  (pack.large_transfers || []).forEach(t => {
    const amt = n(t.amount);
    // Sender
    if (t.from && mem.wallets[t.from]) {
      const s = mem.wallets[t.from];
      s.total_out_xrp += amt;
      if (amt > s.largest_transfer_xrp) s.largest_transfer_xrp = amt;
      if (t.to) {
        s.common_counterparties[t.to] = (s.common_counterparties[t.to] || 0) + 1;
      }
    }
    // Receiver wallet memory (may be unknown/untracked)
    if (t.to) {
      if (!mem.wallets[t.to]) {
        mem.wallets[t.to] = {
          address: t.to, label: t.receiver_label || '',
          first_seen: now, last_seen: now, times_seen: 1,
          total_in_xrp: amt, total_out_xrp: 0,
          largest_transfer_xrp: amt,
          common_counterparties: {}, destination_tags: {},
          archetype_history: [], source_types: ['large_transfer_dest'],
          last_classification: t.classification || null
        };
      } else {
        const r = mem.wallets[t.to];
        r.last_seen = now; r.times_seen++;
        r.total_in_xrp += amt;
        if (amt > r.largest_transfer_xrp) r.largest_transfer_xrp = amt;
        if (!r.source_types.includes('large_transfer_dest'))
          r.source_types.push('large_transfer_dest');
      }
      if (t.destination_tag != null) {
        const w = mem.wallets[t.to];
        const tag = String(t.destination_tag);
        w.destination_tags[tag] = (w.destination_tags[tag] || 0) + 1;
      }
    }
  });

  savePatternMemory(mem);
}

// Detect repeated patterns from all snapshots and update mem.patterns
function updatePatternMemory(pack) {
  if (!pack) return;
  const mem = getPatternMemory();
  const now = new Date().toISOString();
  const snaps = mem.snapshots;

  function upsertPattern(key, type, publicSummary, evidenceRef) {
    if (!mem.patterns[key]) {
      mem.patterns[key] = {
        key, type,
        first_seen: now, last_seen: now,
        times_seen: 1,
        confidence: 'LOW',
        public_summary: publicSummary,
        evidence_refs: evidenceRef ? [evidenceRef] : []
      };
    } else {
      const p = mem.patterns[key];
      p.last_seen = now;
      p.times_seen++;
      p.public_summary = publicSummary; // update to freshest wording
      if (evidenceRef && !p.evidence_refs.includes(evidenceRef)) {
        p.evidence_refs = p.evidence_refs.slice(-19).concat(evidenceRef);
      }
      // Confidence tiers
      if (p.times_seen >= 4)      p.confidence = 'HIGH';
      else if (p.times_seen >= 2) p.confidence = 'MEDIUM';
      else                         p.confidence = 'LOW';
    }
  }

  // 1. Repeated sender → receiver large transfers
  (pack.large_transfers || []).forEach(t => {
    if (t.from && t.to) {
      const key = 'sender_receiver:' + t.from + ':' + t.to;
      const sLabel = _swWho(t.from, t.sender_label);
      const rLabel = _swWho(t.to, t.receiver_label);
      upsertPattern(key, 'REPEATED_SENDER_RECEIVER',
        'Repeated large transfer: ' + sLabel + ' → ' + rLabel + ' (' + fmt(n(t.amount), 0) + ' XRP flags).',
        pack.report_id || pack.scan_id || '');
    }
  });

  // 2. Same receiver from multiple watched wallets (multi-watched receiver)
  const receiverWatched = {};
  (pack.large_transfers || []).forEach(t => {
    // Keyed on the sender's ADDRESS, not its handle: the address is what the
    // registry can resolve to a name, and two handles can be one entity.
    if (t.to && t.from && t.sender_label && !KNOWN[t.to]) {
      if (!receiverWatched[t.to]) receiverWatched[t.to] = new Set();
      receiverWatched[t.to].add(t.from);
    }
  });
  Object.keys(receiverWatched).forEach(recv => {
    if (receiverWatched[recv].size >= 2) {
      const key = 'multi_watched_receiver:' + recv;
      const senders = _swWhoList(Array.from(receiverWatched[recv]), { max: 3 }).join(' + ');
      upsertPattern(key, 'MULTI_WATCHED_RECEIVER',
        _swWho(recv, null, { bare: true }) + ' received from ' + receiverWatched[recv].size +
        ' watched wallets (' + senders + '). Suggests routing or aggregation.',
        pack.report_id || '');
    }
  });

  // 3. Repeated destination-tag clusters
  (state.frags || []).forEach(f => {
    if (f.to && f.unique_from >= 3) {
      const key = 'dest_tag:' + f.to + ':' + (f.tag || 'none');
      upsertPattern(key, 'REPEATED_DEST_TAG',
        'Destination tag cluster: ' + (f.unique_from) + ' unique senders to ' +
        _swWho(f.to, null, { bare: true }) + ', tag=' + (f.tag || 'none') + '. Repeated routing signal.',
        pack.report_id || '');
    }
  });

  // 4. Repeated behavioral cluster counterparties
  const bc = state.behavioralClusters;
  if (bc && Array.isArray(bc.clusters)) {
    bc.clusters.forEach(cluster => {
      (cluster.shared_counterparties || []).forEach(addr => {
        const key = 'cluster_counterparty:' + addr;
        upsertPattern(key, 'CLUSTER_COUNTERPARTY_REPEAT',
          _swWho(addr, null, { bare: true }) + ' appears as shared counterparty in behavioral cluster.',
          pack.report_id || '');
      });
    });
  }

  // 5. Repeated discovery candidates (from discovery history, not just inbox)
  (state.discoveryHistory || []).forEach(h => {
    if (h.top_address) {
      const key = 'discovery_candidate:' + h.top_address;
      upsertPattern(key, 'REPEATED_DISCOVERY_CANDIDATE',
        _swWho(h.top_address, null, { bare: true }) + ' appeared in multiple discovery scans. Repeat behavioral signal.',
        h.generated_at || '');
    }
  });

  // 6. Receiver followthrough — split vs hold patterns
  (pack.receiver_followthrough || []).forEach(r => {
    if (!r.address) return;
    if (n(r.forwarded_large_count) > 0) {
      const key = 'receiver_split:' + r.address;
      upsertPattern(key, 'REPEATED_RECEIVER_SPLIT',
        'Receiver ' + _swWho(r.address, r.label, { bare: true }) + ' repeatedly forwards large amounts. Suggests routing.',
        pack.report_id || '');
    } else {
      const key = 'receiver_hold:' + r.address;
      upsertPattern(key, 'REPEATED_RECEIVER_HOLD',
        'Receiver ' + _swWho(r.address, r.label, { bare: true }) + ' repeatedly holds after large inflow. Suggests accumulation.',
        pack.report_id || '');
    }
  });

  // 7. Repeated news provider failures (from current source health)
  try {
    const health = getSourceHealth(pack);
    (health.failed || []).forEach(provName => {
      const key = 'news_failure:' + provName;
      upsertPattern(key, 'REPEATED_NEWS_FAILURE',
        'News provider ' + provName + ' has failed on multiple scans. Coverage degraded.',
        pack.report_id || '');
    });
  } catch (_) {}

  // Suppress dust-only patterns — require 5+ occurrences or large value
  Object.keys(mem.patterns).forEach(key => {
    const p = mem.patterns[key];
    if (p.type === 'REPEATED_DEST_TAG' && p.times_seen < 5) {
      // Check whether associated wallet has meaningful value
      const addr = key.split(':')[1];
      const wm = mem.wallets[addr];
      if (!wm || wm.total_in_xrp < 1000) {
        // Suppress — not ready for public display
        p._suppressed = true;
      } else {
        p._suppressed = false;
      }
    }
  });

  savePatternMemory(mem);
}

// Get patterns that have repeated (times_seen >= 2) and are not suppressed
function getRepeatedPatterns() {
  const mem = getPatternMemory();
  return Object.values(mem.patterns)
    .filter(p => p.times_seen >= 2 && !p._suppressed)
    .sort((a, b) => b.times_seen - a.times_seen);
}

// Generate report-ready text for the PATTERN MEMORY section
function summarizePatternMemory(pack) {
  const mem = getPatternMemory();
  const snapCount = mem.snapshots.length;
  if (snapCount < 5) {
    return {
      lines: ['• Pattern memory warming up. Need 5+ scans; current: ' + snapCount + '.'],
      snapCount
    };
  }
  const repeated = getRepeatedPatterns();
  if (!repeated.length) {
    return {
      lines: ['• Enough snapshots exist (' + snapCount + '), but no repeat pattern cleared public threshold.'],
      snapCount
    };
  }
  const top3 = repeated.slice(0, 3);
  const lines = top3.map(p =>
    '• [' + p.confidence + '] ' + p.public_summary + ' (flagged ' + p.times_seen + 'x)'
  );
  lines.push('• Pattern = behavioral repetition. Not ownership proof.');
  return { lines, snapCount };
}

// Expose Module 1 helpers
if (typeof window !== 'undefined') {
  window.getPatternMemory     = getPatternMemory;
  window.savePatternMemory    = savePatternMemory;
  window.clearPatternMemory   = clearPatternMemory;
  window.exportPatternMemory  = exportPatternMemory;
  window.savePatternSnapshot  = savePatternSnapshot;
  window.updateWalletMemory   = updateWalletMemory;
  window.updatePatternMemory  = updatePatternMemory;
  window.getRepeatedPatterns  = getRepeatedPatterns;
  window.summarizePatternMemory = summarizePatternMemory;
  window.PATTERN_MEMORY_KEY   = PATTERN_MEMORY_KEY;
}

// ─── MODULE 5 — NEWS DOCTOR HISTORY ───────────────────────────────────

// Load or init the news doctor history map
function getNewsDoctorHistory() {
  try {
    const raw = localStorage.getItem(NEWS_DOCTOR_HISTORY_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && typeof parsed === 'object') return parsed;
    }
  } catch (_) {}
  return {};
}

// ── AUTOMATIC SOURCE SUPPRESSION, WITH A REDUNDANCY GUARD ──────
// A provider that has failed on every run for a week is not a flaky source, it
// is a dead one, and re-attempting it every scan costs a request, a timeout and
// a line in the error log that never changes.
//
// The guard is the important half: a source is NEVER suppressed if doing so
// would leave too few working ones behind. A noisy log is a nuisance; a report
// that quietly lost its news coverage because the app tidied itself into a
// corner is a failure. So suppression requires redundancy to still exist after
// it — and if the healthy count later drops, a suppressed source is
// automatically brought back into rotation rather than staying off.
//
// Suppression is also never permanent. Every SUPPRESS_RETRY_HOURS one probe is
// allowed through, because a source that is off can never be observed to have
// recovered, and a rule with no way back is a rule that eventually lies.
const SUPPRESS_AFTER_FAILS   = 10;   // consecutive failures before it qualifies
const MIN_HEALTHY_TO_SUPPRESS = 2;   // working sources that must remain afterwards
const SUPPRESS_RETRY_HOURS   = 12;   // probation probe interval

function _newsHealthyCount(hist) {
  hist = hist || getNewsDoctorHistory();
  let ok = 0;
  Object.keys(hist).forEach(k => {
    const h = hist[k] || {};
    if (n(h.consecutive_failures) === 0 && n(h.success_count) > 0) ok++;
  });
  return ok;
}

// Should this provider be skipped on this run? Returns the reasoning too, so the
// report can explain itself rather than silently dropping a source.
function newsSuppression(provName) {
  const hist = getNewsDoctorHistory();
  const rec  = hist[provName];
  if (!rec) return { suppressed: false, reason: 'no history' };
  const fails = n(rec.consecutive_failures);
  if (fails < SUPPRESS_AFTER_FAILS)
    return { suppressed: false, fails: fails, reason: 'below the ' + SUPPRESS_AFTER_FAILS + '-failure threshold' };

  // The redundancy guard. Count the healthy sources EXCLUDING this one.
  const healthy = _newsHealthyCount(hist);
  if (healthy < MIN_HEALTHY_TO_SUPPRESS) {
    return { suppressed: false, fails: fails, healthy: healthy,
             reason: 'kept in rotation — only ' + healthy + ' healthy source' +
                     (healthy === 1 ? ' remains' : 's remain') +
                     ', and a failing source still beats no source' };
  }

  // Probation: let one probe through every SUPPRESS_RETRY_HOURS.
  const last = rec.last_probe ? Date.parse(rec.last_probe) : 0;
  const dueMs = (isFinite(last) ? last : 0) + SUPPRESS_RETRY_HOURS * 3600000;
  if (Date.now() >= dueMs) {
    rec.last_probe = new Date().toISOString();
    saveNewsDoctorHistory(hist);
    return { suppressed: false, fails: fails, healthy: healthy, probe: true,
             reason: 'suppressed, but a ' + SUPPRESS_RETRY_HOURS + '-hourly probe is due — checking whether it recovered' };
  }
  return { suppressed: true, fails: fails, healthy: healthy,
           nextRetryMin: Math.max(1, Math.round((dueMs - Date.now()) / 60000)),
           reason: fails + ' consecutive failures with ' + healthy + ' healthy sources still up' };
}

// Save news doctor history
function saveNewsDoctorHistory(hist) {
  try { localStorage.setItem(NEWS_DOCTOR_HISTORY_KEY, JSON.stringify(hist)); } catch (_) {}
}

// Update provider history from the current news diagnostics / source health
function updateNewsDoctorHistory() {
  const hist = getNewsDoctorHistory();
  const now = new Date().toISOString();

  // Pull diagnostics from state (set by v3.20 engine hook)
  const diag = state.newsDiagnostics || null;
  if (!diag || !diag.providers) return;

  Object.keys(diag.providers).forEach(provName => {
    const prov = diag.providers[provName];
    if (!hist[provName]) {
      hist[provName] = {
        provider: provName,
        first_seen: now, last_seen: now,
        last_success: null, last_failure: null,
        success_count: 0, failure_count: 0,
        consecutive_failures: 0,
        last_failure_class: null,
        last_error_excerpt: '',
        reliability_score: 100
      };
    }
    const rec = hist[provName];
    rec.last_seen = now;
    // v3.26-hotfix1: deterministic labels (legacy OK/OK_UNVERIFIED still mapped)
    const isContentOk = (prov.overall_status === 'CONTENT_OK' || prov.overall_status === 'OK');
    const isTransportFail = (prov.overall_status === 'TRANSPORT_FAILED' || prov.overall_status === 'FAILED');
    if (isContentOk) {
      rec.success_count++;
      rec.consecutive_failures = 0;
      rec.last_success = now;
    } else if (isTransportFail) {
      rec.failure_count++;
      rec.consecutive_failures++;
      rec.last_failure = now;
      rec.last_failure_class = prov.failure_class || null;
      rec.last_error_excerpt = prov.last_error_excerpt || '';
    }
    // TRANSPORT_OK_EMPTY / DISABLED_SESSION / NOT_ATTEMPTED don't affect counts
    const total = rec.success_count + rec.failure_count;
    rec.reliability_score = total > 0
      ? Math.round((rec.success_count / total) * 100)
      : 100;
  });

  saveNewsDoctorHistory(hist);
}

// Export news doctor history as JSON
function exportNewsDoctorHistoryJson() {
  const hist = getNewsDoctorHistory();
  const base = shadowFileBase ? shadowFileBase('NewsDoctorHistory') : 'ShadowWatch_NewsDoctorHistory';
  if (typeof downloadJsonFile === 'function') {
    downloadJsonFile(base + '.json', hist);
  } else {
    const a = document.createElement('a');
    a.href = 'data:application/json,' + encodeURIComponent(JSON.stringify(hist, null, 2));
    a.download = base + '.json';
    a.click();
  }
}

// Expose Module 5 helpers
if (typeof window !== 'undefined') {
  window.getNewsDoctorHistory     = getNewsDoctorHistory;
  window.saveNewsDoctorHistory    = saveNewsDoctorHistory;
  window.updateNewsDoctorHistory  = updateNewsDoctorHistory;
  window.exportNewsDoctorHistoryJson = exportNewsDoctorHistoryJson;
  window.NEWS_DOCTOR_HISTORY_KEY  = NEWS_DOCTOR_HISTORY_KEY;
}

// ─── MODULE 2 — PATTERN MEMORY UI ─────────────────────────────────────

// Render the Pattern Memory panel on the PATTERN MEMORY screen.
// Creates or replaces #patternMemoryPanel — idempotent.
function renderPatternMemoryUI() {
  const screen = document.getElementById('screen-pattern');
  if (!screen) return;

  let panel = document.getElementById('patternMemoryPanel');
  if (!panel) {
    panel = document.createElement('div');
    panel.id = 'patternMemoryPanel';
    panel.className = 'panel';
    panel.style.cssText = 'margin-bottom:14px;';
    // Insert at the top of the PATTERN MEMORY screen, after screen-title
    const titleEl = screen.querySelector('.screen-title');
    if (titleEl) titleEl.after(panel);
    else screen.insertBefore(panel, screen.firstChild);
  }

  const mem   = getPatternMemory();
  const hist  = getNewsDoctorHistory();
  const snaps = mem.snapshots;
  const repeated = getRepeatedPatterns();

  // Wallet memory stats
  const walletKeys = Object.keys(mem.wallets);
  const topReceiver = walletKeys
    .map(k => mem.wallets[k])
    .filter(w => w.total_in_xrp > 0)
    .sort((a, b) => b.total_in_xrp - a.total_in_xrp)[0];

  // News provider reliability
  const histEntries = Object.values(hist).sort((a, b) => a.reliability_score - b.reliability_score);
  const worstProvider = histEntries.find(p => p.failure_count > 0);

  // Source failure patterns
  const failurePatterns = Object.values(mem.patterns)
    .filter(p => p.type === 'REPEATED_NEWS_FAILURE' && !p._suppressed)
    .sort((a, b) => b.times_seen - a.times_seen);

  let html = '<div class="panel-title" style="display:flex;justify-content:space-between;align-items:center">' +
    '<span>🧠 PATTERN MEMORY</span>' +
    '<span style="font-size:10px;color:var(--muted);letter-spacing:0.8px">' +
      snaps.length + ' snapshots · ' + walletKeys.length + ' wallet records</span>' +
  '</div>';

  // Last scan saved
  if (snaps.length) {
    const last = snaps[snaps.length - 1];
    html += '<div style="font-size:11px;color:var(--muted);margin-bottom:10px">Last saved: ' +
      (last.generated_at ? last.generated_at.slice(0, 16).replace('T', ' ') + ' UTC' : '—') + '</div>';
  }

  // Snapshot count warning
  if (snaps.length < 5) {
    html += '<div style="color:#ffd76a;font-size:11px;margin-bottom:10px;padding:6px 10px;border:1px solid rgba(255,191,64,0.3);border-radius:6px">' +
      '⚠ Pattern memory warming up. Need 5+ scans; current: ' + snaps.length + '.' +
    '</div>';
  }

  // Top repeated patterns
  if (repeated.length) {
    html += '<div style="font-size:10px;color:var(--lime);letter-spacing:1.2px;margin-bottom:6px">TOP REPEATED PATTERNS</div>';
    html += '<div style="display:flex;flex-direction:column;gap:6px;margin-bottom:12px">';
    repeated.slice(0, 5).forEach(p => {
      const confColor = p.confidence === 'HIGH' ? '#ff6a6a'
                      : p.confidence === 'MEDIUM' ? '#ffd76a' : 'var(--muted)';
      html += '<div style="font-size:11px;line-height:1.4;padding:6px 10px;border-left:2px solid ' + confColor + ';background:rgba(0,0,0,0.3)">' +
        '<span style="color:' + confColor + ';font-weight:700;font-size:10px">[' + escapeHTML(p.confidence) + ']</span> ' +
        escapeHTML(p.public_summary) +
        ' <span style="color:var(--muted);font-size:10px">×' + p.times_seen + '</span>' +
      '</div>';
    });
    html += '</div>';
  } else if (snaps.length >= 5) {
    html += '<div style="font-size:11px;color:var(--muted);margin-bottom:10px">Enough snapshots exist, but no repeat pattern cleared public threshold.</div>';
  }

  // Top receiver by value
  if (topReceiver) {
    html += '<div style="font-size:10px;color:var(--lime);letter-spacing:1.2px;margin-bottom:6px">TOP TRACKED RECEIVER</div>';
    html += '<div style="font-size:11px;color:#cce8cc;margin-bottom:12px">' +
      escapeHTML(topReceiver.label || topReceiver.address.slice(0, 14) + '…') +
      ' · ' + fmt(topReceiver.total_in_xrp, 0) + ' XRP in · seen ' + topReceiver.times_seen + 'x' +
    '</div>';
  }

  // News doctor history — worst provider
  if (histEntries.length) {
    html += '<div style="font-size:10px;color:var(--lime);letter-spacing:1.2px;margin-bottom:6px">NEWS PROVIDER RELIABILITY</div>';
    html += '<div style="display:flex;flex-direction:column;gap:5px;margin-bottom:12px">';
    histEntries.slice(0, 6).forEach(p => {
      const rel = p.reliability_score;
      const relColor = rel >= 80 ? '#aaffaa' : rel >= 50 ? '#ffd76a' : '#ff6a6a';
      const consec = p.consecutive_failures > 0
        ? ' · ' + p.consecutive_failures + ' consecutive fail' + (p.consecutive_failures > 1 ? 's' : '')
        : '';
      html += '<div style="font-size:11px;display:flex;justify-content:space-between;align-items:center">' +
        '<span style="color:#cce8cc">' + escapeHTML(p.provider) + consec + '</span>' +
        '<span style="color:' + relColor + ';font-weight:700">' + rel + '% reliable</span>' +
      '</div>';
      if (p.last_failure_class) {
        html += '<div style="font-size:10px;color:var(--muted);padding-left:8px">' +
          'Last failure: ' + escapeHTML(p.last_failure_class) + '</div>';
      }
    });
    html += '</div>';
  }

  // Action buttons
  html += '<div style="display:flex;flex-wrap:wrap;gap:8px">' +
    '<button id="btnExportPatternMemory" class="secondary" style="font-size:10px">⬇ Export Pattern Memory JSON</button>' +
    '<button id="btnExportNewsDoctorHistory" class="secondary" style="font-size:10px">⬇ News Doctor History JSON</button>' +
    '<button id="btnCopyMemorySummary" class="secondary" style="font-size:10px">📋 Copy Memory Summary</button>' +
    '<button id="btnClearPatternMemory" class="secondary" style="font-size:10px;color:#ff6a6a">🗑 Clear Pattern Memory</button>' +
  '</div>';

  panel.innerHTML = html;

  // Wire buttons
  const btnExp = document.getElementById('btnExportPatternMemory');
  if (btnExp) btnExp.addEventListener('click', () => { try { exportPatternMemory(); } catch(e) { elog('exportPatternMemory', e); } });
  const btnNdh = document.getElementById('btnExportNewsDoctorHistory');
  if (btnNdh) btnNdh.addEventListener('click', () => { try { exportNewsDoctorHistoryJson(); } catch(e) { elog('exportNewsDoctorHistoryJson', e); } });
  const btnCopy = document.getElementById('btnCopyMemorySummary');
  if (btnCopy) btnCopy.addEventListener('click', () => {
    try {
      const sum = summarizePatternMemory(state.pack || {});
      const txt = ['SHADOW WATCH PATTERN MEMORY SUMMARY',
                   snaps.length + ' snapshots · ' + walletKeys.length + ' wallet records',
                   '', ...sum.lines].join('\n');
      if (typeof copySafe === 'function') copySafe(txt, 'Memory Summary');
      else navigator.clipboard?.writeText(txt);
    } catch(e) { elog('copyMemorySummary', e); }
  });
  const btnClr = document.getElementById('btnClearPatternMemory');
  if (btnClr) btnClr.addEventListener('click', () => {
    if (confirm('Clear all pattern memory? This cannot be undone.')) {
      clearPatternMemory();
      renderPatternMemoryUI();
    }
  });
}

if (typeof window !== 'undefined') {
  window.renderPatternMemoryUI = renderPatternMemoryUI;
}

// ─── MODULE 4 — DISCOVERY REVIEW HARDENING ────────────────────────────

// Extend review statuses with v3.21 additions. The existing v3.20 constant
// is replaced here — smoke test updated to expect 8 (was 6).
const DISCOVERY_REVIEW_STATUSES_V321 = [
  'NEW', 'REVIEW', 'RECOMMENDED', 'APPROVED',
  'REJECTED', 'SUPPRESSED', 'WATCH_ONLY', 'WATCHED_ALREADY', 'EXPORTED_FOR_BUILDER'
];

// Poison protection: should this candidate be blocked from auto-RECOMMENDED?
// Dust-only + low value → only ok if repeated across scans or paired with
// large-flow evidence.
function _isPoisonCandidate(c) {
  if (!c) return false;
  const isDustOrTiny = c._is_dust_only || (n(c.total_value_xrp) < 10 && n(c.tx_count) <= 2);
  if (!isDustOrTiny) return false;
  // Allow if repeated (seen 2+ scans)
  if (n(c.seen_count) >= 2) return false;
  // Allow if paired with large-flow evidence
  if (n(c.total_value_xrp) >= 1000) return false;
  return true; // pure dust, first appearance, no large flow — suppress
}

// Build an evidence summary string for a candidate (displayed in inbox rows)
function buildCandidateEvidenceSummary(c) {
  if (!c) return '';
  const parts = [];
  parts.push('Score: ' + n(c.score) + '/150');
  parts.push('Class: ' + (c.classification || '—'));
  if (c.sources && c.sources.length) {
    parts.push('Sources: ' + (Array.isArray(c.sources) ? c.sources : []).slice(0, 3).join(', '));
  }
  if (c.total_value_xrp > 0) parts.push('Total value: ' + fmt(n(c.total_value_xrp), 0) + ' XRP');
  if (c.seen_count > 1) parts.push('Seen ' + c.seen_count + 'x across scans');
  if (c._shared_counterparty_count >= 3) parts.push('Shared by ' + c._shared_counterparty_count + ' watched wallets');
  if (c._forwarded_large_count > 0) parts.push('Forwarded ' + c._forwarded_large_count + ' large tx');
  if (c._is_dust_only) parts.push('⚠ DUST-ONLY');
  // Reasons (top 2)
  if (c.reasons && c.reasons.length) {
    parts.push('Reason: ' + c.reasons.slice(0, 2).join(' · '));
  }
  return parts.join(' | ');
}

// Updated buildWalletAddBuilderPrompt — includes APPROVED, excludes REJECTED/SUPPRESSED
function buildWalletAddBuilderPrompt_v321(selectedCandidates) {
  if (!Array.isArray(selectedCandidates) || !selectedCandidates.length) return '';
  const eligible = selectedCandidates.filter(c =>
    c.review_status !== 'REJECTED' && c.review_status !== 'SUPPRESSED'
  );
  if (!eligible.length) return '';
  const sorted = [...eligible].sort((a, b) => n(b.score) - n(a.score));
  const entries = sorted.map((c, i) => {
    const label = 'DISC_' + String(i + 1).padStart(3, '0');
    const reason = (c.reasons && c.reasons[0]
      ? c.reasons[0].replace(/"/g, '\\"').slice(0, 120)
      : c.classification || 'Auto Wallet Discovery');
    return '  {label:"' + label + '", address:"' + c.address + '", cat:"discovered", ' +
           'classification:"' + (c.classification || '') + '", confidence:"' + (c.confidence || 'LOW') + '", ' +
           'source:"Auto Wallet Discovery v3.21", score:' + n(c.score) + ', reason:"' + reason + '"}';
  });
  return (
    '// v3.21 Auto Wallet Discovery — behavioral evidence only, not ownership proof.\n' +
    '// REJECTED and SUPPRESSED candidates excluded.\n' +
    '// Review before adding to permanent watchlist.\n' +
    'const NEW_WATCH_ENTRIES_V321 = [\n' + entries.join(',\n') + '\n];'
  );
}

if (typeof window !== 'undefined') {
  window.DISCOVERY_REVIEW_STATUSES_V321 = DISCOVERY_REVIEW_STATUSES_V321;
  window._isPoisonCandidate = _isPoisonCandidate;
  window.buildCandidateEvidenceSummary = buildCandidateEvidenceSummary;
  window.buildWalletAddBuilderPrompt_v321 = buildWalletAddBuilderPrompt_v321;
}

// ── v3.21: MODULE 1+4 integration — update buildBundle to include pattern memory ──
// This patches buildBundle at runtime. Called from DOMContentLoaded after all
// v3.21 helpers are defined.
function _patchBuildBundleForV321() {
  const _origBuildBundle = window.buildBundle || (typeof buildBundle !== 'undefined' ? buildBundle : null);
  if (!_origBuildBundle) return;
  // We can't patch `buildBundle` directly (function declaration), so we store the
  // pattern memory in state and add it to the exports mapping below in buildBundle override.
  // Actually — simplest approach: extend state so buildBundle picks it up.
  // The override is done by patching the function on window.
  window.buildBundle_v321 = function(p, seal) {
    const base = JSON.parse(_origBuildBundle(p, seal));
    base.pattern_memory_summary = (() => {
      try { return summarizePatternMemory(p); } catch (_) { return null; }
    })();
    base.pattern_memory_snapshot_count = (() => {
      try { return getPatternMemory().snapshots.length; } catch (_) { return 0; }
    })();
    return JSON.stringify(base, null, 2);
  };
}


// ══════════════════════════════════════════════════════════════════════
//  v3.32a-helper-runtime-proof-lock
//
//  MODULE A — Morning Story Report Engine
//  MODULE B — Evidence-led News Router
//  MODULE C — News Source Strategy (extends News Doctor)
//  MODULE D — Google News targeted query helper
//
//  Safety rules (enforced in all builders):
//    - Ledger facts are evidence. Patterns are analysis. Motives are thesis.
//    - Never: "Ripple did X because…", "proves", "confirms causation"
//    - Always: "ledger evidence shows", "pattern suggests", "route repeated"
//    - Never auto-add discovered wallets to WATCHLIST.
//    - Risk label BLACK / EXTREME is never silently downgraded.
// ══════════════════════════════════════════════════════════════════════

// ─── MODULE A — MORNING STORY REPORT ENGINE ───────────────────────────

// Extract all narrative inputs from the current pack into a flat object
function getMorningStoryNarrativeInputs(pack) {
  pack = pack || state.pack || {};
  const price   = n(pack.xrp_price);
  const delta24 = pack.xrp_delta_24h_pct;
  const vol     = n(pack.xrp_volume_24h);
  const netDelta = n(pack.total_balance_delta_xrp);
  const shadowVol = n(pack.shadow_volume_xrp);
  const largeTxs = pack.large_transfers || [];
  const receivers = pack.receiver_followthrough || [];
  const risk    = pack.risk_score || state.riskScore || {};
  const healthResult = (() => { try { return getSourceHealth(pack); } catch { return { degraded: false, partial_coverage: false, failed: [] }; } })();
  const topItems = (() => { try { return rankNewsItems(getNewsSources(pack)).slice(0, 5); } catch { return []; } })();
  const discInbox = state.discoveryInbox || [];
  const patMem   = (() => { try { return summarizePatternMemory(pack); } catch { return { lines: ['Pattern memory offline.'], snapCount: 0 }; } })();
  const tone     = state.dailyTone || (() => { try { return buildDailyTone(pack); } catch { return { prayer: '', scripture: { ref: '', text: '' } }; } })();

  // Price tape descriptor
  const tape = !price ? 'an unmeasured tape'
    : delta24 == null ? 'a flat tape'
    : delta24 > 3     ? 'a strong green tape'
    : delta24 < -3    ? 'a hard red tape'
    : delta24 > 1     ? 'a firm tape'
    : delta24 < -1    ? 'a soft tape'
    : 'a flat tape';

  // Flow direction descriptor
  const flowDir = netDelta > 500_000 ? 'net inflow' : netDelta < -500_000 ? 'net outflow' : 'flat net flow';

  // Top large transfer
  const topTx = largeTxs.length
    ? [...largeTxs].sort((a, b) => n(b.amount) - n(a.amount))[0]
    : null;

  // Top receiver with forwarding behavior
  const forwardingReceiver = receivers.find(r => n(r.forwarded_large_count) > 0);
  const holdingReceiver    = receivers.find(r => n(r.forwarded_large_count) === 0 && r.balance_xrp != null);

  return {
    price, delta24, vol, netDelta, shadowVol, largeTxs, receivers,
    risk, healthResult, topItems, discInbox, patMem, tone,
    tape, flowDir, topTx, forwardingReceiver, holdingReceiver,
    reportId: pack.report_id || pack.report_id || state.reportId || '',
    dateStamp: pack.date || today(),
    scanTime: pack.data_as_of_utc ? pack.data_as_of_utc.slice(0, 5) + ' UTC' : ''
  };
}

// Pick the single strongest opening hook based on the evidence
function chooseMorningStoryLead(pack) {
  const i = getMorningStoryNarrativeInputs(pack);
  if (n(i.risk.score) >= 75) return 'RISK';
  if (i.largeTxs.length >= 5) return 'LARGE_FLOW';
  if (i.shadowVol > 10_000_000) return 'SHADOW_VOLUME';
  if (i.patMem.snapCount >= 5 && (i.patMem.lines || []).some(l => /repeated.*×[4-9]|×\d{2,}/i.test(l))) return 'PATTERN';
  // v3.32e: only lead with "wires went quiet" when there's genuinely NO news to show.
  // Previously fired on any provider failure, contradicting a report that still had headlines.
  if (i.healthResult.degraded && !(i.topItems && i.topItems.length)) return 'SOURCE_DEGRADED';
  return 'STANDARD';
}

// Opening paragraph — 3-5 sentences
function _buildOpeningParagraph(i, lead) {
  const priceStr = i.price ? '$' + i.price.toFixed(4) : 'an unverified price';
  const deltaStr = i.delta24 != null ? (i.delta24 >= 0 ? '+' : '') + i.delta24.toFixed(2) + '%' : '';
  const flowAmt  = fmt(Math.abs(i.netDelta), 0);

  switch (lead) {
    case 'RISK': {
      const flowVerb = i.netDelta >= 0
        ? 'took in ' + flowAmt + ' XRP net'
        : 'pushed out ' + flowAmt + ' XRP net';
      return `The board lit up ${i.risk.label} this morning — the highest alert level we flag. Price barely moved (${deltaStr || 'flat'}) on ${i.tape}, but the ledger was anything but quiet: watched wallets showed ${i.flowDir} across the window. Here's what the data actually shows — not what the chart suggests. (Score and drivers in the verdict below.)`;
    }
    case 'LARGE_FLOW':
      return `${i.largeTxs.length} transfers above threshold moved ${fmt(i.shadowVol, 0)} XRP in shadow volume overnight. Price was on ${i.tape} at ${priceStr}${deltaStr ? ' (' + deltaStr + ')' : ''}, but the bigger story was in the ledger — not the candle. The strongest signal was where those transfers landed and whether receivers split or held.`;
    case 'SHADOW_VOLUME':
      return `${fmt(i.shadowVol, 0)} XRP moved through watched-wallet shadow channels overnight — a volume that doesn't show in a standard chart view. Price held ${i.tape} at ${priceStr}. The ledger was not idle, even when the tape appeared quiet.`;
    case 'PATTERN':
      return `The route appeared again. Pattern memory across ${i.patMem.snapCount} scans flagged a repeated behavior that has now cleared the confidence threshold. Price was on ${i.tape} at ${priceStr}. Forensic significance comes from repetition, not from any single data point.`;
    case 'SOURCE_DEGRADED': {
      // v3.32d: drop junk tokens like "all" from the failed list, and read like a person.
      const failedList = (i.healthResult.failed || [])
        .filter(f => f && !/^all(-failed)?$/i.test(f))
        .slice(0, 3).join(', ');
      const failedPhrase = failedList ? failedList + ' dropped out' : 'the news wires went quiet';
      return `The wires were spotty this morning — ${failedPhrase} mid-scan, so today's story leans on the ledger. Price sat ${deltaStr ? '(' + deltaStr + ') ' : ''}on ${i.tape} at ${priceStr}, and the on-chain evidence carries the rest.`;
    }
    default: {
      const flowVerb = i.netDelta >= 0
        ? 'took in ' + flowAmt + ' XRP net'
        : 'pushed out ' + flowAmt + ' XRP net';
      return `XRP opened the session on ${i.tape} at ${priceStr}${deltaStr ? ' (' + deltaStr + ')' : ''}. The ledger showed ${i.flowDir} — watched wallets ${flowVerb} across the window. The evidence is presented below — evidence first, pattern second, thesis third.`;
    }
  }
}

// Ledger Story paragraph
function buildLedgerNarrativeParagraph(pack) {
  const i = getMorningStoryNarrativeInputs(pack);
  const lines = [];
  const _wc = n(pack.wallets_checked || 0);
  if (Math.abs(i.netDelta) < 1) {
    lines.push('Across ' + _wc + ' watched wallets the net position came out flat this window — money changed hands, but the board ended roughly where it started.');
  } else {
    lines.push('Net flow across ' + _wc + ' watched wallets: ' +
      (i.netDelta >= 0 ? '+' : '') + fmt(i.netDelta, 0) + ' XRP.');
  }
  if (i.shadowVol > 0) {
    lines.push('Shadow volume: ' + fmt(i.shadowVol, 0) + ' XRP across ' + i.largeTxs.length + ' flagged transfer' + (i.largeTxs.length === 1 ? '' : 's') + '.');
  }
  if (i.topTx) {
    const sender = _swWho(i.topTx.from, i.topTx.sender_label || i.topTx.label);
    const recvLabel = _swWho(i.topTx.to, (i.topTx.receiver_label && i.topTx.receiver_label !== 'UNKNOWN') ? i.topTx.receiver_label : null);
    lines.push('Strongest single transfer: ' + sender + ' → ' + recvLabel + ', ' + fmt(n(i.topTx.amount), 0) + ' XRP. Classification: ' + _swCls(i.topTx.classification) + ' [' + _swConf(i.topTx.confidence) + '].');
  }
  if (i.forwardingReceiver) {
    lines.push('Receiver ' + _swWho(i.forwardingReceiver.address, i.forwardingReceiver.label, { bare: true }) + ' forwarded ' + n(i.forwardingReceiver.forwarded_large_count) + ' large tx onward — consistent with routing, not holding.');
  } else if (i.holdingReceiver) {
    lines.push('Receiver ' + _swWho(i.holdingReceiver.address, i.holdingReceiver.label, { bare: true }) + ' held position after inflow — no large forward detected.');
  }
  return lines.join(' ');
}

// Pattern Memory paragraph
function buildPatternNarrativeParagraph(pack) {
  const i = getMorningStoryNarrativeInputs(pack);
  const pm = i.patMem;
  if (pm.snapCount < 5) {
    return 'Pattern memory is still warming up. The app has ' + pm.snapCount + ' snapshot' + (pm.snapCount === 1 ? '' : 's') + '; it needs 5 or more before repeat behavior becomes meaningful.';
  }
  const repeated = (() => { try { return getRepeatedPatterns(); } catch { return []; } })();
  if (!repeated.length) {
    return 'Pattern memory has ' + pm.snapCount + ' snapshots on record, but no single route or behavior has cleared the public repeat threshold yet. Board is behaviorally quiet across the window.';
  }
  const top3 = repeated.slice(0, 3);
  const intro = 'Across ' + pm.snapCount + ' stored scans, pattern memory flagged ' + repeated.length + ' repeated behavior' + (repeated.length === 1 ? '' : 's') + '. ';
  const desc  = top3.map(p => p.public_summary.replace(/\.$/, '') + ' (×' + p.times_seen + ', ' + p.confidence + ')').join('; ') + '.';
  return intro + desc + ' Pattern repetition suggests behavioral recurrence — not ownership proof, not causation proof.';
}

// News + Macro paragraph — ledger first, news as context only.
// v3.26-hotfix1: gated on shared pack.news_health.newsMode.
// LEDGER_ONLY        → no headlines, no "Key context"
// PARTIAL_CONTEXT    → "News context was partial this scan" only, no headlines
// HEALTHY_CONTEXT    → broad-market headlines allowed, labeled as such
// EVIDENCE_LED_CONTEXT → ledger-matched headlines surfaced
function buildNewsNarrativeParagraph(pack) {
  const i = getMorningStoryNarrativeInputs(pack);
  const health = (pack && pack.news_health) ||
                 (typeof computeNewsHealth === 'function' ? computeNewsHealth(pack) : null);
  const mode = health ? health.newsMode : 'LEDGER_ONLY';

  if (mode === 'LEDGER_ONLY') {
    return 'No live headlines loaded for this run. Ledger evidence stands alone.';
  }
  if (mode === 'PARTIAL_CONTEXT') {
    return 'News context was partial this scan; ledger evidence remains primary.';
  }
  // HEALTHY_CONTEXT or EVIDENCE_LED_CONTEXT — headlines allowed
  // v3.26-hotfix9: toned-down opening line. Was "The news backdrop matters" /
  // "Hidden Narrative" / "institutional rails" — replaced with measured framing
  // to avoid overclaiming when the matched headlines are opinion/analysis pieces.
  const lines = [];
  lines.push('News context is active, but ledger evidence remains primary.');
  if (mode === 'EVIDENCE_LED_CONTEXT') {
    // Prefer ledger-matched articles from the router.
    // v3.26-hotfix9: PUBLIC reports use STRONG or MEDIUM matches only.
    // WEAK matches (generic exchange/listing keyword only, no XRP brand,
    // no macro) are kept in internal diagnostics but never surfaced publicly.
    const allMatched = (pack && pack.news_intelligence_router && pack.news_intelligence_router.matched_articles) || [];
    const publicMatched = allMatched.filter(a =>
      a.match_strength === 'STRONG' || a.match_strength === 'MEDIUM'
    );
    const topMatched = publicMatched.slice(0, 3).map(a => a.title).filter(Boolean);
    if (topMatched.length) {
      lines.push('Ledger-matched context: ' + topMatched.join(' · ') + '.');
      return lines.join(' ');
    }
    // Fall through to HEALTHY style if no STRONG/MEDIUM matches survived
    // (the headlines were all WEAK keyword-only matches — not publishable as evidence-led).
  }
  // HEALTHY_CONTEXT — list top XRP-relevant headlines, regardless of _priority
  // v3.26-hotfix5: previously required _priority<=2 which suppressed valid
  // XRP-mentioning headlines when the ranker didn't tag them as priority 1/2.
  const xrpItems = i.topItems
    .filter(it => XRP_RELEVANCE_RX.test((it.title || '') + ' ' + (it.summary || '')))
    .slice(0, 3);
  if (xrpItems.length) {
    lines.push('Regulatory/liquidity headlines are active context, not causation proof: ' +
               xrpItems.map(it => it.title || '').filter(Boolean).join(' · ') + '.');
  } else if (i.topItems.length) {
    lines.push('Broad-market context (not XRP-specific): ' + (i.topItems[0].title || '') + '.');
  }
  return lines.join(' ');
}

// Discovery paragraph
function buildDiscoveryNarrativeParagraph(pack) {
  const inbox = (state.discoveryInbox || []).filter(c => c.review_status !== 'REJECTED' && c.review_status !== 'SUPPRESSED');
  if (!inbox.length) {
    return 'No new related-wallet candidate cleared the review threshold this scan. Behavioral evidence only — not ownership proof.';
  }
  const recommended = inbox.filter(c => c.recommended_action === 'RECOMMEND_FOR_WATCH' || c.review_status === 'RECOMMENDED' || c.review_status === 'APPROVED');
  const top = inbox[0];
  const topAddr = top.address.slice(0, 8) + '…' + top.address.slice(-4);
  let out = inbox.length + ' related-wallet candidate' + (inbox.length === 1 ? '' : 's') + ' appeared this scan. ' +
    (recommended.length ? recommended.length + ' flagged for review. ' : '') +
    'They are not automatically trusted — parked in Discovery Inbox until reviewed. ';
  out += 'Top candidate: ' + topAddr + ' · ' + (top.classification || 'UNKNOWN') + ' · score ' + n(top.score) + '.';
  out += ' Not ownership proof. Behavioral evidence only.';
  return out;
}

// Verdict paragraph — plain English, risk-label preserved
function buildMorningVerdictParagraph(pack) {
  const risk   = (pack && pack.risk_score) || state.riskScore || {};
  const score  = n(risk.score);
  const label  = risk.label || (score >= 75 ? 'BLACK / EXTREME' : score >= 50 ? 'ORANGE / ACTIVE' : score >= 25 ? 'YELLOW / WATCH' : 'GREEN / QUIET');
  const pub    = score >= 75 ? 'HIGH / FORENSICS WATCH' : score >= 50 ? 'ELEVATED / MONITOR' : score >= 25 ? 'MODERATE / WATCH' : 'LOW / QUIET';
  const netDelta = n((pack && pack.total_balance_delta_xrp) || 0);
  const largeCt  = (pack && (pack.large_transfers || []).length) || 0;

  let sentiment;
  if (score >= 75)      sentiment = 'The evidence picture is forensically significant.';
  else if (score >= 50) sentiment = 'Activity level is elevated above baseline.';
  else if (score >= 25) sentiment = 'Moderate signals are present; nothing extreme.';
  else                  sentiment = 'Board is quiet. No significant forensic signals.';

  const drivers = (risk.drivers || []).slice(0, 3).join(', ');
  const riskLine = score + '/100 — ' + label + (label !== pub ? ' (' + pub + ')' : '') + '. ';

  let verdict = 'Risk: ' + riskLine + sentiment;
  if (drivers) verdict += ' Primary drivers: ' + drivers + '.';
  // v3.32c: the transfer count and the net-flow figure are already stated in the
  // opening and LEDGER STORY — keep the verdict qualitative so the report stops
  // repeating the same numbers three and four times.
  if (netDelta > 500_000) verdict += ' The net inflow above reads as accumulation or inward routing.';
  else if (netDelta < -500_000) verdict += ' The net outflow above reads as distribution or outward routing.';
  // v3.32e: CONFIDENCE FRAME folded in here (was its own section) — one clear read.
  const behavioral = score >= 75 ? 'high' : score >= 50 ? 'medium' : 'low';
  const confAction = behavioral === 'high' ? 'review and consider monitoring'
                   : behavioral === 'medium' ? 'monitor' : 'review only';
  verdict += ' No identity proof — behavioral confidence is ' + behavioral + '; recommended action: ' + confAction + '.';
  verdict += '\nLedger evidence is the primary record. News provides context, not causation.';
  return verdict;
}

// Build the complete Morning Story as plain text (for downloads + state storage)
function buildMorningStoryText(pack) {
  pack = pack || state.pack || {};
  const i    = getMorningStoryNarrativeInputs(pack);
  const lead = chooseMorningStoryLead(pack);
  const r    = [];

  // v3.26-hotfix7: use the same branded header as the Daily Report.
  // The "Lady K's / Coffee & Crypto" header is the operator's signature
  // and must appear on every public report variant.
  if (typeof buildBrandedHeader === 'function') {
    r.push(buildBrandedHeader());
    r.push('');
  } else {
    // Fallback (defensive — should never hit)
    r.push('🩸 XRPMAN PRESENTS 🩸');
    r.push('SHADOW WATCH');
    r.push('RedCandleKiller');
  }
  r.push('XRPL Morning Forensic Brief');
  if (i.dateStamp) r.push(i.dateStamp + (i.scanTime ? ' · ' + i.scanTime : '') + (i.reportId ? ' · ' + i.reportId : ''));
  r.push('');

  // Opening narrative
  r.push(_buildOpeningParagraph(i, lead));
  r.push('');

  // Ledger Story
  r.push('LEDGER STORY');
  r.push(buildLedgerNarrativeParagraph(pack));
  r.push('');

  // Escrow Watch — treasury / supply movement (news context, not a trade signal)
  r.push('ESCROW WATCH');
  r.push(buildEscrowNarrative(pack));
  r.push('');

  // Pattern Memory
  r.push('PATTERN MEMORY');
  r.push(buildPatternNarrativeParagraph(pack));
  r.push('');

  // News + Macro
  r.push('NEWS + MACRO');
  r.push(buildNewsNarrativeParagraph(pack));
  r.push('');

  // Discovery
  r.push('DISCOVERY');
  r.push(buildDiscoveryNarrativeParagraph(pack));
  r.push('');

  // Verdict
  r.push('VERDICT');
  r.push(buildMorningVerdictParagraph(pack));
  r.push('');

  // Sign-off
  r.push('⚠️ This is not financial advice.');
  r.push('');
  r.push("I'm XRPMan, and I tell on the banks.");
  r.push('');

  // Prayer / scripture (kept, at the bottom)
  if (i.tone.prayer) {
    r.push('🙏 THE DAILY PRAYER');
    r.push(i.tone.prayer);
    r.push('');
  }
  if (i.tone.scripture && i.tone.scripture.ref) {
    r.push('📖 THE DAILY SCRIPTURE');
    r.push(i.tone.scripture.ref);
    r.push('"' + i.tone.scripture.text + '"');
    r.push('');
  }

  // Sources block with raw URLs (required for TXT mode)
  try {
    if (typeof renderPlainTextSources === 'function') {
      // v16.19: same relevance filter as the structured report — an XRP report
      // must not cite a Solar/SXP price prediction just to fill the block.
      const ranked = typeof filterSourcesForReport === 'function'
        ? filterSourcesForReport(i.topItems.length ? i.topItems : getNewsSources(pack))
        : (typeof rankNewsItems === 'function'
            ? rankNewsItems(i.topItems.length ? i.topItems : getNewsSources(pack)).slice(0, 8)
            : []);
      if (ranked.length) {
        const src = renderPlainTextSources(ranked);
        if (src) { r.push(''); r.push(src); }
      }
    }
  } catch (_) {}

  return r.join('\n');
}

// Build the clickable HTML version for the Command Center viewer
function buildMorningStoryHtml(pack) {
  pack = pack || state.pack || {};
  const i    = getMorningStoryNarrativeInputs(pack);
  const lead = chooseMorningStoryLead(pack);
  const health = i.healthResult;

  // Build text body, strip any plain-text SOURCES block (will be replaced with clickable)
  let textBody = buildMorningStoryText(pack);
  // DAILY BRIEF GATE (view): when today's brief is locked, the full-screen
  // report shows the SAME governed brief as the popup — no fresh leak here.
  // Scoped to the live pack so mock-pack self-tests stay deterministic.
  try {
    var _live = (typeof state !== 'undefined' && state) ? state.pack : null;
    if (pack && pack === _live &&
        window.SW_DAILY_GATE && typeof window.SW_DAILY_GATE.viewBrief === 'function') {
      textBody = window.SW_DAILY_GATE.viewBrief(textBody, pack);
    }
  } catch (_) {}
  const cleaned  = textBody.replace(/\n{1,3}SOURCES[\s\S]*$/m, '').trimEnd();

  let html = '';

  // v3.26-hotfix4: source degradation warning REMOVED from public report.
  // Failed-provider details belong in News Doctor, News Source Strategy,
  // NewsDiagnostics export, Evidence Bundle, and GPT Package — NOT on the
  // public Morning Story or Daily Report viewer.

  // Report body — pre-formatted, escaped
  html += '<pre class="cmd-report-pre">' + escapeHTML(cleaned) + '</pre>';

  // Clickable sources block
  try {
    const ranked = typeof rankNewsItems === 'function'
      ? rankNewsItems(typeof getNewsSources === 'function' ? getNewsSources(pack) : []).slice(0, 8)
      : [];
    if (ranked.length && typeof renderClickableSources === 'function') {
      html += renderClickableSources(ranked);
    }
  } catch (_) {}

  return html;
}

// Agent mode — structured with source status metadata
function buildMorningStorySources(pack) {
  const items = typeof rankNewsItems === 'function'
    ? rankNewsItems(typeof getNewsSources === 'function' ? getNewsSources(pack) : []).slice(0, 8)
    : [];
  return items;
}

// Main entry point
function buildMorningStoryReport(pack, mode) {
  mode = mode || 'text';
  pack = pack || state.pack || {};
  if (mode === 'html') return buildMorningStoryHtml(pack);
  if (mode === 'agent') {
    const health = typeof getSourceHealth === 'function' ? getSourceHealth(pack) : {};
    return buildMorningStoryText(pack) + '\n\nSTRUCTURED SOURCE STATUS\n' +
      'degraded: ' + (health.degraded ? 'true' : 'false') + '\n' +
      'partial_coverage: ' + (health.partial_coverage ? 'true' : 'false') + '\n' +
      'failed_providers: ' + ((health.failed || []).join(', ') || 'none');
  }
  return buildMorningStoryText(pack);
}

// Expose
if (typeof window !== 'undefined') {
  window.buildMorningStoryReport = buildMorningStoryReport;
  window.buildMorningStoryHtml   = buildMorningStoryHtml;
  window.buildMorningStoryText   = buildMorningStoryText;
  window.buildMorningStorySources= buildMorningStorySources;
  window.getMorningStoryNarrativeInputs = getMorningStoryNarrativeInputs;
  window.chooseMorningStoryLead  = chooseMorningStoryLead;
  window.buildLedgerNarrativeParagraph   = buildLedgerNarrativeParagraph;
  window.buildPatternNarrativeParagraph  = buildPatternNarrativeParagraph;
  window.buildNewsNarrativeParagraph     = buildNewsNarrativeParagraph;
  window.buildDiscoveryNarrativeParagraph= buildDiscoveryNarrativeParagraph;
  window.buildMorningVerdictParagraph    = buildMorningVerdictParagraph;
}

// ─── MODULE B — EVIDENCE-LED NEWS ROUTER ──────────────────────────────

// Evidence trigger classes — what the ledger found that should drive news context
const NEWS_ROUTER_TRIGGERS = [
  'LARGE_EXCHANGE_OUTFLOW', 'WHALE_TO_UNKNOWN', 'UNKNOWN_RECEIVER_SPLIT',
  'REPEATED_COUNTERPARTY', 'DUST_TAG_CLUSTER', 'AMM_LIQUIDITY_CHANGE',
  'DISCOVERY_CANDIDATE', 'NEWS_SOURCE_DEGRADED', 'COORDINATION_MEMORY_ACTIVE'
];

// Classify what the ledger found → which news topics are needed
function classifyLedgerNewsNeeds(pack) {
  pack = pack || {};
  const triggers = [];
  const largeTxs = pack.large_transfers || [];
  const receivers = pack.receiver_followthrough || [];

  largeTxs.forEach(t => {
    if (t.classification === 'EXCHANGE_OUTFLOW') triggers.push('LARGE_EXCHANGE_OUTFLOW');
    if (t.classification === 'WHALE_TO_UNKNOWN') triggers.push('WHALE_TO_UNKNOWN');
  });
  if (receivers.some(r => n(r.forwarded_large_count) > 0)) triggers.push('UNKNOWN_RECEIVER_SPLIT');

  const bc = state.behavioralClusters;
  if (bc && bc.cluster_count > 0) triggers.push('REPEATED_COUNTERPARTY');
  if ((pack.fragmentation_flags || []).length > 0) triggers.push('DUST_TAG_CLUSTER');
  if (n(pack.xrpl_evm_tvl_usd) > 0 || n(pack.xrpl_dex_volume_24h_usd) > 0) triggers.push('AMM_LIQUIDITY_CHANGE');
  if ((state.discoveryInbox || []).length > 0) triggers.push('DISCOVERY_CANDIDATE');
  try {
    const h = getSourceHealth(pack);
    if (h.degraded) triggers.push('NEWS_SOURCE_DEGRADED');
  } catch (_) {}
  const coord = state.coordination || pack.coordination;
  if (coord && coord.snapshots_analyzed >= 5 && (coord.pairs || []).length > 0) triggers.push('COORDINATION_MEMORY_ACTIVE');

  return [...new Set(triggers)];
}

// Build query intents from ledger evidence
function buildEvidenceLedNewsQueries(pack) {
  pack = pack || {};
  const triggers = classifyLedgerNewsNeeds(pack);
  const intents  = [];

  // Always include baseline XRP/Ripple query
  intents.push({ query: 'XRP Ripple RLUSD banking regulation', reason: 'baseline XRP context', trigger: 'BASELINE', priority: 1 });

  const largeTxs = pack.large_transfers || [];

  // Per-trigger queries
  triggers.forEach(trigger => {
    switch (trigger) {
      case 'LARGE_EXCHANGE_OUTFLOW': {
        // Named exchanges from large transfers
        const exchanges = [...new Set(largeTxs.filter(t => t.classification === 'EXCHANGE_OUTFLOW').map(t => t.sender_label || '').filter(Boolean))];
        exchanges.slice(0, 3).forEach(ex => {
          const short = ex.split('_')[0];
          intents.push({ query: short + ' XRP outflow', reason: 'large exchange outflow detected from ' + ex, trigger, priority: 1 });
        });
        intents.push({ query: 'XRP exchange outflow liquidity', reason: 'exchange outflow pattern', trigger, priority: 2 });
        break;
      }
      case 'WHALE_TO_UNKNOWN':
        intents.push({ query: 'XRP whale transfer destination', reason: 'whale-to-unknown transfer detected', trigger, priority: 1 });
        break;
      case 'UNKNOWN_RECEIVER_SPLIT':
        intents.push({ query: 'XRP routing splitting OTC', reason: 'receiver forwarding detected', trigger, priority: 2 });
        break;
      case 'REPEATED_COUNTERPARTY':
        intents.push({ query: 'XRP repeated counterparty coordination', reason: 'behavioral cluster active', trigger, priority: 2 });
        break;
      case 'DUST_TAG_CLUSTER':
        intents.push({ query: 'XRP fragmentation dust payment banking', reason: 'dust/tag cluster detected', trigger, priority: 3 });
        break;
      case 'AMM_LIQUIDITY_CHANGE':
        intents.push({ query: 'XRPL AMM RLUSD liquidity DEX', reason: 'AMM/DEX activity detected', trigger, priority: 2 });
        break;
      case 'DISCOVERY_CANDIDATE':
        intents.push({ query: 'Ripple XRP custody partner stablecoin', reason: 'discovery candidates suggest institutional context', trigger, priority: 3 });
        break;
      case 'NEWS_SOURCE_DEGRADED':
        intents.push({ query: 'XRP regulation enforcement SEC CFTC 2026', reason: 'supplementing degraded news', trigger, priority: 2 });
        break;
      case 'COORDINATION_MEMORY_ACTIVE':
        intents.push({ query: 'XRP coordinated exchange flow', reason: 'coordination memory active', trigger, priority: 2 });
        break;
    }
  });

  // Dedupe by query
  const seen = new Set();
  return intents.filter(intent => {
    if (seen.has(intent.query)) return false;
    seen.add(intent.query);
    return true;
  }).sort((a, b) => a.priority - b.priority);
}

function buildNewsQueryReasons(pack) {
  return buildEvidenceLedNewsQueries(pack).map(q => q.query + ' → ' + q.reason);
}

// Score a news item for relevance to the current ledger evidence
function scoreNewsItemAgainstLedger(item, pack) {
  if (!item || !item.title) return 0;
  pack = pack || {};
  const text  = (item.title + ' ' + (item.summary || '') + ' ' + (item.source || '')).toLowerCase();
  const largeTxs = pack.large_transfers || [];
  let score = 0;

  // Base: priority from rankNewsItems
  if (item._priority === 1)      score += 40;
  else if (item._priority === 2) score += 25;
  else if (item._priority === 3) score += 10;
  else if (item._priority === 5) score -= 20; // price hype demoted

  // Ledger-specific boosts
  largeTxs.forEach(t => {
    const exName = (t.sender_label || '').split('_')[0].toLowerCase();
    if (exName && text.includes(exName)) score += 15;
  });
  if (/rlusd|stablecoin|stable.coin/.test(text)) score += 20;
  if (/etf|regulation|sec|cftc|clarity\s+act/.test(text)) score += 15;
  if (/custody|prime.broker|standard\s+custody|hidden\s+road/.test(text)) score += 15;
  if (/korea|japan|sbi|upbit|bithumb|bitbank|bitflyer/.test(text)) score += 12;

  return score;
}

function rankNewsForLedgerContext(items, pack) {
  if (!Array.isArray(items)) return [];
  pack = pack || {};
  const base = (typeof rankNewsItems === 'function') ? rankNewsItems(items) : items;
  return base.map(item => ({
    ...item,
    _ledger_score: scoreNewsItemAgainstLedger(item, pack)
  })).sort((a, b) => b._ledger_score - a._ledger_score);
}

// Attach news intent router data to pack. Called post-scan.
// v3.26-hotfix9: match strength classifier for headline-trigger pairs.
// Returns { strength, matched_terms, reason_code } so public reports can
// filter to STRONG/MEDIUM only, while internal diagnostics keep WEAK ones.
//
// STRONG = XRP/XRPL/Ripple/RLUSD + trigger-specific keyword
// MEDIUM = broad crypto/macro keyword + trigger-specific keyword
// WEAK   = generic exchange/liquidity/listing keyword only (no XRP, no macro)
function classifyMatchStrength(article, intent) {
  const title   = (article && article.title   || '').toLowerCase();
  const summary = (article && article.summary || '').toLowerCase();
  const blob    = title + ' ' + summary;
  const trigger = (intent && intent.trigger) || '';

  const xrpHit = /\b(xrp|xrpl|ripple|rlusd|xls-?\d+|escrow)\b/.test(blob);
  const macroHit = /\b(bitcoin|btc|ethereum|eth|crypto|stablecoin|cbdc|sec|cftc|fed|sec[\s-]?ruling|clarity[\s-]?act|etf|custody|bank|banking|liquidity)\b/.test(blob);

  // Trigger-specific keyword maps (lowercase). Tuned for the LEDGER TRIGGERS
  // we actually emit: LARGE_EXCHANGE_OUTFLOW, REPEATED_COUNTERPARTY,
  // DUST_TAG_CLUSTER, AMM_LIQUIDITY_CHANGE, DISCOVERY_CANDIDATE,
  // NEWS_SOURCE_DEGRADED, WHALE_TO_UNKNOWN.
  // v3.26-hotfix9: plural/conjugation forms covered (withdraws, outflows, listings, etc.)
  const triggerKwMap = {
    LARGE_EXCHANGE_OUTFLOW: /\b(outflows?|withdraw(?:s|n|al|als|ing)?|exchange[\s-]?balance|exits?\s+exchange|move(d|s)?\s+to\s+cold)\b/,
    WHALE_TO_UNKNOWN:       /\b(whales?|large[\s-]?holders?|unknown[\s-]?wallets?|cold[\s-]?wallets?|accumulat)/,
    REPEATED_COUNTERPARTY:  /\b(repeat|recurr|patterns?|routes?|counterpart(?:y|ies)|relationship)/,
    DUST_TAG_CLUSTER:       /\b(dust|tags?|fragment|small[\s-]?payments?|micro[\s-]?transactions?)/,
    AMM_LIQUIDITY_CHANGE:   /\b(amm|liquidity[\s-]?pool|tvl|pool[\s-]?balance|liquidity\s+change)\b/,
    DISCOVERY_CANDIDATE:    /\b(new[\s-]?wallets?|emerging|discovery|fresh[\s-]?address)/,
    NEWS_SOURCE_DEGRADED:   /\b(news|coverage|media)/,
    BASELINE:               /\b(market|liquidity|flows?|movements?|signals?)/
  };
  const triggerRx = triggerKwMap[trigger] || triggerKwMap.BASELINE;
  const triggerHit = triggerRx.test(blob);
  const triggerMatchText = triggerHit ? (blob.match(triggerRx) || [''])[0] : '';

  // Generic exchange/listing keyword check (the WEAK floor)
  const genericExchangeHit = /\b(exchange|listing|launch|debut|listed|trading[\s-]?pair|cex|dex)\b/.test(blob);

  // Collect terms hit for transparency
  const matched_terms = [];
  if (xrpHit)               matched_terms.push((blob.match(/\b(xrp|xrpl|ripple|rlusd|xls-?\d+|escrow)\b/) || [''])[0]);
  if (macroHit && !xrpHit)  matched_terms.push((blob.match(/\b(bitcoin|btc|ethereum|eth|crypto|stablecoin|cbdc|sec|cftc|fed|sec[\s-]?ruling|clarity[\s-]?act|etf|custody|bank|banking|liquidity)\b/) || [''])[0]);
  if (triggerHit)           matched_terms.push(triggerMatchText);

  // Score
  let strength, reason_code;
  if (xrpHit && triggerHit) {
    strength = 'STRONG';
    reason_code = 'XRP_BRAND_PLUS_TRIGGER';
  } else if (macroHit && triggerHit) {
    strength = 'MEDIUM';
    reason_code = 'MACRO_PLUS_TRIGGER';
  } else if (xrpHit) {
    strength = 'MEDIUM';
    reason_code = 'XRP_BRAND_ONLY';
  } else if (triggerHit && genericExchangeHit) {
    strength = 'WEAK';
    reason_code = 'GENERIC_TRIGGER_KEYWORD';
  } else if (genericExchangeHit) {
    strength = 'WEAK';
    reason_code = 'GENERIC_EXCHANGE_KEYWORD';
  } else {
    strength = 'WEAK';
    reason_code = 'NO_STRONG_LINK';
  }

  return { strength, matched_terms: matched_terms.filter(Boolean), reason_code };
}

function attachNewsIntentToPack(pack) {
  if (!pack) return;
  const now = new Date().toISOString();
  const triggers   = classifyLedgerNewsNeeds(pack);
  const queryIntents = buildEvidenceLedNewsQueries(pack);
  const items = (pack.news_intel && (pack.news_intel.items || pack.news_intel.top_headlines)) || [];
  const ranked = rankNewsForLedgerContext(items, pack);

  // v3.26: LOCAL matcher — match collected headlines against triggers.
  // The remote GDELT/Google News fetch usually fails in-browser; the
  // matcher works on whatever headlines we DO have, so query intents
  // actually produce evidence-led results instead of returning 0.
  let matched = [], unmatched = [];
  if (typeof matchHeadlinesToTriggers === 'function') {
    const result = matchHeadlinesToTriggers(items, queryIntents);
    matched = result.matched;
    unmatched = result.unmatched;
  }
  // Flatten matched articles for the existing evidence_results list
  // v3.26-hotfix9: each article gets a match_strength (STRONG/MEDIUM/WEAK)
  // so public reports can filter to STRONG+MEDIUM and internal diagnostics
  // can show everything.
  const matchedArticles = [];
  matched.forEach(m => {
    m.articles.forEach(a => {
      const strength = classifyMatchStrength(a, m.intent);
      matchedArticles.push({
        title: a.title, url: a.url, source: a.source,
        query: m.intent.query, trigger: m.intent.trigger || 'BASELINE',
        match_hits: a._match_hits || 0,
        // v3.26-hotfix9 fields:
        match_strength: strength.strength,
        matched_terms:  strength.matched_terms,
        reason_code:    strength.reason_code,
        why: 'matched ' + (a._match_hits || 0) + ' keyword(s) for trigger ' +
             (m.intent.trigger || 'BASELINE') + ' (' + strength.strength + ' · ' + strength.reason_code + ')'
      });
    });
  });

  pack.news_intelligence_router = {
    generated_at: now,
    evidence_triggers: triggers,
    query_intents: queryIntents,
    searched_queries:   [],   // filled by fetchGoogleNewsForQuery if available
    failed_queries:     [],
    google_news_results:[],
    // v3.26: local-match results — populated even when remote fetch fails
    matched_articles: matchedArticles,
    // v3.26-hotfix9: counts by match strength tier (for diagnostics)
    matched_strong_count: matchedArticles.filter(a => a.match_strength === 'STRONG').length,
    matched_medium_count: matchedArticles.filter(a => a.match_strength === 'MEDIUM').length,
    matched_weak_count:   matchedArticles.filter(a => a.match_strength === 'WEAK').length,
    searched_intents: matched.map(m => m.intent),
    unmatched_intents: unmatched,
    evidence_led_results_count: matchedArticles.length,
    ranked_context: ranked.slice(0, 8).map(it => ({
      title: it.title, source: it.source, url: it.url,
      priority: it._priority, ledger_score: it._ledger_score,
      source_rank: typeof classifyNewsSourceRank === 'function' ? classifyNewsSourceRank(it) : 'C'
    })),
    // v16.9: state the limits that BIT this run, not a permanent footnote. The
    // Google News CORS caveat was printed on every report including the ones
    // where Google News was the source of the winning headline — a limit that
    // never applies reads as boilerplate and gets skipped along with the real
    // ones underneath it.
    source_limits: _routerSourceLimits()
  };

  // v3.26: also attach centralized news health to pack
  if (typeof attachNewsHealthToPack === 'function') attachNewsHealthToPack(pack);
}

function _routerSourceLimits() {
  const out = [];
  try {
    const hist = (typeof getNewsDoctorHistory === 'function' ? getNewsDoctorHistory() : null) || {};
    Object.keys(hist).forEach(k => {
      const h = hist[k] || {};
      if (n(h.consecutive_failures) >= 3)
        out.push(k + ': unavailable this run and the ' + n(h.consecutive_failures) +
                 ' before it — its coverage is missing from the pool above.');
    });
  } catch (_) {}
  try {
    // Only mention the browser-CORS limit when it actually cost us something.
    // Provider status lives on state.newsDiagnostics, the same object
    // buildNewsSourceStrategy reads.
    const gn = ((state.newsDiagnostics || {}).providers || {})['Google News'];
    if (gn && gn.overall_status && !/CONTENT_OK/.test(gn.overall_status))
      out.push('google_news: in-browser CORS blocked this fetch; a backend proxy is needed for it to be reliable.');
  } catch (_) {}
  if (!out.length) out.push('None hit this run — every configured source answered.');
  return out;
}

// Expose Module B
if (typeof window !== 'undefined') {
  window.classifyLedgerNewsNeeds    = classifyLedgerNewsNeeds;
  window.buildEvidenceLedNewsQueries= buildEvidenceLedNewsQueries;
  window.classifyMatchStrength      = classifyMatchStrength;
  window.buildNewsQueryReasons      = buildNewsQueryReasons;
  window.scoreNewsItemAgainstLedger = scoreNewsItemAgainstLedger;
  window.rankNewsForLedgerContext   = rankNewsForLedgerContext;
  window.attachNewsIntentToPack     = attachNewsIntentToPack;
  window.NEWS_ROUTER_TRIGGERS       = NEWS_ROUTER_TRIGGERS;
}

// ─── MODULE C — NEWS SOURCE STRATEGY (extends News Doctor) ────────────

// Extended failure classes for v3.23
const NEWS_FAILURE_CLASSES_V323 = {
  GOOGLE_NEWS_BLOCKED_OR_PROXY_FAILED: 'GOOGLE_NEWS_BLOCKED_OR_PROXY_FAILED',
  GDELT_QUERY_TOO_LONG:                'GDELT_QUERY_TOO_LONG',
  RSS_FEED_CHANGED:                    'RSS_FEED_CHANGED',
  PROVIDER_UNRELIABLE_REPEATED_FAILURE:'PROVIDER_UNRELIABLE_REPEATED_FAILURE'
};

// Per-provider recommended replacement route
function getProviderRecommendedRoute(provName, failureClass, hist) {
  const n = (provName || '').toLowerCase();
  const f = failureClass || '';
  const histRec = hist && hist[provName];
  const consecFail = histRec ? histRec.consecutive_failures : 0;
  const reliability = histRec ? histRec.reliability_score : 100;

  // Repeatedly unreliable
  if (consecFail >= 3 || reliability < 30) {
    return 'Provider is unreliable. Recommend disabling or replacing with an alternate RSS. Add to News Doctor suppression list.';
  }
  if (/gdelt/.test(n)) {
    if (f === 'INVALID_JSON' || f === 'GDELT_QUERY_TOO_LONG') {
      return 'Encode query string strictly. Reduce max records to 10. Capture 120 chars of raw response for diagnosis. Use direct GDELT if CORS permits. Consider shorter queries (4-6 words max).';
    }
    return 'GDELT is a no-key fallback — retry later. If repeated, reduce query length and encode URI components strictly.';
  }
  if (/google.*news|googlenews/.test(n) || f === 'GOOGLE_NEWS_BLOCKED_OR_PROXY_FAILED') {
    return 'Google News RSS requires a backend proxy for reliable production use. In-browser CORS requests will fail. Recommend: NewsAPI, CryptoPanic, or direct RSS from crypto publishers.';
  }
  if (/cointelegraph|ctmain|defiant|decrypt|coindesk|newsbtc|bitcoinist/.test(n)) {
    if (f === 'CORS_PROXY_EMPTY' || f === 'EMPTY_FEED' || f === 'RSS_FEED_CHANGED') {
      return 'RSS feed empty or changed. Try: (1) direct fetch if CORS allows, (2) allorigins raw endpoint, (3) codetabs, (4) rss2json compatible fallback. If all fail, disable until source stabilizes.';
    }
    if (f === 'CORS_PROXY_BLOCKED') {
      return 'CORS proxy is blocking this source. Try a different proxy (allorigins, codetabs, thingproxy) or direct fetch. If blocked consistently, disable and use a direct RSS reader.';
    }
    return 'Try alternate proxy cascade: direct → allorigins → codetabs → thingproxy. If all fail, disable until source returns valid XML.';
  }
  if (/cryptopanic|newsapi/.test(n)) {
    return f === 'NO_KEY'
      ? 'API key missing. Add key in Intel Settings. This provider is optional — GDELT covers without a key.'
      : 'Verify API key and rate limit. Check provider status page.';
  }
  return 'Check provider status. Try alternate proxy route or direct fetch. If repeatedly failing, disable for this session.';
}

// Build the full News Source Strategy report
function buildNewsSourceStrategy() {
  const diag = state.newsDiagnostics || null;
  const hist  = typeof getNewsDoctorHistory === 'function' ? getNewsDoctorHistory() : {};
  const health = typeof getSourceHealth === 'function' ? getSourceHealth() : {};
  const now = new Date().toISOString();
  const providers = {};

  // v3.26-hotfix9: read authoritative news_health from the pack (computed
  // by attachNewsHealthToPack). This is the same domain-aware truth model
  // the public reports use. The legacy `getSourceHealth()` returns the older
  // degraded/partial flags only — we layer the new fields on top.
  const pack       = state.pack || {};
  const newsHealth = pack.news_health || null;
  const newsMode   = newsHealth ? newsHealth.newsMode : 'LEDGER_ONLY';
  const unique_domain_count = newsHealth ? (newsHealth.unique_domain_count || 0) : 0;
  const source_group_count  = newsHealth ? (newsHealth.source_group_count  || 0) : (health.source_group_count || 0);
  const headline_count      = newsHealth ? (newsHealth.headline_count      || 0) : (health.headline_count      || 0);
  const public_usable       = newsHealth ? !!newsHealth.public_usable       : false;
  const evidence_led_usable = newsHealth ? !!newsHealth.evidence_led_usable : false;
  const narrative_usable    = newsHealth ? !!newsHealth.narrative_usable    : false;
  // v3.31-hotfix1k: canonical governor-aware terminology
  const public_news_usable    = newsHealth ? !!newsHealth.public_news_usable    : false;
  const public_sources_usable = newsHealth ? !!newsHealth.public_sources_usable : false;

  // Build working/failed publisher rosters from the provider diagnostic table
  const working_publishers = [];
  const failed_publishers  = [];
  const active_domains     = new Set();

  if (diag && diag.providers) {
    Object.keys(diag.providers).forEach(p => {
      const prov = diag.providers[p];
      const histRec = hist[p] || {};
      providers[p] = {
        provider: p,
        overall_status:      prov.overall_status || 'UNKNOWN',
        failure_class:       prov.failure_class  || null,
        last_error_excerpt:  prov.last_error_excerpt || '',
        consecutive_failures: histRec.consecutive_failures || 0,
        reliability_score:   histRec.reliability_score   != null ? histRec.reliability_score : 100,
        suggested_fix:       prov.suggested_fix || '',
        recommended_route:   getProviderRecommendedRoute(p, prov.failure_class, hist)
      };
      // Roster classification
      if (prov.overall_status === 'CONTENT_OK' || prov.overall_status === 'OK') {
        working_publishers.push(p);
      } else if (prov.overall_status === 'TRANSPORT_FAILED' || prov.overall_status === 'FAILED') {
        failed_publishers.push(p);
      }
    });
  }

  // Extract active domains from the actual fetched news items
  const newsItems = (pack.news_intel && pack.news_intel.items) || [];
  newsItems.forEach(it => {
    if (it.domain) active_domains.add(it.domain.toLowerCase().replace(/^www\./, ''));
    else if (it.url) {
      try {
        const u = new URL(it.url);
        active_domains.add(u.hostname.toLowerCase().replace(/^www\./, ''));
      } catch (_) {}
    }
  });

  // v3.26-hotfix9: derive overall_health from newsMode (not just legacy flags)
  // Maps the new truth model to a short label for the diagnostic summary.
  let overall_health;
  switch (newsMode) {
    case 'EVIDENCE_LED_CONTEXT': overall_health = 'EVIDENCE-LED'; break;
    case 'HEALTHY_CONTEXT':      overall_health = 'HEALTHY';      break;
    case 'PARTIAL_CONTEXT':      overall_health = 'PARTIAL';      break;
    case 'LEDGER_ONLY':          overall_health = 'LEDGER-ONLY';  break;
    default:                      overall_health = health.degraded ? 'DEGRADED' : 'OK';
  }

  return {
    generated_at: now,
    overall_health,
    newsMode,
    degraded: health.degraded || false,
    partial_coverage: health.partial_coverage || false,
    public_usable,
    narrative_usable,
    evidence_led_usable,
    // v3.31-hotfix1k: canonical governor-aware terminology (surfaced in report)
    public_news_usable,
    public_sources_usable,
    headline_count,
    unique_domain_count,
    source_group_count,
    active_domains: Array.from(active_domains).sort(),
    working_publishers: working_publishers.sort(),
    failed_publishers: failed_publishers.sort(),
    providers,
    // v16.9: derived from what is ACTUALLY wrong, not a fixed block. This list
    // used to print the same four lines in every report — including advice about
    // providers that were at 100% reliability, and a mild "retry later" for
    // GDELT on its twenty-second consecutive failure. Advice that never changes
    // is advice nobody reads.
    recommendations: _newsRecommendations(providers)
  };
}

// One line per provider that needs something done about it, escalating with the
// failure count, plus a closing line about the ones that are fine.
function _newsRecommendations(providers) {
  const out = [], healthy = [];
  Object.keys(providers || {}).forEach(k => {
    const pv = providers[k] || {};
    const name = pv.provider || k;
    const fails = n(pv.consecutive_failures);
    const rel = n(pv.reliability_score);
    const st = pv.overall_status || '';
    const ok = /CONTENT_OK/.test(st) && fails === 0;
    if (ok) { healthy.push(name); return; }

    // v16.10: never contacted, so there is nothing to diagnose from this run.
    // Report the standing record if it is bad, and otherwise say nothing —
    // advice about a fetch that did not happen is noise.
    if (/NOT_ATTEMPTED|DISABLED_SESSION/.test(st)) {
      if (fails >= SUPPRESS_AFTER_FAILS)
        out.push(name + ': not contacted this run, and carrying ' + fails + ' consecutive failures from before. ' +
                 'Suppress it or replace the feed — it has not worked in ' + fails + ' attempts.');
      return;
    }

    if (fails >= 10) {
      out.push(name + ': ' + fails + ' consecutive failures at ' + rel + '% reliability. This is not a blip — ' +
               'suppress it or replace the feed. Every report until then carries a line that says nothing new.');
    } else if (fails >= 3) {
      out.push(name + ': failing ' + fails + ' runs in a row. Switch route or drop it from the rotation before it ' +
               'starts shaping the headline pool by absence.');
    } else if (/EMPTY/.test(pv.failure_class || '') || /EMPTY/.test(pv.overall_status || '')) {
      out.push(name + ': responding but returning nothing. Quiet source or broken query — worth one check, not a fix.');
    } else if (fails > 0) {
      out.push(name + ': ' + fails + ' recent failure' + (fails === 1 ? '' : 's') + '. Watch it; no action yet.');
    }
  });
  if (healthy.length)
    out.push(healthy.join(', ') + (healthy.length === 1 ? ' is' : ' are') + ' healthy — no action needed.');
  if (!out.length) out.push('Every configured source responded cleanly. Nothing to do.');
  return out;
}

function _newsSourceStrategyToText(strategy) {
  if (!strategy) return '';
  const lines = ['NEWS SOURCE STRATEGY REPORT', 'Generated: ' + strategy.generated_at, ''];

  // v3.31-hotfix1m: Overall line driven by canonical governor fields (not legacy summary)
  // priority: public_news_usable (cleared) > evidence_led_usable (internal) > ledger-only
  let overallLine;
  if (strategy.public_news_usable) {
    overallLine = 'PUBLIC NEWS CLEARED — governor-approved headlines available';
  } else if (strategy.evidence_led_usable) {
    overallLine = 'INTERNAL EVIDENCE-LED CONTEXT USABLE — public news not cleared';
  } else {
    overallLine = 'LEDGER-ONLY — no usable news context';
  }
  lines.push('Overall: ' + overallLine);
  lines.push('newsMode: ' + (strategy.newsMode || '—'));
  lines.push('Headlines: ' + strategy.headline_count +
             ' from ' + strategy.unique_domain_count + ' unique domains / ' +
             strategy.source_group_count + ' transport groups');
  // v3.31-hotfix1m: rename public_usable → legacy_public_usable_deprecated (avoids visible contradiction)
  // Internal compatibility field (.public_usable) preserved on object for legacy test compat.
  lines.push('legacy_public_usable_deprecated: ' + (strategy.public_usable ? 'yes' : 'no') +
             '  ·  evidence_led_usable: ' + (strategy.evidence_led_usable ? 'yes' : 'no') +
             '  ·  narrative_usable: ' + (strategy.narrative_usable ? 'yes' : 'no'));
  // v3.31-hotfix1k: canonical governor truth (resolves Section 02 vs Section 06 contradiction)
  lines.push('public_news_usable: ' + (strategy.public_news_usable ? 'yes' : 'no') +
             '  ·  public_sources_usable: ' + (strategy.public_sources_usable ? 'yes' : 'no') +
             '  ·  (governor canonical)');
  if (strategy.active_domains && strategy.active_domains.length) {
    lines.push('Active domains: ' + strategy.active_domains.join(', '));
  }
  if (strategy.working_publishers && strategy.working_publishers.length) {
    lines.push('Working publishers: ' + strategy.working_publishers.join(', '));
  }
  if (strategy.failed_publishers && strategy.failed_publishers.length) {
    lines.push('Failed publishers: ' + strategy.failed_publishers.join(', '));
  }
  lines.push('');
  // v16.9: a provider that is working gets one line. It used to get the full
  // five-line block including "Suggested fix" and a "Recommended route" telling
  // the operator to try an alternate proxy — printed against sources sitting at
  // 100% reliability with zero failures. Repair instructions for healthy
  // equipment are how a diagnostics page teaches people to stop reading it.
  //
  // v16.10: the split keyed on CONTENT_OK alone, so two things landed in the
  // sick bucket that had nothing wrong with them. A provider at TRANSPORT_OK_EMPTY
  // with 0 failures and 100% reliability answered fine and had nothing to say —
  // it got a full repair block telling the operator to try an alternate proxy.
  // A provider at NOT_ATTEMPTED was never contacted at all, and got told
  // "Unclassified failure. Inspect raw error and route logs" for a fetch that
  // never happened. Neither is broken. They get their own honest buckets.
  const healthy = [], empty = [], skipped = [], sick = [];
  Object.keys(strategy.providers || {}).forEach(k => {
    const pv = strategy.providers[k];
    const st = pv.overall_status || '';
    const fails = n(pv.consecutive_failures);
    if (/CONTENT_OK/.test(st) && fails === 0)           healthy.push(pv);
    else if (/TRANSPORT_OK_EMPTY/.test(st) && fails === 0) empty.push(pv);
    else if (/NOT_ATTEMPTED|DISABLED_SESSION/.test(st))  skipped.push(pv);
    else                                                  sick.push(pv);
  });
  const sup = (state.newsSuppression || {});
  const supNames = Object.keys(sup).filter(k => sup[k] && sup[k].suppressed);
  if (supNames.length) {
    lines.push('SUPPRESSED THIS RUN');
    supNames.forEach(k => {
      const x = sup[k];
      lines.push('  \u2022 ' + k + ' \u2014 ' + x.reason + '. Not fetched. Next probe in ' + x.nextRetryMin + ' min.');
    });
    lines.push('  Suppression requires ' + MIN_HEALTHY_TO_SUPPRESS + '+ healthy sources to remain; if that stops being ' +
               'true, these come straight back into rotation.');
    lines.push('');
  }
  // A source that qualified for suppression but was KEPT because dropping it
  // would have left too little coverage. Worth saying out loud — it is the guard
  // doing its job, and silence would look like the rule failing.
  const held = Object.keys(sup).filter(k => sup[k] && !sup[k].suppressed && !sup[k].probe &&
                                            n(sup[k].fails) >= SUPPRESS_AFTER_FAILS);
  if (held.length) {
    lines.push('KEPT DESPITE FAILING');
    held.forEach(k => lines.push('  \u2022 ' + k + ' \u2014 ' + sup[k].reason + '.'));
    lines.push('');
  }
  if (healthy.length) {
    lines.push('HEALTHY');
    healthy.forEach(pv => lines.push('  \u2022 ' + pv.provider + ' \u2014 ' + pv.overall_status +
      ', ' + pv.reliability_score + '% reliability, no consecutive failures.'));
    lines.push('');
  }
  if (empty.length) {
    lines.push('RESPONDING, NOTHING TO REPORT');
    empty.forEach(pv => lines.push('  \u2022 ' + pv.provider + ' \u2014 answered cleanly at ' +
      pv.reliability_score + '% reliability and returned no items. Quiet feed, not a fault.'));
    lines.push('  Nothing to repair here. If a source stays empty for days, check the query \u2014 not the route.');
    lines.push('');
  }
  if (skipped.length) {
    lines.push('NOT CONTACTED THIS RUN');
    skipped.forEach(pv => {
      const f = n(pv.consecutive_failures);
      const why = /DISABLED_SESSION/.test(pv.overall_status || '')
        ? 'disabled for this session'
        : (sup[pv.provider] && sup[pv.provider].suppressed)
          ? 'held back by suppression \u2014 ' + sup[pv.provider].reason
          : 'the run ended before this tier was reached (news fetch ceiling, or the scan aborted)';
      lines.push('  \u2022 ' + pv.provider + ' \u2014 ' + why + '. No fetch was attempted, so nothing about ' +
        'this run tells you whether it works.' +
        (f >= SUPPRESS_AFTER_FAILS ? ' Standing record: ' + f + ' consecutive failures before this run.' : ''));
    });
    lines.push('');
  }
  if (sick.length) {
    lines.push('NEEDS ATTENTION');
    lines.push('');
    sick.forEach(pv => {
      const fails = n(pv.consecutive_failures);
      lines.push('PROVIDER: ' + pv.provider);
      lines.push('  Status:              ' + pv.overall_status);
      lines.push('  Failure class:       ' + (pv.failure_class || '—'));
      lines.push('  Consecutive fails:   ' + fails +
        (fails >= 10 ? '   \u2190 sustained; this is a dead source, not a flaky one' : ''));
      lines.push('  Reliability:         ' + pv.reliability_score + '%');
      if (pv.last_error_excerpt) lines.push('  Last error:          ' + pv.last_error_excerpt);
      if (pv.suggested_fix)     lines.push('  Suggested fix:       ' + pv.suggested_fix);
      if (pv.recommended_route) lines.push('  Recommended route:   ' + pv.recommended_route);
      lines.push('');
    });
  }
  lines.push('WHAT TO DO');
  (strategy.recommendations || []).forEach(r => lines.push('\u2022 ' + r));
  return lines.join('\n');
}

function exportNewsSourceStrategyTxt() {
  const strategy = buildNewsSourceStrategy();
  state.newsSourceStrategy = _newsSourceStrategyToText(strategy);
  const base = typeof shadowFileBase === 'function' ? shadowFileBase('NewsSourceStrategy') : 'ShadowWatch_NewsSourceStrategy';
  if (typeof downloadTextFile === 'function') {
    downloadTextFile(base + '.txt', state.newsSourceStrategy);
  }
}

