  const titleColor = strategy.overall_health === 'OK' ? 'var(--lime)' : '#ffb347';
  let html = '<div class="news-source-status-title" style="color:' + titleColor + '">NEWS SOURCE STRATEGY — ' + strategy.overall_health + '</div>';

