function buildBundle(p, seal) {
  return JSON.stringify({
    discovery_inbox: state.discoveryInbox || [],
    discovery_history: (state.discoveryHistory || []).slice(-20),
    discovery_settings: state.discoverySettings || null,
    forensic_doctrine: {
      operator: 'XRP Man / RedCandleKiller',
      mission: 'Daily XRPL forensic report generation',
      public_rule: 'Ledger facts are evidence. Patterns are analysis. Motives are thesis unless verified.',
      prohibited_public_claims: ['Unsupported causation', 'Unverified Ripple/bank motive', 'Hashtags', 'Comedy node']
    }
  }, null, 2);
}

function buildMasterPaste(p, report, bundle, seal) {
  const context = $('inWorldContext')?.value?.trim() || 'none supplied';
  const sealBlock = seal ? JSON.stringify(seal, null, 2) : 'Seal pending';
  const errors = $('errorLog')?.textContent || '';
  const tone = $('toneBox')?.textContent || '';
  const prayer = $('prayerBox')?.textContent || '';
  const mainReport = (function(){ try { return buildXRPMainReport(p); } catch { return 'main report unavailable'; }})();
  return `=== XRPMAN SHADOW WATCH // MASTER PACKAGE ${APP_VERSION} ===
INSTRUCTION_FOR_CHATGPT: Build the final Shadow Watch report from the evidence below. Treat ledger data as scanned evidence. Treat news/macro as operator-supplied context unless independently verified. Failed/invalid wallets are internal only.

=== XRP MAIN REPORT (consolidated, human-readable) ===
${mainReport}

=== EVIDENCE CAPSULE SEAL ===
${sealBlock}

=== SCAN SUMMARY ===
DATE=${p.date}
AS_OF_UTC=${p.data_as_of_utc}
SCAN_TARGET=${p.scan_target}
TX_WINDOW=${p.tx_window?.label || 'LAST 24H'}
PRICE=$${p.xrp_price} (${pct(p.xrp_delta_24h_pct)} 24h)
VOLUME_USD=${p.xrp_volume_24h}
WALLETS_SCORED=${p.wallets_checked}/${p.watchlist_total}
SHADOW_VOLUME_XRP=${p.shadow_volume_xrp}
NET_WATCHLIST_DELTA_XRP=${p.total_balance_delta_xrp}
LARGE_TRANSFER_COUNT=${(p.large_transfers || []).length}
NEXT_HOP_COUNT=${(p.receiver_followthrough || []).length}

=== EVIDENCE QUALITY ===
GRADE=${p.evidence_quality?.grade} ${p.evidence_quality?.score}/100
INCLUDED=${(p.evidence_quality?.included_evidence_sources || []).join(' | ') || 'none'}
MISSING=${(p.evidence_quality?.missing_or_failed_evidence || []).join(' | ') || 'none'}

=== TOP SIGNALS ===
${(p.top_signals || []).join('\n')}

=== FORENSIC INTELLIGENCE BRIEF ===
${state.intelBrief || 'No intel brief.'}

=== RISK SCORE ===
${state.riskScore ? JSON.stringify(state.riskScore, null, 2) : 'No risk score.'}

=== NEWS / MACRO CONTEXT ===
${state.newsIntel ? JSON.stringify(state.newsIntel, null, 2) : 'No news intel.'}

=== OPERATOR CLAIM LANE ===
${context}

=== CLEAN 4K PUBLIC REPORT ===
${report}

=== DAILY TONE ===
${tone}

=== PRAYER / SCRIPTURE ===
${prayer}

=== FULL INTERNAL EVIDENCE BUNDLE ===
${bundle}

=== DEBUG / ERROR LOG ===
${errors}

=== END MASTER PACKAGE ===`;
}

