function renderHudFromPack(p) {
  const q = p.evidence_quality || {}, risk = p.risk_score || {};
  const chk = p.wallets_checked || 0, total = p.watchlist_total || WATCHLIST.length;
  setText('hudChecked', chk); setText('hudTotal', total);
  const wPct = total > 0 ? chk / total * 100 : 0;
  setBar('hudWalletBar', wPct, wPct > 80 ? 'ok' : wPct > 40 ? 'warn' : 'bad');
  const d = n(p.total_balance_delta_xrp);
  setText('hudNetDelta', d ? (d > 0 ? '+' : '') + fmt(d, 0) + ' XRP' : '0 XRP');
  setText('hudDeltaBadge', d > 0 ? 'INFLOW' : d < 0 ? 'OUTFLOW' : 'FLAT');
  setBar('hudDeltaBar', Math.min(100, Math.abs(d) / 100000));
  const lc = (p.large_transfers || []).length;
  setText('hudLargeCount', lc);
  setText('hudShadowVol', p.shadow_volume_xrp > 0 ? fmt(p.shadow_volume_xrp, 0) : '—');
  const top = $('hudTopTransfer');
  if (top) { top.textContent = lc > 0 ? lc + ' FLAGGED' : 'NO TRANSFER'; top.className = 'chip ' + (lc > 0 ? 'warn' : ''); }
  const rs = n(risk.score);
  setText('hudRiskScore', rs + '/100');
  setText('hudRiskBadge', riskBand(rs).split(' / ')[0]);
  setBar('hudRiskBar', rs, rs >= 75 ? 'bad' : rs >= 50 ? 'warn' : '');
  const rb = $('hudRiskBadge');
  if (rb) rb.className = 'panel-badge ' + (rs >= 75 ? 'bad' : rs >= 50 ? 'warn' : 'ok');
  setText('hudEvidenceScore', q.score || 0);
  setText('hudGrade', q.grade || '—');
  setBar('hudEvidenceBar', n(q.score));
  const cl = (state.clusters || [])[0];
  if (cl) {
    setText('hudClusterType', cl.type.replace(/_/g, ' '));
    setText('hudClusterReason', cl.reason);
    setText('hudClusterBadge', cl.confidence);
    const cb = $('hudClusterBadge');
    if (cb) cb.className = 'panel-badge ' + (cl.confidence === 'HIGH' ? 'warn' : 'ok');
  }
  renderMacroLanes(macroLinkMatrix(p));
  const prof = state.walletProfiles || [];
  const al = $('hudArchList');
  if (al) {
    al.innerHTML = prof.slice(0, 8).map(x =>
      `<div style="margin-bottom:4px;border-bottom:1px solid rgba(0,255,0,0.1);padding-bottom:3px">
        <span style="color:var(--lime);font-weight:700">${x.label}</span>
        <span style="color:var(--muted);font-size:9px"> ${x.archetype}</span>
      </div>`).join('') || 'no profiles';
    const ab = $('hudArchBadge');
    if (ab) { ab.textContent = prof.length + ' PROFILED'; ab.className = 'panel-badge ok'; }
  }
  setText('statWallets', total); setText('statChecked', chk);
  setText('statDelta', fmt(d, 0));
  setText('statLarge', lc); setText('statShadow', fmt(p.shadow_volume_xrp, 0));
  setText('statHops', (p.receiver_followthrough || []).length);
  setText('statDust', (p.fragmentation_flags || []).length);

  // v3.4: Floor wall HUD tile
  const fa = p.floor_analysis;
  const fb = $('hudFloorBadge'), fr = $('hudFloorRange'), fd = $('hudFloorDepth'), frRatio = $('hudFloorRatio');
  if (fa && fa.floor_walls?.length) {
    const top = fa.floor_walls[0];
    if (fb) {
      const inZone = top.in_floor_zone;
      fb.textContent = inZone ? 'IN ZONE' : 'OUT OF ZONE';
      fb.className = 'panel-badge ' + (inZone ? 'ok' : 'warn');
    }
    if (fr) fr.textContent = top.range;
    if (fd) fd.textContent = fmt(top.buy_xrp, 0) + ' XRP buy depth · ' + top.buy_contributors.length + ' wallet(s)';
    if (frRatio) {
      const r = fa.floor_zone_sell_xrp > 0 ? (fa.floor_zone_buy_xrp / fa.floor_zone_sell_xrp) : null;
      frRatio.textContent = 'Zone B/S ratio: ' + (r === null ? '∞ (no sells)' : r.toFixed(2)) +
        (r !== null && r > 1.5 ? ' · floor holding' : r !== null && r < 0.67 ? ' · floor weak' : '');
    }
  } else {
    if (fb) { fb.textContent = 'NO OFFERS'; fb.className = 'panel-badge'; }
    if (fr) fr.textContent = '—';
    if (fd) fd.textContent = (p.offers && p.offers.length === 0) ? 'no active offers on watchlist' : 'no offer scan yet';
    if (frRatio) frRatio.textContent = 'B/S ratio: —';
  }

  // v3.4: Forensic Memory tile now reflects black box size
  const h = state.blackbox || [];
  const mb = $('hudMemoryBadge'), ml = $('hudMemoryLine');
  if (h.length) {
    if (mb) { mb.textContent = h.length + '/' + BLACKBOX_MAX_SNAPSHOTS; mb.className = 'panel-badge ' + (h.length >= COORD_MIN_SNAPSHOTS ? 'ok' : 'warn'); }
    if (ml) {
      const first = new Date(h[0].ts).toLocaleDateString();
      const last = new Date(h[h.length - 1].ts).toLocaleDateString();
      ml.textContent = h.length === 1 ? 'first snapshot ' + last : first + ' → ' + last;
    }
  } else {
    if (mb) { mb.textContent = '—'; mb.className = 'panel-badge'; }
    if (ml) ml.textContent = 'no forensic memory loaded';
  }
}

function renderWallets() {
  const tb = document.querySelector('#walletTable tbody'); if (!tb) return;
  tb.innerHTML = '';
  for (const w of state.wallets) {
    const dlt = w.delta_xrp === null ? 'baseline' : ((w.delta_xrp > 0 ? '+' : '') + fmt(w.delta_xrp, 2));
    const cls = w.status !== 'CHECKED' ? 't-warn' : (w.delta_xrp > 0 ? 't-lime' : w.delta_xrp < 0 ? 't-bad' : '');
    // v3.10: tier-based row styling
    const grp = getWalletGroup(w.label);
    let rowCls = 'wallet-row-' + grp;
    let linkMarker = '';
    // Custodial multi-sig splits get a chain-link marker
    if (grp === 'msig_cluster') linkMarker = ' <span class="msig-link" title="Linked multi-sig cluster">⛓</span>';
    const tr = document.createElement('tr');
    tr.className = rowCls;
    tr.innerHTML = `<td>${w.label}${linkMarker}</td><td style="font-family:monospace;font-size:10px">${w.address}</td><td>${w.cat}</td><td>${fmt(w.balance_xrp, 2)}</td><td>${w.prev_balance_xrp === null ? '—' : fmt(w.prev_balance_xrp, 2)}</td><td class="${cls}">${dlt}</td><td class="${w.status === 'CHECKED' ? 't-ok' : 't-warn'}">${w.status}${w.error ? ' — ' + w.error : ''}</td>`;
    tb.appendChild(tr);
  }
}

// ── CLIPBOARD + DOWNLOAD ──────────────────────────────────────
function copySafe(text, label) {
  if (!text || text.startsWith('Run scan first')) { log('Nothing to copy: ' + label); return; }
  if (navigator.clipboard?.writeText) {
    navigator.clipboard.writeText(text).then(() => log('Copied: ' + label)).catch(() => fallbackCopy(text, label));
  } else fallbackCopy(text, label);
}
function fallbackCopy(text, label) {
  const ta = document.createElement('textarea');
  ta.value = text; ta.style.cssText = 'position:fixed;left:-9999px;opacity:0';
  document.body.appendChild(ta); ta.select(); ta.setSelectionRange(0, text.length);
  try { document.execCommand('copy'); log('Copied (fallback): ' + label); }
  catch { log('COPY BLOCKED — select text manually: ' + label); }
  ta.remove();
}
function dl(name, text, mime = 'text/plain') {
  const a = document.createElement('a'), b = new Blob([text], { type: mime });
  a.href = URL.createObjectURL(b); a.download = name; a.click(); URL.revokeObjectURL(a.href);
}
const todaySlug = () => today().replace(/-/g, '');

