// ── Tab switching ─────────────────────────────────────────────
function installDevTabs() {
  const tabs = document.querySelectorAll('#devTabs .dev-tab');
  if (!tabs.length) return;
  tabs.forEach(t => {
    t.addEventListener('click', () => {
      const target = t.dataset.tab;
      tabs.forEach(x => x.classList.toggle('active', x === t));
      document.querySelectorAll('.dev-page').forEach(p => {
        p.classList.toggle('active', p.dataset.page === target);
      });
      // Scroll the dev drawer top into view on mobile so the tab is visible
      try { $('devDrawer')?.scrollIntoView({ behavior: 'smooth', block: 'start' }); } catch {}
    });
  });
}

// ── Filename helpers ──────────────────────────────────────────
function shadowFileBase(kind) {
  const reportId = (state.seal && state.seal.report_id) || $('sealReportId')?.textContent || 'noid';
  const safeReportId = String(reportId).replace(/[^A-Za-z0-9_-]/g, '_').slice(0, 32);
  const date = (state.pack && state.pack.date) || today();
  const safeKind = String(kind || 'file').replace(/[^A-Za-z0-9_-]/g, '_');
  return 'ShadowWatch_' + safeKind + '_' + safeReportId + '_' + date;
}

function downloadTextFile(filename, text) {
  try {
    const blob = new Blob([text == null ? '' : String(text)], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    return true;
  } catch (e) {
    elog('downloadTextFile', e);
    return false;
  }
}

function downloadJsonFile(filename, obj) {
  try {
    const text = (typeof obj === 'string') ? obj : JSON.stringify(obj, null, 2);
    return downloadTextFile(filename, text);
  } catch (e) {
    elog('downloadJsonFile', e);
    return false;
  }
}

// Expose helpers on window for external use / smoke tests
if (typeof window !== 'undefined') {
  window.shadowFileBase = shadowFileBase;
  window.downloadTextFile = downloadTextFile;
  window.downloadJsonFile = downloadJsonFile;
}

// ── Per-kind file source resolvers ────────────────────────────
// Each kind returns { text, ext, ok } — ok=false if source is empty/missing
function _resolveReportSource(kind) {
  const txt = (id) => $(id)?.textContent || '';
  switch (kind) {
    case 'news-router': {
      const router = state.pack && state.pack.news_intelligence_router;
      if (!router) return { text: '', ext: 'txt', ok: false };
      const txt = _newsRouterToText(router);
      return { text: txt, ext: 'txt', ok: !!(txt && txt.length > 20) };
    }
    case 'morning-story': {
      const ms = state.morningStoryReport || '';
      return { text: ms, ext: 'txt', ok: !!(ms && ms.length > 50) };
    }
    case 'news-source-strategy': {
      if (!state.newsSourceStrategy && typeof buildNewsSourceStrategy === 'function') {
        try { state.newsSourceStrategy = _newsSourceStrategyToText(buildNewsSourceStrategy()); } catch (_) {}
      }
      const ns = state.newsSourceStrategy || '';
      return { text: ns, ext: 'txt', ok: !!(ns && ns.length > 20) };
    }
    // v3.27: Auto Wallet Finder exports
    case 'suggested-wallets-txt': {
      if (typeof window.AUTO_WALLET_FINDER === 'undefined') return { text: '', ext: 'txt', ok: false };
      try {
        const text = window.AUTO_WALLET_FINDER.exportSuggestedWalletsTXT(state.pack || {});
        return { text, ext: 'txt', ok: !!(text && text.length > 100) };
      } catch (_) { return { text: '', ext: 'txt', ok: false }; }
    }
    case 'suggested-wallets-json': {
      if (typeof window.AUTO_WALLET_FINDER === 'undefined') return { text: '', ext: 'json', ok: false };
      try {
        const obj = window.AUTO_WALLET_FINDER.exportSuggestedWalletsJSON(state.pack || {});
        return { text: JSON.stringify(obj, null, 2), ext: 'json', ok: true };
      } catch (_) { return { text: '', ext: 'json', ok: false }; }
    }
    // v3.29: Richlist ingest exports
    case 'richlist-suggestions': {
      if (typeof window.RICHLIST_INGEST === 'undefined') return { text: '', ext: 'txt', ok: false };
      try {
        const text = window.RICHLIST_INGEST.exportRichlistWatchSuggestionsTXT();
        return { text, ext: 'txt', ok: !!(text && text.length > 50) };
      } catch (_) { return { text: '', ext: 'txt', ok: false }; }
    }
    case 'richlist-json': {
      if (typeof window.RICHLIST_INGEST === 'undefined') return { text: '', ext: 'json', ok: false };
      try {
        const obj = window.RICHLIST_INGEST.exportRichlistUniverseJSON();
        return { text: JSON.stringify(obj, null, 2), ext: 'json', ok: true };
      } catch (_) { return { text: '', ext: 'json', ok: false }; }
    }
    // v3.29-hotfix1: richlist ingest metrics for Total Debug
    case 'richlist-metrics': {
      try {
        const meta   = (typeof state !== 'undefined') ? (state.richlistMeta || null) : null;
        const universe = (typeof state !== 'undefined') ? (state.richlistUniverse || null) : null;
        const inbox  = (typeof state !== 'undefined') ? (state.discoveryInbox || []) : [];
        const watched = (typeof KNOWN !== 'undefined') ? KNOWN : {};
        const lines = ['RICHLIST INGEST METRICS', 'Generated: ' + new Date().toISOString(), ''];
        if (!meta && !universe) {
          lines.push('Richlist not imported this session.');
          lines.push('');
          lines.push('To import: Pattern Memory screen → RICHLIST INGEST panel → Upload CSV → Import / Dedupe.');
        } else {
          const m = meta || {};
          const src = m.source || 'unknown';
          lines.push('imported:                      true');
          lines.push('source:                        ' + src);
          lines.push('imported_at:                   ' + (m.imported_at || '—'));
          lines.push('raw_rows:                      ' + (m.raw_rows || 0).toLocaleString());
          lines.push('unique_addresses:              ' + (m.unique_addresses || Object.keys(universe || {}).length).toLocaleString());
          lines.push('seed_threshold_xrp:            ' + (m.seed_threshold_xrp ? (m.seed_threshold_xrp/1_000_000).toFixed(0) + 'M XRP min' : '—'));
          lines.push('duplicate_rows_removed:        ' + (m.duplicate_rows_removed || 0).toLocaleString());
          lines.push('invalid_addresses_removed:     ' + (m.invalid_addresses_removed || 0));
          lines.push('identities_resolved:           ' + (m.identities_resolved || 0).toLocaleString());
          lines.push('identities_unknown:            ' + (m.identities_unknown || 0).toLocaleString());
          lines.push('balance_normalization_mode:    ' + (m.balance_normalization_mode || 'auto_detect'));
          lines.push('top_balance_xrp:               ' + Math.round(m.top_balance_xrp || 0).toLocaleString() + ' XRP');
          // Crosscheck metrics
          const inboxAddrs = inbox.map(c => c.address);
          const rl = universe || {};
          const rlMatched = inboxAddrs.filter(a => rl[a]).length;
          const rlWatched = Object.keys(watched).filter(a => rl[a]).length;
          const rlHighBal = Object.values(rl)
            .filter(r => (r.balance_xrp_normalized || 0) >= 1_000_000 && !watched[r.address]).length;
          lines.push('storage_mode:                  ' + (m.raw_rows ? 'in-memory + localStorage_top5k' : 'localStorage_top5k'));
          lines.push('');
          lines.push('CROSSCHECK RESULTS');
          lines.push('richlist_matched_discovered_count:   ' + rlMatched);
          lines.push('richlist_matched_watched_count:      ' + rlWatched);
          lines.push('richlist_new_high_balance_candidates:' + rlHighBal);
          lines.push('');
          lines.push('SAFETY');
          lines.push('identities_are_not_verified_ownership: true');
          lines.push('operator_reviewed_labels_take_priority: true');
          lines.push('no_auto_add: true');
        }
        const text = lines.join('\n');
        return { text, ext: 'txt', ok: true };
      } catch (e) { return { text: 'Richlist metrics error: ' + (e.message || e), ext: 'txt', ok: true }; }
    }
    case 'daily-report': {
      const t = txt('mainReport');
      return { text: t, ext: 'txt', ok: !!(t && !/^Run scan first/i.test(t)) };
    }
    case 'gpt-package': {
      // Prefer masterPaste (one-paste master), fall back to agentBox
      const m = txt('masterPaste');
      if (m && !/^Run scan first/i.test(m)) return { text: m, ext: 'txt', ok: true };
      const a = txt('agentBox');
      return { text: a, ext: 'txt', ok: !!(a && !/^Run scan first/i.test(a)) };
    }
    case 'evidence-bundle': {
      const t = txt('bundleBox');
      return { text: t, ext: 'txt', ok: !!(t && !/^Run scan first/i.test(t)) };
    }
    case 'intel-brief': {
      const t = txt('briefBox');
      return { text: t, ext: 'txt', ok: !!(t && !/^No brief yet/i.test(t)) };
    }
    case 'seal': {
      const seal = state.seal || null;
      if (seal) return { text: JSON.stringify(seal, null, 2), ext: 'txt', ok: true };
      const t = txt('sealJson');
      return { text: t, ext: 'txt', ok: !!(t && !/^Run scan first/i.test(t)) };
    }
    case 'blackbox': {
      const bb = state.blackbox || loadBlackboxHistory();
      if (bb && (Array.isArray(bb) ? bb.length : Object.keys(bb).length)) {
        return { text: JSON.stringify(bb, null, 2), ext: 'json', ok: true };
      }
      return { text: '[]', ext: 'json', ok: false };
    }
    case 'error-log': {
      const t = txt('errorLog');
      return { text: t, ext: 'txt', ok: !!(t && !/^No errors yet/i.test(t)) };
    }
    case 'full-json': {
      if (state.pack) return { text: JSON.stringify(state.pack, null, 2), ext: 'json', ok: true };
      return { text: '{}', ext: 'json', ok: false };
    }
    // ── v3.31 GO 1: Shadow Brain sections ──
    case 'brain-snapshot': {
      try {
        if (typeof window === 'undefined' || !window.SHADOW_BRAIN_CORE) {
          return { text: 'SHADOW BRAIN SNAPSHOT\n\nBrain core not loaded.', ext: 'txt', ok: true };
        }
        var snap = window.SHADOW_BRAIN_CORE.buildBrainSnapshot();
        var lines = ['SHADOW BRAIN SNAPSHOT',
                     'Generated: ' + snap.generated, '',
                     'version:        ' + snap.version,
                     'brain_mode:     ' + snap.brain_mode,
                     'live_execution: false',
                     'auto_add:       false', '',
                     'MODULES'];
        Object.keys(snap.flags).forEach(function(k) {
          lines.push('  ' + k.padEnd(26) + (snap.flags[k] ? 'ENABLED' : 'DISABLED'));
        });
        lines.push('');
        lines.push('STATE');
        if (snap.event_bus)      lines.push('  event_bus.events_logged:    ' + snap.event_bus.events_logged);
        if (snap.journal)        lines.push('  journal.entries:            ' + snap.journal.entries);
        if (snap.decision_trace) lines.push('  decision_trace.entries:     ' + snap.decision_trace.entries);
        if (snap.rule_engine)    lines.push('  rule_engine.built_in_rules: ' + snap.rule_engine.built_in_rules);
        if (snap.bloom_queue)    lines.push('  bloom_queue.size (passive): ' + snap.bloom_queue.size);
        if (snap.balance_memory) lines.push('  balance_memory.wallets:     ' + snap.balance_memory.wallets_tracked);
        lines.push('');
        lines.push('RICHLIST');
        lines.push('  loaded:            ' + snap.richlist.loaded);
        lines.push('  unique_addresses:  ' + snap.richlist.unique_addresses);
        lines.push('  source:            ' + (snap.richlist.source || 'none'));
        return { text: lines.join('\n'), ext: 'txt', ok: true };
      } catch (e) { return { text: 'Brain snapshot error: ' + (e.message || e), ext: 'txt', ok: true }; }
    }
    case 'decision-trace': {
      try {
        if (typeof window === 'undefined' || !window.SHADOW_DECISION_TRACE) {
          return { text: 'SHADOW DECISION TRACE\n\nDecision trace not loaded.', ext: 'txt', ok: true };
        }
        var DT = window.SHADOW_DECISION_TRACE;
        var ex = DT.exportJSON();
        var lines = ['SHADOW DECISION TRACE',
                     'Generated: ' + ex.generated, '',
                     'total_entries: ' + ex.total, '',
                     'BY TYPE'];
        Object.keys(ex.by_type).forEach(function(k) {
          lines.push('  ' + k.padEnd(28) + ex.by_type[k]);
        });
        lines.push('', 'RECENT TRACE (text)', '');
        lines.push(DT.exportText() || '[No decisions recorded this session]');
        return { text: lines.join('\n'), ext: 'txt', ok: true };
      } catch (e) { return { text: 'Decision trace error: ' + (e.message || e), ext: 'txt', ok: true }; }
    }
    case 'bloom-queue': {
      try {
        if (typeof window === 'undefined' || !window.SHADOW_BLOOM_QUEUE) {
          return { text: 'SHADOW BLOOM QUEUE\n\nBloom queue not loaded.', ext: 'txt', ok: true };
        }
        var q = window.SHADOW_BLOOM_QUEUE.exportQueue();
        var lines = ['SHADOW BLOOM QUEUE',
                     'Generated: ' + new Date().toISOString(), '',
                     'SAFETY: passive_mode = true — GO 1 builds + exports, does not auto-scan.',
                     '', JSON.stringify(q, null, 2)];
        return { text: lines.join('\n'), ext: 'txt', ok: true };
      } catch (e) { return { text: 'Bloom queue error: ' + (e.message || e), ext: 'txt', ok: true }; }
    }
    case 'journal-summary': {
      try {
        if (typeof window === 'undefined' || !window.SHADOW_JOURNAL) {
          return { text: 'SHADOW JOURNAL SUMMARY\n\nJournal not loaded.', ext: 'txt', ok: true };
        }
        var jx = window.SHADOW_JOURNAL.exportJSON();
        var lines = ['SHADOW JOURNAL SUMMARY',
                     'Generated: ' + jx.generated, '',
                     'total_entries: ' + jx.total, '',
                     'EVENTS BY TYPE'];
        Object.keys(jx.by_type).forEach(function(k) {
          lines.push('  ' + k.padEnd(40) + jx.by_type[k]);
        });
        lines.push('', 'RECENT 10 ENTRIES (compact)', '');
        jx.recent_100.slice(-10).forEach(function(e) {
          var ts = (e.timestamp || '').slice(11, 19);
          lines.push('  [' + ts + '] ' + e.type +
            (e.address ? ' ' + e.address.slice(0, 12) + '…' : ''));
        });
        return { text: lines.join('\n'), ext: 'txt', ok: true };
      } catch (e) { return { text: 'Journal summary error: ' + (e.message || e), ext: 'txt', ok: true }; }
    }
    case 'builder-recs': {
      try {
        if (typeof window === 'undefined' || !window.SHADOW_BUILDER_RECS) {
          return { text: 'BUILDER HARD-CODE RECOMMENDATIONS\n\nBuilder Recs not loaded.', ext: 'txt', ok: true };
        }
        // Rebuild from current state at export time
        window.SHADOW_BUILDER_RECS.buildFromState();
        var rx = window.SHADOW_BUILDER_RECS.exportJSON();
        var lines = ['BUILDER HARD-CODE RECOMMENDATIONS',
                     'Generated: ' + rx.generated, '',
                     'SAFETY: Recommendations are advisory only. Operator must review before adding to KNOWN.',
                     '', 'count: ' + rx.count, '',
                     rx.note, '',
                     JSON.stringify(rx.recommendations, null, 2)];
        return { text: lines.join('\n'), ext: 'txt', ok: true };
      } catch (e) { return { text: 'Builder recs error: ' + (e.message || e), ext: 'txt', ok: true }; }
    }
    default:
      return { text: '', ext: 'txt', ok: false };
  }
}

function _kindFilenamePart(kind) {
  // Map internal kind to file-name fragment per spec
  const map = {
    'news-router':         'NewsRouter',
    'morning-story':       'MorningStoryReport',
    'news-source-strategy':'NewsSourceStrategy',
    'suggested-wallets-txt':  'SuggestedWallets',
    'suggested-wallets-json': 'SuggestedWallets',
    'richlist-suggestions':   'RichlistSuggestions',
    'richlist-json':          'RichlistUniverse',
    'daily-report':    'DailyReport',
    'gpt-package':     'GPT_Package',
    'evidence-bundle': 'EvidenceBundle',
    'intel-brief':     'IntelBrief',
    'seal':            'Seal',
    'blackbox':        'BlackBox',
    'error-log':       'ErrorLog',
    'full-json':       'FullPack'
  };
  return map[kind] || kind;
}

function exportReportFile(kind) {
  const src = _resolveReportSource(kind);
  if (!src.ok) {
    log('Export "' + kind + '": source empty — run a scan first.');
    return false;
  }
  const base = shadowFileBase(_kindFilenamePart(kind));
  const filename = base + '.' + src.ext;
  const ok = src.ext === 'json'
    ? downloadJsonFile(filename, src.text)
    : downloadTextFile(filename, src.text);
  if (ok) log('Downloaded ' + filename);
  return ok;
}

// ── DOWNLOAD ALL ──────────────────────────────────────────────
async function downloadAllReports() {
  const order = [
    'morning-story', 'daily-report',
    'gpt-package', 'evidence-bundle', 'intel-brief',
    'seal', 'blackbox', 'news-router', 'news-source-strategy',
    'error-log'
  ];
  let downloaded = 0, skipped = 0;
  for (const kind of order) {
    const src = _resolveReportSource(kind);
    if (!src.ok) {
      skipped++;
      log('Skipped ' + kind + ' (empty).');
      continue;
    }
    const ok = exportReportFile(kind);
    if (ok) downloaded++;
    // Small delay so browser doesn't block bulk downloads
    await new Promise(r => setTimeout(r, 280));
  }
  log('DOWNLOAD ALL complete: ' + downloaded + ' file(s) saved, ' + skipped + ' skipped.');
  return { downloaded, skipped };
}

