    var row = _swEl('div', { 'class':'sw-feed-row' });
    var ico = _swEl('div', { 'class':'sw-feed-ico' }, _swIcon(ic[0]));
    ico.querySelector('svg').setAttribute('stroke', ic[1]);
    var body = _swEl('div', { 'class':'sw-feed-body' });
    var t1 = _swEl('div', { 'class':'sw-feed-title' });
    t1.textContent = cls + ' · ' + _swCompact(n(tx.amount)) + ' XRP';
    var t2 = _swEl('div', { 'class':'sw-feed-detail' });
    t2.textContent = (tx.sender_label || _swShort(tx.from) || 'UNKNOWN') + ' → ' + (tx.receiver_label || _swShort(tx.to) || 'UNKNOWN');
