// ═══════════════════════════════════════════════════════════════
//  v3.24 SMOKE TEST — newsAfterLedgerSmokeTest
// ═══════════════════════════════════════════════════════════════
function newsAfterLedgerSmokeTest() {
  const results = []; let pass = 0, fail = 0;
  const check = (name, cond) => {
    if (cond) { pass++; results.push('✓ ' + name); }
    else      { fail++; results.push('✗ ' + name); }
  };

  // 1. Version
  check('APP_VERSION = v3.32a-helper-runtime-proof-lock', APP_VERSION === 'v3.32a-helper-runtime-proof-lock');
  check('hudVersion contains v3.24',
    /v3.32a-helper-runtime-proof-lock/.test(document.getElementById('hudVersion')?.textContent || ''));

  // 2. Core functions exist
  check('fetchEvidenceLedNews is a function',    typeof fetchEvidenceLedNews === 'function');
  check('clearEvidenceNewsCache is a function',  typeof clearEvidenceNewsCache === 'function');
  check('renderNewsRouterPanel is a function',   typeof renderNewsRouterPanel === 'function');
  check('buildMorningStoryText is a function',   typeof buildMorningStoryText === 'function');
  check('classifyLedgerNewsNeeds is a function', typeof classifyLedgerNewsNeeds === 'function');
  check('buildEvidenceLedNewsQueries is a function', typeof buildEvidenceLedNewsQueries === 'function');
  check('_newsRouterToText is a function',       typeof _newsRouterToText === 'function');

  // 3. classifyNewsFailure — field-observed patterns
  check('classifyNewsFailure: "X empty (codetabs)" → CORS_PROXY_EMPTY',
    classifyNewsFailure('CoinTelegraph empty (codetabs)') === 'CORS_PROXY_EMPTY');
  check('classifyNewsFailure: "empty via codetabs" → CORS_PROXY_EMPTY',
    classifyNewsFailure('TheDefiant empty via codetabs') === 'CORS_PROXY_EMPTY');
  check('classifyNewsFailure: "thingproxy Failed to fetch" → CORS_PROXY_BLOCKED',
    classifyNewsFailure('thingproxy Failed to fetch') === 'CORS_PROXY_BLOCKED');
  check('classifyNewsFailure: "Please lim" truncated → RATE_LIMIT_OR_HTML_RESPONSE',
    classifyNewsFailure('Unexpected token \'P\', "Please lim"... is not valid JSON') === 'RATE_LIMIT_OR_HTML_RESPONSE');
  check('classifyNewsFailure: GDELT rate limit → RATE_LIMIT_OR_HTML_RESPONSE',
    classifyNewsFailure('GDELT: Unexpected token \'P\', "Please li"') === 'RATE_LIMIT_OR_HTML_RESPONSE');

  // 4. normalizeNewsProviderName — handles rss:provider@proxy format
  check('normalizeNewsProviderName: "rss:newsbtc@codetabs" → "NewsBTC"',
    normalizeNewsProviderName('rss:newsbtc@codetabs') === 'NewsBTC');
  check('normalizeNewsProviderName: "rss:bitcoinist@codetabs" → "Bitcoinist"',
    normalizeNewsProviderName('rss:bitcoinist@codetabs') === 'Bitcoinist');
  check('normalizeNewsProviderName: "gdelt" → "GDELT"',
    normalizeNewsProviderName('gdelt') === 'GDELT');

  // 5. buildEvidenceLedNewsQueries detects exchange outflow
  const mockPack = {
    date: '2026-05-12', wallets_checked: 74,
    large_transfers: [{
      from: 'rUPBIT', to: 'rRECV001', amount: 6800000,
      sender_label: 'UPBIT_1.2B', receiver_label: 'UNKNOWN',
      classification: 'EXCHANGE_OUTFLOW', confidence: 'HIGH'
    }],
    receiver_followthrough: [{ address: 'rRECV001abc', forwarded_large_count: 0, balance_xrp: 1200 }],
    risk_score: { score: 100, label: 'BLACK / EXTREME', drivers: [] },
    news_intel: { items: [
      { title: 'Ripple XRP custody deal announced', source: 'NewsBTC',
        url: 'https://newsbtc.example/ripple-custody', _priority: 1 }
    ], source_status: {}, source_breakdown: { 'NewsBTC': 1 } }
  };
  const triggers = classifyLedgerNewsNeeds(mockPack);
  check('classifyLedgerNewsNeeds: detects LARGE_EXCHANGE_OUTFLOW',
    triggers.includes('LARGE_EXCHANGE_OUTFLOW'));

  const queries = buildEvidenceLedNewsQueries(mockPack);
  check('buildEvidenceLedNewsQueries: returns array', Array.isArray(queries));
  check('buildEvidenceLedNewsQueries: includes XRP/Ripple baseline',
    queries.some(q => /xrp|ripple|rlusd/i.test(q.query)));
  check('buildEvidenceLedNewsQueries: UPBIT outflow creates UPBIT query',
    queries.some(q => /upbit/i.test(q.query)));
  check('buildEvidenceLedNewsQueries: all queries are ≤5 words',
    queries.every(q => q.query.split(/\s+/).length <= 6));

  // 6. fetchEvidenceLedNews: returns structured object even if all providers fail
  // In test environment fetch is mocked — it will fail cleanly
  const fetchPromise = fetchEvidenceLedNews([
    { query: 'XRP Ripple', reason: 'test', trigger: 'BASELINE', priority: 1 }
  ]).then(res => {
    check('fetchEvidenceLedNews: returns array even on provider failure',
      Array.isArray(res));
  }).catch(() => {
    check('fetchEvidenceLedNews: returns array even on provider failure', true);
  });

  // 7. Public report does NOT contain source degradation language
  const storyText = buildMorningStoryText(mockPack);
  check('Morning Story does not contain "degraded"',
    !/\bdegraded\b/i.test(storyText));
  check('Morning Story does not mention failed providers by name',
    !/CoinTelegraph\s+failed|GDELT\s+failed|Decrypt\s+failed/i.test(storyText));
  check('Morning Story does not contain "Source note:"',
    !/Source note:/i.test(storyText));
  check('Morning Story does not contain "failed providers:"',
    !/failed\s+providers:/i.test(storyText));
  // v3.31-hotfix1h: SOURCES section now governor-gated (REAL NEWS clearance required).
  // Either: SOURCES section appears (when governor cleared) OR is absent (when not).
  const _v1hSrcCleared24 = !!(window.MORNING_NEWS_GOVERNOR &&
    window.MORNING_NEWS_GOVERNOR.publicSourcesCleared(mockPack));
  if (_v1hSrcCleared24) {
    check('Morning Story has SOURCES section when governor cleared real news',
      /\bSOURCES\b/.test(storyText));
  } else {
    check('Morning Story has no SOURCES section when governor not cleared',
      !/\nSOURCES\n/.test(storyText) && !/\n\nSOURCES\s*$/.test(storyText));
  }

  // 8. Structured report (buildXRPMainReport) has no Section 12 SOURCE NOTE
  const structuredTxt = buildXRPMainReport(mockPack);
  check('Structured report has no "12. SOURCE NOTE"',
    !/12\.\s+SOURCE NOTE/i.test(structuredTxt));
  check('Structured report has no "External news coverage degraded"',
    !/External news coverage degraded/.test(structuredTxt));

  // v3.26-hotfix4: HTML report viewer never injects the cmd-source-warning banner
  if (typeof buildMorningStoryHtml === 'function') {
    try {
      const html = buildMorningStoryHtml(mockPack);
      check('Morning Story HTML: no "cmd-source-warning" banner injection',
        !/cmd-source-warning/.test(html));
      check('Morning Story HTML: no "External news coverage degraded" string',
        !/External news coverage degraded/.test(html));
      check('Morning Story HTML: no "Source note:" label',
        !/Source note:/.test(html));
    } catch (_) {
      // buildMorningStoryHtml may need extra fields — just skip if it throws
    }
  }

  // 9. News Router export exists
  const mockRouter = {
    generated_at: '2026-05-12T00:00:00Z',
    evidence_triggers: ['LARGE_EXCHANGE_OUTFLOW'],
    query_intents: [{ query: 'XRP Ripple', reason: 'baseline', trigger: 'BASELINE' }],
    searched_queries: [], failed_queries: [], evidence_results: [], source_limits: []
  };
  const routerTxt = _newsRouterToText(mockRouter);
  check('_newsRouterToText produces non-empty output', routerTxt.length > 20);
  check('_newsRouterToText includes LEDGER TRIGGERS', /LEDGER TRIGGERS/i.test(routerTxt));

  // 10. Report Desk has news-router row
  const rdList = document.getElementById('reportDeskList');
  check('Report Desk has news-router row',
    rdList && !!rdList.querySelector('[data-kind="news-router"]'));

  // 11. _resolveReportSource handles news-router
  const src = _resolveReportSource('news-router');
  check('_resolveReportSource handles news-router kind', src && src.ext === 'txt');

  // 12. WATCHLIST not mutated
  const wBefore = JSON.stringify(Object.keys(KNOWN).slice(0, 5));
  try { _initDiscoveryState(); runAutoWalletDiscovery(mockPack); } catch (_) {}
  const wAfter = JSON.stringify(Object.keys(KNOWN).slice(0, 5));
  check('WATCHLIST not mutated by discovery', wBefore === wAfter);

  // 13. Morning Story opening direction correct for outflow pack
  // v3.26-hotfix7: slice extended to 16 lines because the new branded header
  // takes ~11 lines before the opening paragraph starts.
  const outflowPack = { ...mockPack, total_balance_delta_xrp: -3110000, xrp_price: 1.46 };
  const outflowStory = buildMorningStoryText(outflowPack);
  check('Morning Story opening says "out" or "outflow" for negative net delta',
    /pushed out|net outflow|outflow|took out/i.test(outflowStory.split('\n').slice(0,16).join('\n')));

  // 14. No stale v3.23 in visible strings
  check('No stale v3.23 in <title>', !/v3\.23/.test(document.title));
  check('No stale v3.23 in hudVersion',
    !/v3\.23/.test(document.getElementById('hudVersion')?.textContent || ''));

  // 15. GDELT queries are now short (≤5 words)
  check('GDELT_QUERIES are short (≤5 words each)',
    GDELT_QUERIES.every(q => q.split(/\s+/).length <= 5));

  // 16. Prior smoke tests still exposed
  ['morningStoryNewsRouterSmokeTest', 'shadowMemoryReviewSmokeTest',
   'newsDoctorAutoDiscoverySmokeTest', 'reportIntelPolishSmokeTest',
   'reportIntelSourcesSmokeTest', 'screenRouterSmokeTest',
   'shadowReportDeskSmokeTest', 'shadowHolderDominanceSmokeTest',
   'shadowRelatedOfferSmokeTest'
  ].forEach(fn => {
    check(fn + ' still exposed', typeof window[fn] === 'function');
  });

  const summary = '\n[Shadow Watch v3.24 news-after-ledger smoke test] ' +
    pass + ' passed, ' + fail + ' failed of ' + (pass + fail) + ' checks';
  console.log(summary);
  results.forEach(r => console.log('  ' + r));
  return { pass, fail, total: pass + fail, results, summary };
}
