// ═══════════════════════════════════════════════════════════════
//  v3.26 SMOKE TEST — shadowWatchNewsIntelHardeningSmokeTest
//
//  Validates: transport_ok vs content_ok split, public_usable gate,
//  evidence_led_usable gate, headline-trigger matching, shared newsMode,
//  public report gating, session suppression memory, source ranking.
// ═══════════════════════════════════════════════════════════════
function shadowWatchNewsIntelHardeningSmokeTest() {
  const results = []; let pass = 0, fail = 0;
  const check = (name, cond) => {
    if (cond) { pass++; results.push('✓ ' + name); }
    else      { fail++; results.push('✗ ' + name); }
  };

  // 1. Version
  check('APP_VERSION = v3.32a-helper-runtime-proof-lock',
    APP_VERSION === 'v3.32a-helper-runtime-proof-lock');
  check('hudVersion contains v3.28',
    /v3.32a-helper-runtime-proof-lock/.test(document.getElementById('hudVersion')?.textContent || ''));

  // 2. Core v3.26 functions exposed
  check('computeNewsHealth is a function',        typeof computeNewsHealth === 'function');
  check('attachNewsHealthToPack is a function',   typeof attachNewsHealthToPack === 'function');
  check('buildProviderTruthStatus is a function', typeof buildProviderTruthStatus === 'function');
  check('matchHeadlineToTrigger is a function',   typeof matchHeadlineToTrigger === 'function');
  check('matchHeadlinesToTriggers is a function', typeof matchHeadlinesToTriggers === 'function');
  check('isNewsUsableForNarrative is a function', typeof isNewsUsableForNarrative === 'function');
  check('isNewsUsableAsContext is a function',    typeof isNewsUsableAsContext === 'function');
  check('classifyNewsSourceRank is a function',   typeof classifyNewsSourceRank === 'function');
  check('TRIGGER_KEYWORDS constant exists',       typeof TRIGGER_KEYWORDS === 'object' && Object.keys(TRIGGER_KEYWORDS).length >= 5);

  // 3. Truth model: empty feed → content_ok=false
  const emptyPack = {
    news_intel: {
      items: [],
      source_status: { gdelt: 'OK', cryptocompare: 'OK', rss_feeds: 'OK', google_news: 'OK' },
      source_breakdown: {}
    }
  };
  const emptyProviders = buildProviderTruthStatus(emptyPack);
  check('Empty feed → GDELT content_ok=false despite status=OK',
    emptyProviders['GDELT'] && emptyProviders['GDELT'].content_ok === false);
  check('Empty feed → no providers have overall_ok=true',
    Object.values(emptyProviders).every(p => p.overall_ok === false || p.usable_count === 0));

  // 4. public_usable=false when only 1 source group
  const oneGroupPack = {
    news_intel: {
      items: [
        { title: 'XRP news', source: 'NewsBTC', url: 'https://newsbtc.com/x1' },
        { title: 'XRP news 2', source: 'NewsBTC', url: 'https://newsbtc.com/x2' },
        { title: 'XRP news 3', source: 'NewsBTC', url: 'https://newsbtc.com/x3' }
      ],
      source_status: { rss_feeds: 'OK' },
      source_breakdown: { 'NewsBTC': 3 }
    }
  };
  const oneGroupHealth = computeNewsHealth(oneGroupPack);
  check('Single source group → public_usable=false',
    oneGroupHealth.public_usable === false);
  check('Single source group → newsMode is PARTIAL or LEDGER_ONLY',
    /PARTIAL_CONTEXT|LEDGER_ONLY/.test(oneGroupHealth.newsMode));

  // 5. Healthy: 2+ groups AND ≥5 headlines
  const healthyPack = {
    news_intel: {
      items: [
        { title: 'XRP whale moves 6M', source: 'NewsBTC', url: 'https://newsbtc.com/1' },
        { title: 'Ripple custody deal', source: 'NewsBTC', url: 'https://newsbtc.com/2' },
        { title: 'XRP ETF news', source: 'Bitcoinist', url: 'https://bitcoinist.com/3' },
        { title: 'Banking custody', source: 'Bitcoinist', url: 'https://bitcoinist.com/4' },
        { title: 'XRPL liquidity', source: 'GDELT', url: 'https://example.com/5' }
      ],
      source_status: { rss_feeds: 'OK', gdelt: 'OK' },
      source_breakdown: { 'NewsBTC': 2, 'Bitcoinist': 2, 'GDELT': 1 }
    },
    news_intelligence_router: { evidence_triggers: ['LARGE_EXCHANGE_OUTFLOW'] }
  };
  const healthyHealth = computeNewsHealth(healthyPack);
  check('Healthy: source_group_count >= 2',
    healthyHealth.source_group_count >= 2);
  check('Healthy: public_usable=true',
    healthyHealth.public_usable === true);
  check('Healthy: newsMode is HEALTHY_CONTEXT or EVIDENCE_LED_CONTEXT',
    /HEALTHY_CONTEXT|EVIDENCE_LED_CONTEXT/.test(healthyHealth.newsMode));

  // 6. Evidence-led: triggers detect ledger-relevant headlines
  const triggerMatch = matchHeadlineToTrigger(
    { title: 'Upbit XRP outflow whale transfer detected' }, 'LARGE_EXCHANGE_OUTFLOW'
  );
  check('Headline-trigger matcher returns hits for relevant text',
    triggerMatch > 0);
  const unrelatedMatch = matchHeadlineToTrigger(
    { title: 'Bitcoin reaches $100k as Ethereum holds' }, 'LARGE_EXCHANGE_OUTFLOW'
  );
  check('Unrelated headline returns 0 hits',
    unrelatedMatch === 0);

  // 7. matchHeadlinesToTriggers returns matched + unmatched
  const queryIntents = [
    { query: 'XRP Upbit outflow', trigger: 'LARGE_EXCHANGE_OUTFLOW', priority: 1 },
    { query: 'XRPL AMM RLUSD', trigger: 'AMM_LIQUIDITY_CHANGE', priority: 2 }
  ];
  const matchResult = matchHeadlinesToTriggers(healthyPack.news_intel.items, queryIntents);
  check('matchHeadlinesToTriggers returns object with matched + unmatched',
    matchResult && Array.isArray(matchResult.matched) && Array.isArray(matchResult.unmatched));
  check('LARGE_EXCHANGE_OUTFLOW trigger matches XRP whale headline',
    matchResult.matched.some(m => m.intent.trigger === 'LARGE_EXCHANGE_OUTFLOW'));

  // 8. isNewsUsableForNarrative — gates HEALTHY only
  check('isNewsUsableForNarrative=false for empty pack',
    isNewsUsableForNarrative({}) === false);
  check('isNewsUsableForNarrative=true for healthy pack',
    isNewsUsableForNarrative(healthyPack) === true);
  check('isNewsUsableForNarrative=false for single-group pack',
    isNewsUsableForNarrative(oneGroupPack) === false);

  // 9. Public report does NOT mention degraded providers in body
  const degradedMockPack = {
    date: '2026-05-12', xrp_price: 1.46, total_balance_delta_xrp: -3110000,
    wallets_checked: 74, shadow_volume_xrp: 8500000,
    large_transfers: [{ from: 'rUPBIT', to: 'rRECV', amount: 4500000,
      sender_label: 'UPBIT_1.2B', receiver_label: 'UNKNOWN',
      classification: 'EXCHANGE_OUTFLOW', confidence: 'HIGH' }],
    receiver_followthrough: [],
    risk_score: { score: 100, label: 'BLACK / EXTREME', drivers: [] },
    news_intel: {
      items: [{ title: 'NewsBTC XRP price moves', source: 'NewsBTC', url: 'https://newsbtc.com/x' }],
      source_status: { rss_feeds: 'OK' },
      source_breakdown: { 'NewsBTC': 1 }
    }
  };
  attachNewsHealthToPack(degradedMockPack);
  const degradedReport = buildXRPMainReport(degradedMockPack);
  check('Degraded report: NO "GDELT failed" mention',
    !/GDELT\s+failed|CoinDesk\s+failed|CoinTelegraph\s+failed/i.test(degradedReport));
  check('Degraded report: NO "CORS" / "proxy" in public body',
    !/CORS|proxy.*failed/i.test(degradedReport));
  check('Degraded report: NO "degraded providers" in public body',
    !/degraded providers|Failed providers/i.test(degradedReport));

  // 10. Healthy news report DOES say "news backdrop matters" gating
  // The mock healthy pack must have a meaningful XRP headline AND triggers
  healthyPack.date = '2026-05-12';
  healthyPack.xrp_price = 1.46;
  healthyPack.total_balance_delta_xrp = -3110000;
  healthyPack.wallets_checked = 74;
  healthyPack.shadow_volume_xrp = 8500000;
  healthyPack.large_transfers = degradedMockPack.large_transfers;
  healthyPack.receiver_followthrough = [];
  healthyPack.risk_score = degradedMockPack.risk_score;
  attachNewsHealthToPack(healthyPack);
  const healthyReport = buildPublicReport(healthyPack);
  check('Healthy report MAY include "news backdrop matters" line',
    /news backdrop|matters:|Ripple|XRP/.test(healthyReport));

  // 11. IntelBrief / DailyReport share same newsMode
  const briefDegraded = buildIntelBrief(degradedMockPack);
  check('IntelBrief on degraded pack says partial or ledger-only',
    /partial|ledger-only/i.test(briefDegraded));
  check('IntelBrief on degraded pack does NOT say "news backdrop matters"',
    !/news backdrop matters/i.test(briefDegraded));

  // 12. Source rank classification
  check('Ripple.com URL → rank A',
    classifyNewsSourceRank({ title: 'Ripple announces', url: 'https://ripple.com/news', source: 'Ripple' }) === 'A');
  check('XRP headline from NewsBTC → rank B',
    classifyNewsSourceRank({ title: 'XRP whale moves big', source: 'NewsBTC', url: 'https://newsbtc.com/x' }) === 'B');
  check('Pure price hype → rank D',
    classifyNewsSourceRank({ title: 'Crypto pundit says price could reach $20 target', source: 'NewsBTC', url: 'https://newsbtc.com/x' }) === 'D');

  // 13. Session suppression — 3 fails → disabled
  try { sessionStorage.removeItem(NEWS_DOCTOR_SESSION_KEY); } catch (_) {}
  recordNewsDoctorAttempt('TestProvider', false);
  recordNewsDoctorAttempt('TestProvider', false);
  const rec3 = recordNewsDoctorAttempt('TestProvider', false);
  check('Provider disabled after 3 consecutive failures',
    rec3.disabled_for_session === true);
  check('isProviderSessionDisabled returns true after 3 fails',
    isProviderSessionDisabled('TestProvider') === true);
  recordNewsDoctorAttempt('TestProvider', true);
  check('Provider re-enabled after success',
    isProviderSessionDisabled('TestProvider') === false);
  try { sessionStorage.removeItem(NEWS_DOCTOR_SESSION_KEY); } catch (_) {}

  // 14. attachNewsIntentToPack stores matched_articles
  attachNewsIntentToPack(healthyPack);
  check('news_intelligence_router has matched_articles array',
    Array.isArray(healthyPack.news_intelligence_router.matched_articles));
  check('news_intelligence_router has evidence_led_results_count',
    typeof healthyPack.news_intelligence_router.evidence_led_results_count === 'number');
  check('news_intelligence_router has searched_intents',
    Array.isArray(healthyPack.news_intelligence_router.searched_intents));

  // 15. No stale v3.25 in visible strings
  check('No stale v3.25 in <title>', !/v3\.25/.test(document.title));
  check('No stale v3.25 in hudVersion',
    !/v3\.25/.test(document.getElementById('hudVersion')?.textContent || ''));

  // 16. Prior smoke tests still exposed
  ['newsAfterLedgerSmokeTest','morningStoryNewsRouterSmokeTest',
   'shadowMemoryReviewSmokeTest','newsDoctorAutoDiscoverySmokeTest',
   'reportIntelPolishSmokeTest','reportIntelSourcesSmokeTest',
   'screenRouterSmokeTest','shadowReportDeskSmokeTest',
   'shadowHolderDominanceSmokeTest','shadowRelatedOfferSmokeTest'
  ].forEach(fn => {
    check(fn + ' still exposed', typeof window[fn] === 'function');
  });

  const summary = '\n[Shadow Watch v3.26 news-intel-hardening smoke test] ' +
    pass + ' passed, ' + fail + ' failed of ' + (pass + fail) + ' checks';
  console.log(summary);
  results.forEach(r => console.log('  ' + r));
  return { pass, fail, total: pass + fail, results, summary };
}
