    const publicTxt = (typeof buildPublicReport === 'function')
      ? buildPublicReport(fullPack) : '';
    check('Public report does not say "verified owner"',
      !/verified owner/i.test(publicTxt));
    check('Public report does not say "confirmed owner"',
      !/confirmed owner/i.test(publicTxt));

    // Restore inbox
    state.discoveryInbox = saved;
