  const XRPL_LOCKED = '\u{1D5EB}\u{1D5E5}\u{1D5E3}\u{1D5DF}';             // same via codepoints
  const MIXED_XRPL  = '\u{1D5EB}\u{1D5E5}PL';                             // 𝗫𝗥 + ASCII PL

